test('main gradient basis motion generates detached rotated paint with undo', async ({ page }) => {
  const p = newProject();
  p.duration = 6;
  p.layers[0].drawingMode = 'object';
  const a: Vector = {
    id: 'basis-motion',
    kind: 'rectangle',
    x: 100,
    y: 100,
    width: 80,
    height: 80,
    rotation: 0,
    fill: '#ff0000',
    stroke: '#000000',
    strokeWidth: 0,
    points: [],
    gradient: {
      kind: 'radial',
      from: { x: 20, y: 20 },
      to: { x: 40, y: 20 },
      stops: [
        { offset: 0, color: '#ff0000' },
        { offset: 1, color: '#0000ff' },
      ],
    },
  };
  p.layers[0].keys = [
    { frame: 0, shapes: [a] },
    { frame: 4, shapes: [{ ...a, gradient: { ...a.gradient!, transform: [0, 2, -3, 1] } }] },
    { frame: 5, shapes: [] },
  ];
  await page.addInitScript(
    (project) =>
      localStorage.setItem(
        'splash-recovery-v1',
        JSON.stringify({ project, folder: null, manifest: null }),
      ),
    p,
  );
  await page.goto('/');
  await page.getByRole('button', { name: 'Recover changes', exact: true }).click();
  const timeline = (await page.getByLabel('Timeline frames').boundingBox())!;
  await page.mouse.click(timeline.x + 9, timeline.y + 40);
  await page.keyboard.down('Shift');
  await page.mouse.click(timeline.x + 4 * 18 + 9, timeline.y + 40);
  await page.keyboard.up('Shift');
  const read = () =>
    page.evaluate(() => JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  await page.getByRole('button', { name: 'Generate motion in-betweens', exact: true }).click();
  expect(await read()).toEqual(p);
  await page.getByLabel('Motion interpolate gradient basis', { exact: true }).check();
  await page.getByRole('button', { name: 'Generate motion in-betweens', exact: true }).click();
  await expect.poll(async () => (await read()).layers[0].keys.length).toBe(6);
  const after = await read();
  const basis = after.layers[0].keys[2].shapes[0].gradient!.transform!;
  const root = Math.SQRT1_2;
  [1.5 * root, 1.5 * root, -1.5 * root, 2.5 * root].forEach((v, i) =>
    expect(basis[i]).toBeCloseTo(v, 10),
  );
  expect(after.layers[0].keys[0]).toEqual(p.layers[0].keys[0]);
  expect(after.layers[0].keys[4]).toEqual(p.layers[0].keys[1]);
  expect(after.layers[0].keys[5]).toEqual(p.layers[0].keys[2]);
  await page.getByLabel('Drawing stage').focus();
  await page.keyboard.press('Control+z');
  expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');
  expect(await read()).toEqual(after);
});

for (const mode of ['object', 'merge'] as const)
  for (const variant of ['rotated', 'radial-skew', 'mirrored-linear', 'mirrored-radial'] as const)
    test(`gradient basis motion exports ${variant} pixels in ${mode} mode`, async ({ page }) => {
      const project = newProject();
      project.width = project.height = 120;
      project.duration = 6;
      project.fps = 10;
      const shape: Vector = {
        id: 'rotating-gradient',
        kind: 'rectangle',
        x: 20,
        y: 20,
        width: 80,
        height: 80,
        rotation: 0,
        fill: '#ff0000',
        stroke: '#000000',
        strokeWidth: 0,
        points: [],
        gradient: {
          kind: variant.includes('radial') ? 'radial' : 'linear',
          from: { x: 0, y: 0 },
          to: { x: 80, y: 0 },
          stops: [
            { offset: 0, color: '#ff0000' },
            { offset: 1, color: '#0000ff' },
          ],
        },
      };
      const handedness = variant.startsWith('mirrored') ? -1 : 1;
      if (handedness < 0) shape.gradient!.transform = [1, 0, 0, -1];
      const target = structuredClone(shape);
      target.gradient!.transform =
        variant === 'rotated' ? [0, 1, -1, 0] : [2, 0, 1, 3 * handedness];
      project.layers[0].drawingMode = mode;
      project.layers[0].keys = [
        { frame: 0, shapes: [shape] },
        { frame: 4, shapes: [target] },
        { frame: 5, shapes: [] },
      ];
      await page.addInitScript(
        (project) =>
          localStorage.setItem(
            'splash-recovery-v1',
            JSON.stringify({ project, folder: null, manifest: null }),
          ),
        project,
      );
      await page.goto('/');
      await page.getByRole('button', { name: 'Recover changes', exact: true }).click();
      const timeline = (await page.getByLabel('Timeline frames').boundingBox())!;
      await page.mouse.click(timeline.x + 9, timeline.y + 40);
      await page.keyboard.down('Shift');
      await page.mouse.click(timeline.x + 4 * 18 + 9, timeline.y + 40);
      await page.keyboard.up('Shift');
      await page.getByLabel('Motion interpolate gradient basis', { exact: true }).check();
      await page.getByRole('button', { name: 'Generate motion in-betweens', exact: true }).click();
      const downloading = page.waitForEvent('download');
      await exportHtmlFromShortcut(page);
      const files = await readWebDownload(await downloading);
      const out = await page.context().newPage();
      const errors: string[] = [];
      out.on('pageerror', (error) => errors.push(error.message));
      await out.addInitScript(() => {
        let next: FrameRequestCallback;
        window.requestAnimationFrame = (callback) => {
          next = callback; Reflect.set(window, 'exportReady', true);
          return 1;
        };
        Object.assign(window, { renderAt: (time: number) => next(time) });
      });
      await openWebExport(out, files, true); await out.waitForFunction(() => Reflect.get(window, 'exportReady'));
      const pixels = (time: number) =>
        out.evaluate((time) => {
          (window as unknown as { renderAt: (time: number) => void }).renderAt(time);
          const ctx = document.querySelector('canvas')!.getContext('2d')!;
          return [
            [80, 30],
            [30, 80],
          ].map(([x, y]) => [...ctx.getImageData(x, y, 1, 1).data]);
        }, time);
      const near = (actual: number[][], expected: number[][]) =>
        actual.forEach((pixel, i) =>
          pixel.forEach((value, channel) =>
            expect(Math.abs(value - expected[i][channel])).toBeLessThanOrEqual(3),
          ),
        );
      // Independent analytic pixel-center projection, without reading generated matrices.
      const expected = (t: number) =>
        [
          [60.5, 10.5],
          [10.5, 60.5],
        ].map(([x, y]) => {
          let localX: number, localY: number;
          if (variant === 'rotated') {
            const angle = (t * Math.PI) / 2;
            localX = Math.cos(angle) * x + Math.sin(angle) * y;
            localY = -Math.sin(angle) * x + Math.cos(angle) * y;
          } else {
            localY = y / (handedness * (1 + 2 * t));
            localX = (x - t * localY) / (1 + t);
          }
          const fraction = Math.max(
            0,
            Math.min(1, (variant.includes('radial') ? Math.hypot(localX, localY) : localX) / 80),
          );
          return [Math.round(255 * (1 - fraction)), 0, Math.round(255 * fraction), 255];
        });
      near(await pixels(0), expected(0));
      near(await pixels(200), expected(0.5));
      near(await pixels(400), expected(1));
      expect(await pixels(500)).toEqual([
        [255, 255, 255, 255],
        [255, 255, 255, 255],
      ]);
      near(await pixels(600), expected(0));
      expect(errors).toEqual([]);
      await out.close();
    });

