async function openAdvancedMotionTimeline(page: Page, name: string) {
  await page.getByRole('option', { name: `Library item ${name}`, exact: true }).dblclick();
  const advanced = page.getByRole('button', { name: 'Advanced symbol timeline tools…', exact: true });
  const tools = page.getByRole('button', { name: 'Timeline tools…', exact: true });
  await expect(advanced.or(tools)).toBeVisible();
  if (await advanced.isVisible()) await advanced.click();
  await tools.click();
  await expect(page.getByLabel('Symbol timeline preview', { exact: true })).toBeVisible();
}

async function publishAdvancedMotionTimeline(page: Page, read: () => Promise<Project>, before: Project) {
  const editor = page.getByRole('dialog', { name: 'Symbol timeline', exact: true });
  await editor.getByRole('button', { name: 'Undo symbol timeline change', exact: true }).click();
  await editor.getByRole('button', { name: 'Redo symbol timeline change', exact: true }).click();
  await editor.getByRole('button', { name: 'Apply symbol timeline', exact: true }).click();
  expect(await read()).toEqual(before);
  await page.getByRole('button', { name: 'Save and return to scene', exact: true }).click();
}

