for (const drawingMode of ['object', 'merge'] as const)
  test(`remembered basic motion ${drawingMode} preserves history and guards endpoint or interior edits`, async ({
    page,
  }) => {
    const project = newProject();
    project.duration = 6;
    const shape: Vector = {
      id: 'remembered',
      kind: 'rectangle',
      x: 20,
      y: 20,
      width: 20,
      height: 20,
      rotation: 0,
      fill: '#ff0000',
      stroke: '#000000',
      strokeWidth: 0,
      points: [],
    };
    project.layers[0].drawingMode = drawingMode;
    project.layers[0].keys = [
      { frame: 0, shapes: [shape] },
      { frame: 4, shapes: [{ ...shape, x: 100 }] },
      { frame: 5, shapes: [] },
    ];
    await page.addInitScript((project) => {
      if (!localStorage.getItem('splash-recovery-v1'))
        localStorage.setItem(
          'splash-recovery-v1',
          JSON.stringify({ project, folder: null, manifest: null }),
        );
    }, project);
    await page.goto('/');
    await page.getByRole('button', { name: 'Recover changes', exact: true }).click();
    const read = () =>
      page.evaluate(
        () => JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project,
      );
    const frame = async (n: number, shift = false) => {
      const box = (await page.getByLabel('Timeline frames').boundingBox())!;
      if (shift) await page.keyboard.down('Shift');
      await page.mouse.click(box.x + n * 18 + 9, box.y + 40);
      if (shift) await page.keyboard.up('Shift');
    };
    const undo = async () => {
      await page.getByLabel('Drawing stage').focus();
      await page.keyboard.press('Control+z');
    };
    const redo = async () => {
      await page.getByLabel('Drawing stage').focus();
      await page.keyboard.press('Control+Shift+z');
    };
    const move = async () => {
      await page.getByLabel('Drawing stage').focus();
      await page.keyboard.press('Control+a');
      await page.keyboard.press('ArrowRight');
    };
    await frame(0);
    await frame(4, true);
    await page.getByRole('button', { name: 'Create remembered motion', exact: true }).click();
    await expect.poll(async () => (await read()).layers[0].motionSpans?.length).toBe(1);
    const created = await read();
    expect(created.layers[0].keys[2].shapes[0].x).toBe(60);
    await undo();
    expect(await read()).toEqual(project);
    await redo();
    expect(await read()).toEqual(created);
    await frame(4);
    await move();
    await expect.poll(async () => (await read()).layers[0].keys[4].shapes[0].x).toBe(101);
    const edited = await read();
    expect(edited.layers[0].keys[4].shapes[0].x).toBe(101);
    await page.getByRole('button', { name: 'Select remembered frames 1–5', exact: true }).click();
    await page.getByRole('button', { name: 'Refresh remembered motion', exact: true }).click();
    if (drawingMode === 'merge') {
      // The existing merge nudge rebuilds endpoint geometry; basic recipes cannot match it.
      await expect(page.getByRole('alert')).toContainText('same ordered artwork');
      expect(await read()).toEqual(edited);
      await undo();
      expect(await read()).toEqual(created);
      await redo();
      expect(await read()).toEqual(edited);
      await page.getByRole('button', { name: 'Detach remembered motion', exact: true }).click();
      await expect.poll(async () => (await read()).layers[0].motionSpans).toBeUndefined();
      expect((await read()).layers[0].keys).toEqual(edited.layers[0].keys);
      await undo();
      expect(await read()).toEqual(edited);
      return;
    }
    await expect.poll(async () => (await read()).layers[0].keys[2].shapes[0].x).toBe(60.5);
    const refreshed = await read();
    expect(refreshed.layers[0].keys[4]).toEqual(edited.layers[0].keys[4]);
    expect(refreshed.layers[0].keys[5]).toEqual(project.layers[0].keys[2]);
    await undo();
    expect(await read()).toEqual(edited);
    await redo();
    expect(await read()).toEqual(refreshed);
    await page.reload();
    await page.getByRole('button', { name: 'Recover changes', exact: true }).click();
    await frame(2);
    await expect(
      page.getByRole('button', { name: 'Select remembered frames 1–5', exact: true }),
    ).toBeVisible();
    await move();
    await expect.poll(async () => (await read()).layers[0].keys[2].shapes[0].x).toBe(61.5);
    const conflict = await read();
    await page.getByRole('button', { name: 'Select remembered frames 1–5', exact: true }).click();
    await page.getByRole('button', { name: 'Refresh remembered motion', exact: true }).click();
    await expect(
      page.getByText('Generated keys changed; detach the span to preserve those edits.', {
        exact: false,
      }),
    ).toBeVisible();
    expect(await read()).toEqual(conflict);
    await undo();
    expect(await read()).toEqual(refreshed);
    await redo();
    expect(await read()).toEqual(conflict);
    await page.getByRole('button', { name: 'Detach remembered motion', exact: true }).click();
    await expect.poll(async () => (await read()).layers[0].motionSpans).toBeUndefined();
    expect((await read()).layers[0].keys).toEqual(conflict.layers[0].keys);
    await undo();
    expect(await read()).toEqual(conflict);
  });

test('remembered symbol motion isolates base and additional track histories through Cancel and Apply', async ({
  page,
}) => {
  const project = newProject();
  const shape: Vector = {
    id: 'art',
    kind: 'rectangle',
    x: 20,
    y: 20,
    width: 20,
    height: 20,
    rotation: 0,
    fill: '#ff0000',
    stroke: '#000000',
    strokeWidth: 0,
    points: [],
  };
  project.symbols = [
    {
      id: 'span-symbol',
      name: 'Spans',
      width: 200,
      height: 100,
      shapes: [shape],
      timeline: {
        duration: 6,
        keys: [{ frame: 4, shapes: [{ ...shape, x: 100 }] }],
        layers: [
          {
            id: 'extra',
            name: 'Extra',
            visible: true,
            locked: false,
            keys: [
              { frame: 0, shapes: [shape] },
              { frame: 4, shapes: [{ ...shape, x: 100 }] },
            ],
          },
        ],
      },
    },
  ];
  await page.addInitScript(
    (project) =>
      localStorage.setItem(
        'splash-recovery-v1',
        JSON.stringify({ project, folder: null, manifest: null }),
      ),
    project,
  );
  await page.goto('/');
  await page.getByRole('button', { name: 'Recover changes', exact: true }).click();
  const read = () =>
    page.evaluate(() => JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const open = () =>
    page
      .getByRole('group', { name: 'Symbol Spans', exact: true })
      .getByRole('button', { name: 'Edit symbol timeline', exact: true })
      .click();
  const setup = async () => {
    await page.getByLabel('Symbol range start', { exact: true }).fill('1');
    await page.getByLabel('Symbol range end', { exact: true }).fill('5');
    await page.getByRole('button', { name: 'Select all symbol tracks', exact: true }).click();
    await page.getByLabel('Remembered motion on checked symbol tracks', { exact: true }).check();
  };
  await open();
  await setup();
  await page.getByRole('button', { name: 'Create remembered symbol motion', exact: true }).click();
  const select = page.getByRole('button', {
    name: 'Select remembered symbol frames 1–5',
    exact: true,
  });
  await expect(select).toBeVisible();
  expect(await read()).toEqual(project);
  await page.getByRole('button', { name: 'Undo symbol timeline change', exact: true }).click();
  await expect(select).toHaveCount(0);
  await page.getByRole('button', { name: 'Redo symbol timeline change', exact: true }).click();
  await expect(select).toBeVisible();
  await page.getByRole('button', { name: 'Cancel symbol timeline', exact: true }).click();
  expect(await read()).toEqual(project);
  await open();
  await setup();
  await page.getByRole('button', { name: 'Create remembered symbol motion', exact: true }).click();
  await page.getByRole('button', { name: 'Apply symbol timeline', exact: true }).click();
  const saved = await read();
  expect(saved.symbols![0].timeline!.motionSpans).toHaveLength(1);
  expect(saved.symbols![0].timeline!.layers![0].motionSpans).toHaveLength(1);
  expect(saved.symbols![0].timeline!.keys[1].shapes[0].x).toBe(60);
  await open();
  await setup();
  await select.click();
  await page.getByRole('button', { name: 'Refresh remembered symbol motion', exact: true }).click();
  await page.getByRole('button', { name: 'Detach remembered symbol motion', exact: true }).click();
  await expect(select).toHaveCount(0);
  await page.getByRole('button', { name: 'Undo symbol timeline change', exact: true }).click();
  await expect(select).toBeVisible();
  await page.getByRole('button', { name: 'Redo symbol timeline change', exact: true }).click();
  await page.getByRole('button', { name: 'Apply symbol timeline', exact: true }).click();
  const detached = await read();
  expect(detached.symbols![0].timeline!.motionSpans).toBeUndefined();
  expect(detached.symbols![0].timeline!.layers![0].motionSpans).toBeUndefined();
  expect(detached.symbols![0].timeline!.keys).toEqual(saved.symbols![0].timeline!.keys);
});

for (const editor of ['main', 'symbol'] as const)
  test(`${editor} automatic remembered endpoints share history and preserve conflicted edits`, async ({
    page,
  }) => {
    const project = newProject();
    project.duration = 6;
    const shape: Vector = {
      id: 'art',
      kind: 'rectangle',
      x: 20,
      y: 20,
      width: 20,
      height: 20,
      rotation: 0,
      fill: '#ff0000',
      stroke: '#000000',
      strokeWidth: 0,
      points: [],
    };
    const keys = [
      { frame: 0, shapes: [shape] },
      { frame: 4, shapes: [{ ...shape, x: 100 }] },
    ];
    project.layers[0].keys = keys;
    if (editor === 'symbol')
      project.symbols = [
        {
          id: 'auto',
          name: 'Auto',
          width: 200,
          height: 100,
          shapes: [shape],
          timeline: { duration: 6, keys: keys.slice(1) },
        },
      ];
    await page.addInitScript(
      (project) =>
        localStorage.setItem(
          'splash-recovery-v1',
          JSON.stringify({ project, folder: null, manifest: null }),
        ),
      project,
    );
    await page.goto('/');
    await page.getByRole('button', { name: 'Recover changes', exact: true }).click();
    const read = () =>
      page.evaluate(
        () => JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project,
      );
    const open = () =>
      page
        .getByRole('group', { name: 'Symbol Auto', exact: true })
        .getByRole('button', { name: 'Edit symbol timeline', exact: true })
        .click();
    if (editor === 'symbol') await open();
    const range = async (start: number, end: number) => {
      if (editor === 'symbol') {
        await page.getByLabel('Symbol range start', { exact: true }).fill(String(start + 1));
        await page.getByLabel('Symbol range end', { exact: true }).fill(String(end + 1));
      } else {
        const box = (await page.getByLabel('Timeline frames').boundingBox())!;
        await page.mouse.click(box.x + start * 18 + 9, box.y + 40);
        if (start !== end) {
          await page.keyboard.down('Shift');
          await page.mouse.click(box.x + end * 18 + 9, box.y + 40);
          await page.keyboard.up('Shift');
        }
      }
    };
    const move = async () => {
      if (editor === 'symbol') {
        await page.getByLabel('Edit symbol frame-range artwork', { exact: true }).check();
        await page
          .getByRole('button', { name: 'Select all symbol range artwork', exact: true })
          .click();
        await page.getByLabel('Symbol multi-frame X offset', { exact: true }).fill('2');
        await page.getByLabel('Symbol multi-frame Y offset', { exact: true }).fill('0');
        await page.getByRole('button', { name: 'Move symbol range artwork', exact: true }).click();
      } else {
        await page.getByLabel('Drawing stage').focus();
        await page.keyboard.press('Control+a');
        await page.keyboard.press('ArrowRight');
        await page.keyboard.press('ArrowRight');
      }
    };
    const undo = async (redo = false) => {
      if (editor === 'symbol')
        await page
          .getByRole('button', {
            name: `${redo ? 'Redo' : 'Undo'} symbol timeline change`,
            exact: true,
          })
          .click();
      else {
        await page.getByLabel('Drawing stage').focus();
        await page.keyboard.press(redo ? 'Control+Shift+z' : 'Control+z');
      }
    };
    await range(0, 4);
    await page
      .getByRole('button', {
        name: editor === 'main' ? 'Create remembered motion' : 'Create remembered symbol motion',
        exact: true,
      })
      .click();
    await page
      .getByLabel(
        editor === 'main'
          ? 'Automatically refresh remembered endpoints this session'
          : 'Automatically refresh remembered symbol endpoints this session',
        { exact: true },
      )
      .check();
    await range(4, 4);
    await move();
    await undo();
    if (editor === 'main') {
      expect((await read()).layers[0].keys[4].shapes[0].x).toBe(101);
      expect((await read()).layers[0].keys[2].shapes[0].x).toBe(60.5);
    }
    await undo(true);
    if (editor === 'symbol') {
      expect(await read()).toEqual(project);
      await page.getByRole('button', { name: 'Apply symbol timeline', exact: true }).click();
    }
    const after = await read();
    const actual =
      editor === 'main'
        ? after.layers[0].keys
        : [{ frame: 0, shapes: after.symbols![0].shapes }, ...after.symbols![0].timeline!.keys];
    expect(actual[4].shapes[0].x).toBe(102);
    expect(actual[2].shapes[0].x).toBe(61);
    if (editor === 'symbol') {
      await open();
      await expect(
        page.getByLabel('Automatically refresh remembered symbol endpoints this session', {
          exact: true,
        }),
      ).not.toBeChecked();
      await page
        .getByLabel('Automatically refresh remembered symbol endpoints this session', {
          exact: true,
        })
        .check();
    }
    await range(2, 2);
    await move();
    await range(4, 4);
    await move();
    await expect(page.getByRole('alert')).toContainText(
      'Endpoint edit kept; automatic motion refresh failed',
    );
    if (editor === 'symbol')
      await page.getByRole('button', { name: 'Apply symbol timeline', exact: true }).click();
    const conflicted = await read();
    const final =
      editor === 'main'
        ? conflicted.layers[0].keys
        : [
            { frame: 0, shapes: conflicted.symbols![0].shapes },
            ...conflicted.symbols![0].timeline!.keys,
          ];
    expect(final[4].shapes[0].x).toBe(104);
    expect(final[2].shapes[0].x).toBe(63);
    expect(final[1]).toEqual(actual[1]);
  });

