for(const mode of ['success','failure','cancel'] as const)test(`streamed PNG file ${mode} commits only a complete archive`,async({page})=>{
  const project=newProject();project.duration=3;project.width=32;project.height=24;
  await page.addInitScript(({project,mode})=>{
    localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));
    const state={chunks:[] as number[][],closed:false,aborted:false,writes:0};
    Object.assign(window,{pngFileState:state,showSaveFilePicker:async()=>({createWritable:async()=>({
      write:async(blob:Blob)=>{state.writes++;if(state.writes===3){if(mode==='failure')throw new Error('disk full');if(mode==='cancel'){document.documentElement.dataset.fileWrite='stalled';await new Promise(()=>{});}}
        state.chunks.push([...new Uint8Array(await blob.arrayBuffer())]);},
      close:async()=>{state.closed=true;},abort:async()=>{state.aborted=true;state.chunks=[];}
    })})});
  },{project,mode});
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const before=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await openExportSettings(page);await page.getByRole('button',{name:'Save PNG sequence ZIP to file…',exact:true}).click();
  if(mode==='cancel'){await expect(page.locator('html')).toHaveAttribute('data-file-write','stalled');await page.getByRole('button',{name:'Cancel PNG export',exact:true}).click();}
  if(mode==='success')await expect(page.getByText('Saved 3 PNG frames at 24 fps · buttons in Up state',{exact:true})).toBeVisible();
  else if(mode==='failure')await expect(page.getByRole('alert')).toContainText('disk full');
  else await expect(page.getByText('PNG export cancelled',{exact:true})).toBeVisible();
  await expect(page.locator('iframe[title="PNG frame renderer"]')).toHaveCount(0);
  const state=await page.evaluate(()=>(window as unknown as {pngFileState:{chunks:number[][];closed:boolean;aborted:boolean}}).pngFileState);
  expect(state.closed).toBe(mode==='success');expect(state.aborted).toBe(mode!=='success');
  if(mode==='success'){const bytes=Uint8Array.from(state.chunks.flat()),view=new DataView(bytes.buffer);expect(view.getUint32(bytes.length-22,true)).toBe(0x06054b50);expect(view.getUint16(bytes.length-12,true)).toBe(4);expect(view.getUint32(bytes.length-42,true)).toBe(0x07064b50);expect(new TextDecoder().decode(bytes)).toContain('frame-000003.png');}
  else expect(state.chunks).toEqual([]);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);
});


