test('compiler worker compiles TypeScript and recovers after deadline and cancellation',async({page})=>{
  const compiler=await fs.readFile('packages/scripting/src/compile.ts','utf8');
  const frameTypes=await fs.readFile('packages/scripting/src/frame-types.ts','utf8');
  const worker=await fs.readFile('packages/scripting/src/compile-worker.ts','utf8');
  const tsLibrary=await fs.readFile('node_modules/typescript/lib/typescript.js','utf8');
  const es5=await fs.readFile('node_modules/typescript/lib/lib.es5.d.ts','utf8');
  const workerBundle=await transformWithEsbuild(frameTypes.replace(/export /g,'')+'\n'+compiler.replace(/^import[^\n]+\n/gm,'').replace(/export /g,'')+'\n'+worker.replace(/^import[^\n]+\n/gm,''),'compiler-test.ts',{loader:'ts',target:'es2022'});
  let stall=false;
  await page.route('**/compiler-test-worker.js',route=>route.fulfill({contentType:'text/javascript',body:stall?'while(true){}':tsLibrary+'\nconst es5Library = '+JSON.stringify(es5)+';\n'+workerBundle.code}));
  const host=await fs.readFile('packages/scripting/src/compile-async.ts','utf8');
  const hostBundle=await transformWithEsbuild(host.replace(/^import[^\n]+\n/gm,'').replace(/export /g,'').replace("new URL('./compile-worker.ts',import.meta.url)","new URL('/compiler-test-worker.js',location.href)")+'\nObject.assign(window,{compileFrameSourceAsync});','compiler-host.ts',{loader:'ts',target:'es2022'});
  await page.goto('/');await page.addScriptTag({content:hostBundle.code});
  const run=async(mode:string)=>page.evaluate(async mode=>{
    const api=window as unknown as {compileFrameSourceAsync:typeof import('../../packages/scripting/src/compile-async').compileFrameSourceAsync};
    const controller=new AbortController();
    if(mode==='cancel')setTimeout(()=>controller.abort(),50);
    try{return await api.compileFrameSourceAsync(mode==='semantic'?'timeline.gotoAndStop(\"wrong\");':mode==='syntax'?'const n: = 1;':'const n: number = 3; state.n=n; throw new Error("not evaluated");',{signal:controller.signal,timeoutMs:mode==='timeout'?100:10000});}
    catch(error){return {error:String(error)};}
  },mode);
  const compiled=await run('success');expect(compiled).toMatchObject({diagnostics:[]});expect('body' in compiled&&compiled.body).toContain('const n = 3;');
  expect(await run('syntax')).toMatchObject({diagnostics:[expect.objectContaining({line:1})]});
  expect(await run('semantic')).toMatchObject({diagnostics:[expect.objectContaining({code:2345,line:1})]});
  stall=true;
  expect(await run('timeout')).toMatchObject({error:expect.stringContaining('timed out')});
  expect(await run('cancel')).toMatchObject({error:expect.stringContaining('AbortError')});
  stall=false;expect(await run('success')).toMatchObject({diagnostics:[]});
});


for(const mode of ['diagnostics','cancel','failure'] as const)
  test(`shipped TypeScript scratchpad ${mode} uses bundled disposable workers`,async({page})=>{
    const workers:string[]=[];let closed=0;
    page.on('worker',worker=>{if(!worker.url().includes('compile-worker'))return;workers.push(worker.url());worker.on('close',()=>closed++);});
    await page.goto('/');
    const tabBefore=await page.locator('.document-tab').innerText();
    await page.getByRole('button',{name:'Control',exact:true}).click();
    await page.getByRole('button',{name:'Check frame TypeScript…',exact:true}).click();
    const dialog=page.getByRole('dialog',{name:'Check frame TypeScript',exact:true});
    const source=sourceEditor(dialog);
    const check=dialog.getByRole('button',{name:'Check TypeScript',exact:true});
    if(mode==='diagnostics'){
      await fillSource(source, 'const n: number = 1;\ntimeline.gotoAndStop(false);');await check.click();
      const diagnostic=dialog.getByRole('button',{name:/Line 2, column/});await expect(diagnostic).toBeVisible();await diagnostic.click();
      await expect(dialog.locator('.monaco-editor .selected-text')).toBeVisible();
      await fillSource(source, 'throw new Error("source must not run");');await check.click();
      await expect(dialog.getByRole('status')).toHaveText('No type errors. Source was not executed.');
    }else if(mode==='cancel'){
      await page.route('**/assets/compile-worker-*.js',route=>route.fulfill({contentType:'text/javascript',body:'while(true){}'}));
      await check.click();await expect.poll(()=>workers.length).toBe(1);
      await dialog.getByRole('button',{name:'Cancel compilation'}).click();
      await expect(dialog.getByRole('status')).toHaveText('Compilation cancelled.');
      await expect.poll(()=>closed).toBe(1);
      await check.click();await expect.poll(()=>workers.length).toBe(2);
      await fillSource(source, 'timeline.stop();');await expect.poll(()=>closed).toBe(2);
      await expect(dialog.locator('p[role="status"]')).toBeEmpty();
      await check.click();await expect.poll(()=>workers.length).toBe(3);
      await dialog.getByRole('button',{name:'Close dialog'}).click();await expect.poll(()=>closed).toBe(3);
      await page.unroute('**/assets/compile-worker-*.js');
      await page.getByRole('button',{name:'Control',exact:true}).click();
      await page.getByRole('button',{name:'Check frame TypeScript…',exact:true}).click();
      await expectSource(source,'timeline.stop();');
      await check.click();await expect(dialog.getByRole('status')).toHaveText('No type errors. Source was not executed.');
    }else{
      await page.route('**/assets/compile-worker-*.js',route=>route.fulfill({contentType:'text/javascript',body:'throw new Error("load failure");'}));
      await check.click();await expect(dialog.getByRole('status')).toHaveText('Compiler worker failed.');
      await page.unroute('**/assets/compile-worker-*.js');
      await check.click();await expect(dialog.getByRole('status')).toHaveText('No type errors. Source was not executed.');
    }
    await expect.poll(()=>closed).toBe(workers.length);
    expect(workers.every(url=>/assets\/compile-worker-[^/]+\.js$/.test(url))).toBe(true);
    expect(workers.length).toBeGreaterThan(0);
    expect(await page.locator('.document-tab').innerText()).toBe(tabBefore);
  });


for(const mode of ['seek-stop','same-frame','loop','rollback'] as const)
 test(`entry script dispatch ${mode} preserves checkpoint and bounded entry semantics`,async({page})=>{
  const files=await Promise.all(['timeline','isolated-frame','session'].map(name=>fs.readFile('packages/scripting/src/'+name+'.ts','utf8')));
  const input=files.map(source=>source.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,'')+'\nObject.assign(window,{createScriptSession});';
  const bundle=await transformWithEsbuild(input,'entry-session-test.ts',{loader:'ts',target:'es2022',minify:true});
  await page.goto('/');await page.addScriptTag({content:bundle.code});
  const result=await page.evaluate(async mode=>{
    const api=window as unknown as {createScriptSession:typeof import('../../packages/scripting/src/session').createScriptSession};
    const sources=mode==='seek-stop'?[
      {frame:0,source:'state.frames.push(0); timeline.gotoAndPlay(2);'},
      {frame:2,source:'state.frames.push(2); timeline.gotoAndStop(3);'},
      {frame:3,source:'state.frames.push(3); timeline.stop();'},
    ]:mode==='same-frame'?[{frame:0,source:'state.frames.push(0); timeline.gotoAndStop(0);'}]:
      mode==='rollback'?[{frame:0,source:'state.frames.push(0); timeline.gotoAndStop(2);'},
        {frame:2,source:'state.frames.push(2); throw new Error("entry failure");'}]:
        [{frame:0,source:'state.frames.push(0);'}];
    const session=api.createScriptSession({duration:mode==='loop'?1:4,fps:24,seed:3},sources,{frames:[]},'entry');
    const initial=session.checkpoint();
    if(mode==='rollback'){
      let error='';try{await session.run(2);}catch(e){error=String(e);}
      return {initial,after:session.checkpoint(),error};
    }
    const first=await session.run(1),cut=session.checkpoint();
    const after=await session.run(4);
    session.restore(JSON.parse(JSON.stringify(cut)));
    const replay=await session.run(4);
    return {first,after,replay};
  },mode);
  if(mode==='rollback'){expect(result.after).toEqual(result.initial);expect(result.error).toContain('entry failure');}
  else{
    expect(result.after).toEqual(result.replay);expect(result.after?.timeline.tick).toBe(5);
    if(mode==='seek-stop'){
      expect(result.first?.timeline.frame).toBe(2);expect(result.first?.entryPending).toBe(true);
      expect(result.after?.state.frames).toEqual([0,2,3]);expect(result.after?.entryPending).toBe(false);
      expect(result.after?.timeline).toMatchObject({frame:3,playing:false});
    }else{expect(result.after?.state.frames).toEqual([0,0,0,0,0]);expect(result.after?.entryPending).toBe(true);}
  }
  await expect(page.locator('iframe[title="Isolated script frame"]')).toHaveCount(0);
 });


