  await d.getByRole('button',{name:'Deliver next key and step',exact:true}).click();await expect(d.getByRole('status')).toContainText(fault==='script'?'key failed':'Artwork encoding failed');
  await expect(d.getByLabel('Queued keyboard inputs')).toContainText('2 keyboard');await expect(d.getByLabel('Script preview state')).toContainText('keydown:a;keyup:a;');
  expect(await d.getByAltText('Script preview artwork').getAttribute('src')).toBe(image);
  await page.evaluate(()=>Object.assign(window,{keyRenderFault:false}));await d.getByRole('button',{name:'Clear queued keys',exact:true}).click();
  await d.getByLabel('Script input JSON').press('z');await expect(d.getByLabel('Queued keyboard inputs')).toContainText('0 keyboard');
  if(fault==='script'){
    await target.press('Control+z');await expect(d.getByLabel('Queued keyboard inputs')).toContainText('4 keyboard');
    await expect(d.getByLabel('Next keyboard input')).toContainText('"ctrlKey": true');
    await d.getByRole('button',{name:'Clear queued keys',exact:true}).click();
  }
  await target.press('Tab');await expect(d.getByLabel('Queued keyboard inputs')).toContainText('0 keyboard');
  await target.dispatchEvent('keydown',{key:'r',code:'KeyR',repeat:true});await target.dispatchEvent('keydown',{key:'c',code:'KeyC',isComposing:true});
  await expect(d.getByLabel('Queued keyboard inputs')).toContainText('0 keyboard');
  await target.evaluate(element=>{for(let i=0;i<65;i++)element.dispatchEvent(new KeyboardEvent('keydown',{key:'q',code:'KeyQ',bubbles:true}));});
