  await d.getByRole('button',{name:'Deliver next pointer and step',exact:true}).click();await expect(d.getByRole('status')).toHaveText('Completed 1 script tick.');
  packet=JSON.parse(await d.getByLabel('Next pointer input').innerText());expect(packet.x).toBeLessThan(0);expect(packet.type).toBe('pointerup');
  await d.getByRole('button',{name:'Deliver next pointer and step',exact:true}).click();await expect(d.getByRole('status')).toHaveText('Completed 1 script tick.');
  await d.getByRole('button',{name:'Capture script checkpoint',exact:true}).click();
  await d.getByRole('button',{name:'Replay retained script history',exact:true}).click();await expect(d.getByRole('status')).toContainText('2 JSON inputs replayed.');
  const oldState=await d.getByLabel('Script preview state').innerText(),oldImage=await image.getAttribute('src');
  await image.click({modifiers:['Shift']});if(fault==='render')await page.evaluate(()=>Object.assign(window,{pointerFault:true}));
  await d.getByRole('button',{name:'Deliver next pointer and step',exact:true}).click();await expect(d.getByRole('status')).toContainText(fault==='script'?'pointer failed':'Artwork encoding failed');
  await expect(d.getByLabel('Queued pointer inputs')).toContainText('2 pointer');await expect(d.getByLabel('Script preview state')).toHaveText(oldState);expect(await image.getAttribute('src')).toBe(oldImage);
  await page.evaluate(()=>Object.assign(window,{pointerFault:false}));await d.getByRole('button',{name:'Clear queued pointers',exact:true}).click();
  await d.getByRole('application',{name:'Script pointer target'}).evaluate(element=>{for(let i=0;i<65;i++)element.dispatchEvent(new PointerEvent('pointercancel',{pointerId:i,clientX:10,clientY:10,bubbles:true}));});
  await expect(d.getByLabel('Queued pointer inputs')).toContainText('64 pointer');await expect(d.getByLabel('Capture pointers on artwork')).not.toBeChecked();
  await d.getByRole('button',{name:'Restore script checkpoint',exact:true}).click();await expect(d.getByLabel('Queued pointer inputs')).toContainText('0 pointer');
  await d.getByRole('button',{name:'Close dialog',exact:true}).click();await expect(page.locator('iframe')).toHaveCount(0);
