  const leaf:Vector={...art,id:'leaf-instance',kind:'symbol',symbolId:'leaf',symbolPlayback:{mode:'movie',firstFrame:0}};
  p.symbols=[{id:'leaf',name:'Leaf',width:30,height:30,shapes:[art],timeline:{duration:3,keys:[{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]}]}},
    {id:'button',name:'Button',width:30,height:30,shapes:[leaf],timeline:{duration:2,keys:[{frame:1,shapes:[{...art,fill:'#ffff00'}]}]},buttonStates:{up:0,over:1,down:1,hit:1}}];
  const button:Vector={...leaf,id:'button-instance',symbolId:'button',symbolPlayback:{mode:'single',firstFrame:0}};
  let root=button;
