  await d.getByRole('button',{name:'Capture script checkpoint',exact:true}).click();
  await d.getByRole('button',{name:'Replay retained script history',exact:true}).click();await expect(d.getByRole('status')).toContainText('4 JSON inputs replayed.');
  const state=await d.getByLabel('Script preview state').innerText(),url=await d.getByAltText('Script preview artwork').getAttribute('src');
  await key.press(fault==='script'?'x':'b');await d.getByAltText('Script preview artwork').click();
