  await deliver.click();await expect(d.getByRole('status')).toContainText(fault==='script'?'mixed failure':'Artwork encoding failed');
  await expect(d.getByLabel('Captured input order')).toContainText('4 captured events pending. Next: key');
  await expect(d.getByLabel('Script preview state')).toHaveText(state);expect(await d.getByAltText('Script preview artwork').getAttribute('src')).toBe(url);
