for(const fault of ['throw','cancel','render'] as const)test(`script playback controls ${fault} retain atomic history and artwork`,async({page})=>{
  const project=newProject();project.width=40;project.height=40;project.duration=4;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:30,height:30,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  project.layers[0].keys=[{frame:0,shapes:[art]},{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]}];
  project.frameScripts=[{frame:0,source:'state.n=((state.n as number)||0)+1; timeline.stop();'},
    {frame:1,source:'state.arrived=true; timeline.stop();'},
    {frame:2,source:fault==='throw'?'throw new Error("playback failure");':fault==='cancel'?'while(true){}':'state.changed=true; timeline.stop();'}];
  await page.addInitScript(p=>{
    if(window===parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project:p,folder:null,manifest:null}));
    const original=HTMLCanvasElement.prototype.toBlob;
    HTMLCanvasElement.prototype.toBlob=function(callback,...args){
      if(window!==parent&&(parent as unknown as {playbackFault?:boolean}).playbackFault){callback(null);return;}
      original.call(this,callback,...args);
    };
  },project);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const recovery=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true}),image=d.getByAltText('Script preview artwork');
  const pixel=()=>image.evaluate(async element=>{const img=element as HTMLImageElement;await img.decode();const c=document.createElement('canvas');c.width=40;c.height=40;const x=c.getContext('2d')!;x.drawImage(img,0,0);return Array.from(x.getImageData(10,10,1,1).data);});
  await d.getByLabel('Render detached artwork').check();await d.getByRole('button',{name:'Prepare script preview',exact:true}).click();await expect(d.getByRole('status')).toHaveText('Ready. No scripts have run.');
  const resume=d.getByRole('button',{name:'Resume root and step',exact:true}),pause=d.getByRole('button',{name:'Pause root and step',exact:true});
  await resume.click();await expect(d).toContainText('Frame 1 · Tick 1 · Stopped'); // Pending source overrides host resume.
  await resume.click();await expect(d).toContainText('Frame 2 · Tick 2 · Playing');
  await expect(d.getByLabel('Script preview state')).toContainText('"n": 1');expect(await pixel()).toEqual([0,255,0,255]);
  await pause.click();await expect(d).toContainText('Frame 2 · Tick 3 · Stopped');await expect(d.getByLabel('Script preview state')).toContainText('"arrived": true');
  await d.getByRole('button',{name:'Capture script checkpoint',exact:true}).click();
  await resume.click();await expect(d).toContainText('Frame 3 · Tick 4 · Playing');expect(await pixel()).toEqual([0,0,255,255]);
  await d.getByRole('button',{name:'Replay retained script history',exact:true}).click();await expect(d.getByRole('status')).toContainText('4 playback inputs replayed.');
  const state=await d.getByLabel('Script preview state').innerText(),url=await image.getAttribute('src');
  if(fault==='render')await page.evaluate(()=>Object.assign(window,{playbackFault:true}));
  if(fault==='cancel'){
    await withPendingScriptEngine(page,()=>pause.click(),()=>d.getByRole('button',{name:'Cancel script preview',exact:true}).click());
  }else{await pause.click();await expect(d.getByRole('status')).toContainText(fault==='throw'?'playback failure':'Artwork encoding failed');}
  await expect(pause).toBeEnabled();await expect(d).toContainText('Frame 3 · Tick 4 · Playing');
  await expect(d.getByLabel('Retained script playback inputs')).toContainText('4 playback inputs');
  await expect(d.getByLabel('Script preview state')).toHaveText(state);expect(await image.getAttribute('src')).toBe(url);
  await page.evaluate(()=>Object.assign(window,{playbackFault:false}));
  await d.getByRole('button',{name:'Restore script checkpoint',exact:true}).click();await expect(d).toContainText('Frame 2 · Tick 3 · Stopped');
  await expect(d.getByLabel('Retained script playback inputs')).toContainText('3 playback inputs');expect(await pixel()).toEqual([0,255,0,255]);
  await d.getByRole('button',{name:'Reset script preview',exact:true}).click();await expect(d.getByLabel('Retained script playback inputs')).toContainText('0 playback inputs');
  await d.getByRole('button',{name:'Restore script checkpoint',exact:true}).click();
  await d.getByRole('button',{name:'Replay retained script history',exact:true}).click();await expect(d.getByRole('status')).toContainText('3 playback inputs replayed.');
  await d.getByRole('button',{name:'Close dialog',exact:true}).click();await expect(page.locator('iframe')).toHaveCount(0);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(recovery);
});

for(const frames of [[0],[0,1],[0,2],[0,2,3]])test(`script button hit query ${frames.join('-')} uses final visible Hit geometry without interaction`,async({page})=>{
  const p=newProject();p.width=120;p.height=100;p.duration=4;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:40,height:40,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const child:Vector={...art,id:'child-instance',kind:'symbol',symbolId:'child',x:5,y:5,width:10,height:10};
  p.symbols=[{id:'child',name:'Child',width:10,height:10,shapes:[{...art,width:2,height:2}],
    timeline:{duration:2,keys:[{frame:1,shapes:[{...art,x:2,y:2,width:8,height:8}]}]},buttonStates:{up:0,over:0,down:0,hit:1}},
    {id:'parent',name:'Parent',width:40,height:40,shapes:[art,child],timeline:{duration:2,keys:[{frame:1,shapes:[art]}]},buttonStates:{up:0,over:0,down:0,hit:1}}];
  const root:Vector={...art,id:'root-instance',kind:'symbol',symbolId:'parent',x:10,y:20,transform:[2,0,0,1]};
  const top:Vector={...root,id:'top-instance'};
  p.layers[0].keys=[{frame:0,shapes:[root,top]},{frame:1,shapes:[root]},{frame:2,shapes:[]},{frame:3,shapes:[root]}];
  await page.goto('about:blank');
  await page.evaluate(()=>{
    Object.assign(window,{canvasHandlers:[]});const original=EventTarget.prototype.addEventListener;
    EventTarget.prototype.addEventListener=function(type,...args){
      if(this instanceof HTMLCanvasElement)(window as unknown as {canvasHandlers:string[]}).canvasHandlers.push(type);
      return original.call(this,type,...args);
    };
  });
  await page.setContent(exportPresentationHTML(p,frames.map((frame,tick)=>({frame,tick}))));
  const canvas=page.locator('canvas').first();await expect(canvas).toHaveAttribute('data-capture','ready');
  const result=await canvas.evaluate(element=>{
    const c=element as HTMLCanvasElement&{splashButtonAt:(x:number,y:number)=>null|{token:string;instanceId:string;symbolId:string;name:string}};
    const child=c.splashButtonAt(30,30),parent=c.splashButtonAt(12,22);
    const original=child?.token;if(child)child.token='mutated';
    return {child:c.splashButtonAt(30,30),parent,detached:c.splashButtonAt(30,30)?.token===original,
      outside:c.splashButtonAt(-100,-100),invalid:c.splashButtonAt(NaN,30),handlers:(window as unknown as {canvasHandlers:string[]}).canvasHandlers};
  });
  expect(result.handlers).toEqual([]);expect(result.outside).toBeNull();expect(result.invalid).toBeNull();expect(result.detached).toBe(true);
  if(frames.at(-1)===2){expect(result.child).toBeNull();expect(result.parent).toBeNull();}
  else{
    expect(result.child).toMatchObject({symbolId:'child',name:'Child'});
    expect(result.parent).toMatchObject({symbolId:'parent',instanceId:frames.at(-1)===0?'top-instance':'root-instance'});
  }
  await expect(canvas).not.toHaveAttribute('role','button');
  await canvas.dispatchEvent('pointerdown',{clientX:30,clientY:30,button:0,pointerId:1});
  await expect(canvas).not.toHaveAttribute('data-activations',/.+/);
});

for(const mode of ['success','compiler-timeout','renderer-cancel'] as const)test(`script artwork host query ${mode} detaches inputs and cleans resources`,async({page})=>{
  const asset=(await fs.readdir('dist/assets')).find(name=>name.startsWith('script-artwork-worker-')&&name.endsWith('.js'))!;
  const files=await Promise.all(['script-artwork-compile','script-artwork'].map(name=>fs.readFile('apps/editor/src/'+name+'.ts','utf8')));
  const source=files.map(s=>s.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,'')
    .replace("new URL('./script-artwork-worker.ts',import.meta.url)",`new URL('/assets/${asset}',location.href)`)+'\nObject.assign(window,{queryScriptArtworkTargets});';
  const bundle=await transformWithEsbuild(source,'query-test.ts',{loader:'ts',target:'es2022',minify:true});
  const p=newProject();p.width=40;p.height=40;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:30,height:30,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  p.symbols=[{id:'button',name:'Button',width:30,height:30,shapes:[art],timeline:{duration:2,keys:[{frame:1,shapes:[art]}]},buttonStates:{up:0,over:0,down:0,hit:1}}];
  p.layers[0].keys=[{frame:0,shapes:[{...art,id:'instance',kind:'symbol',symbolId:'button'}]},{frame:1,shapes:[]}];
  if(mode!=='success')await page.route('**/assets/script-artwork-worker-*.js',route=>route.fulfill({contentType:'text/javascript',body:mode==='compiler-timeout'?'self.onmessage=()=>{while(true){}};':`self.onmessage=()=>postMessage({ok:true,html:'<canvas></canvas>'});`}));
  let created=0,closed=0;page.on('worker',worker=>{created++;worker.on('close',()=>closed++);});
  await page.goto('/');await page.addScriptTag({content:bundle.code});
  const result=await page.evaluate(async({p,mode})=>{
    const api=window as unknown as {queryScriptArtworkTargets:typeof import('../../apps/editor/src/script-artwork').queryScriptArtworkTargets};
    const poses=[{frame:0,tick:0}],points=[{x:10,y:10},{x:-5,y:10}],controller=new AbortController();
    const watch=mode==='renderer-cancel'?setInterval(()=>{if(document.querySelector('iframe[title="Script artwork renderer"]'))controller.abort(new Error('cancel renderer query'));},10):undefined;
    try{
      const pending=api.queryScriptArtworkTargets(p,poses,points,{signal:controller.signal,timeoutMs:mode==='compiler-timeout'?100:5000});
      poses[0].frame=1;points[0].x=-50;p.layers[0].keys=[];
      return {result:await pending};
    }catch(error){return {error:String(error)};}finally{clearInterval(watch);}
  },{p,mode});
  if(mode==='success')expect(result).toMatchObject({result:{frame:0,tick:0,points:[{x:10,y:10},{x:-5,y:10}],targets:[{instanceId:'instance',symbolId:'button',name:'Button'},null]}});
  else expect(result.error).toContain(mode==='compiler-timeout'?'query timed out':'cancel renderer query');
  await expect(page.locator('iframe')).toHaveCount(0);await expect.poll(()=>closed).toBe(created);
  if(mode!=='success'){
    await page.unroute('**/assets/script-artwork-worker-*.js');
    const retry=await page.evaluate(async p=>{
      const api=window as unknown as {queryScriptArtworkTargets:typeof import('../../apps/editor/src/script-artwork').queryScriptArtworkTargets};
      return api.queryScriptArtworkTargets(p,[{frame:0,tick:0},{frame:1,tick:1}],[{x:10,y:10}]);
    },p);
    expect(retry).toMatchObject({frame:1,tick:1,targets:[null]});
    await expect(page.locator('iframe')).toHaveCount(0);await expect.poll(()=>closed).toBe(created);
  }
});

