for(const nested of [false,true])test(`script visual button states ${nested} guard lifetimes and restart state clocks`,async({page})=>{
  const p=newProject();p.width=40;p.height=40;p.duration=3;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:30,height:30,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const green={...art,fill:'#00ff00'},blue={...art,fill:'#0000ff'};
  const movie:Vector={...art,id:'movie-instance',kind:'symbol',symbolId:'movie',symbolPlayback:{mode:'movie',firstFrame:0}};
  p.symbols=[{id:'movie',name:'Movie',width:30,height:30,shapes:[art],timeline:{duration:3,keys:[{frame:1,shapes:[green]},{frame:2,shapes:[blue]}]}},
    {id:'button',name:'Button',width:30,height:30,shapes:[art],timeline:{duration:4,keys:[{frame:1,shapes:[green]},{frame:2,shapes:[movie]},{frame:3,shapes:[art]}]},buttonStates:{up:0,over:1,down:2,hit:3}}];
  let root:Vector={...art,id:'instance',kind:'symbol',symbolId:'button'};
  if(nested){p.symbols.push({id:'parent',name:'Parent',width:30,height:30,shapes:[root],timeline:{duration:2,keys:[{frame:1,shapes:[art]}]},buttonStates:{up:0,over:0,down:0,hit:1}});root={...root,id:'parent-instance',symbolId:'parent'};}
  p.layers[0].keys=[{frame:0,shapes:[root]},{frame:1,shapes:[]},{frame:2,shapes:[root]}];
  type Pose=Parameters<typeof exportPresentationHTML>[1][number];
  const show=async(poses:Pose[])=>{
    await page.goto('about:blank');await page.setContent(exportPresentationHTML(p,poses));
    const canvas=page.locator('canvas').first();await expect(canvas).toHaveAttribute('data-capture','ready');
    return canvas.evaluate(element=>{const c=element as HTMLCanvasElement&{splashButtonAt:(x:number,y:number)=>{lifetime:number;instanceId:string;symbolId:string}|null};return {pixel:Array.from(c.getContext('2d')!.getImageData(10,10,1,1).data).slice(0,3),target:c.splashButtonAt(10,10)};});
  };
  const initial=await show([{frame:0,tick:0}]);
  const state={instanceId:initial.target!.instanceId,symbolId:initial.target!.symbolId,lifetime:initial.target!.lifetime,state:'down' as 'over'|'down'};
  expect((await show([{frame:0,tick:0,buttonState:{...state,state:'over'}}])).pixel).toEqual([255,0,0]);
  expect((await show([{frame:0,tick:0},{frame:0,tick:1,buttonState:{...state,state:'over'}}])).pixel).toEqual([0,255,0]);
  const poses:Pose[]=[{frame:0,tick:0}];
  for(const [index,pixel] of [[1,[255,0,0]],[2,[0,255,0]],[3,[0,0,255]]] as const){
    poses.push({frame:0,tick:index,buttonState:state});expect((await show(poses)).pixel).toEqual(pixel);
  }
  poses.push({frame:0,tick:4,buttonState:{...state,state:'over'}},{frame:0,tick:5,buttonState:state});
  expect((await show(poses)).pixel).toEqual([255,0,0]);
  expect((await show([...poses,{frame:0,tick:6}])).pixel).toEqual([255,0,0]);
  const reentry=await show([{frame:0,tick:0},{frame:1,tick:1},{frame:2,tick:2,buttonState:{...state,state:'over'}}]);
  expect(reentry.pixel).toEqual([255,0,0]);expect(reentry.target!.lifetime).not.toBe(state.lifetime);
  expect(await show(poses)).toEqual(await show(poses));
});

