  p.symbols=[{id:'button',name:'Button',width:20,height:20,shapes:[art],timeline:{duration:4,keys:[{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]},{frame:3,shapes:[art]}]},buttonStates:{up:0,over:1,down:2,hit:3}}];
