test('two-pass GIF worker acknowledges each frame and publishes only completed output',async({page})=>{
  const source=(await Promise.all(['gif','gif-rgba','gif-stream','gif-stream-worker'].map(name=>fs.readFile(`packages/export-video/src/${name}.ts`,'utf8')))).map(s=>s.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,'');
  const bundle=await transformWithEsbuild(source,'gif-stream-test.ts',{loader:'ts',target:'es2022',minify:true});
  await page.route('**/gif-stream-test.js',route=>route.fulfill({contentType:'text/javascript',body:bundle.code}));await page.goto('/');
  const result=await page.evaluate(async()=>{
    const worker=new Worker('/gif-stream-test.js'),responses:unknown[]=[];
    const send=(request:unknown,transfer:Transferable[]=[])=>new Promise<Record<string,unknown>>((resolve,reject)=>{
      const timer=setTimeout(()=>reject(new Error('stream test timeout')),5000);
      worker.onmessage=e=>{clearTimeout(timer);resolve(e.data);};worker.onerror=()=>{clearTimeout(timer);reject(new Error('worker failed'));};
      worker.postMessage(request,transfer);
    });
    try{
      responses.push(await send({seq:0,kind:'init',settings:{width:1,height:1,frameCount:2,fps:24,matte:[255,255,255],transparent:true},maxBytes:4096,maxIndexedBytes:2}));
      for(const [seq,kind,color] of [[1,'analyze',255],[2,'analyze',0],[4,'index',255],[5,'index',0]] as const){
        if(seq===4)responses.push(await send({seq:3,kind:'seal'}));
        const frame=new Uint8Array([color,0,255,255]),pending=send({seq,kind,frame},[frame.buffer]);
        if(frame.byteLength!==0)throw new Error('frame not transferred');responses.push(await pending);
      }
      const final=await send({seq:6,kind:'finish'});
      return {responses,bytes:Array.from(final.bytes as Uint8Array),phase:final.phase};
    }finally{worker.terminate();}
  });
  expect(result.responses).toEqual(Array.from({length:6},(_,seq)=>({ok:true,seq,phase:seq<3?'analyze':'index',accepted:seq<3?seq:seq-3})));
  const frames=[new Uint8Array([255,0,255,255]),new Uint8Array([0,0,255,255])];
  expect(result.bytes).toEqual(Array.from(encodeIndexedGif(prepareRgbaGif({width:1,height:1,frames,fps:24,matte:[255,255,255],transparent:true}).animation)));
  expect(result.phase).toBe('done');
});

