  const source=(await Promise.all(['gif','gif-rgba','gif-stream','gif-stream-worker'].map(name=>fs.readFile(`packages/export-video/src/${name}.ts`,'utf8')))).map(s=>s.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,'');
