test('GIF chunk worker waits for acknowledgments before completing output',async({page})=>{
  const source=(await Promise.all(['gif','gif-rgba','gif-stream','gif-chunk-stream','gif-chunk-worker'].map(name=>fs.readFile(`packages/export-video/src/${name}.ts`,'utf8')))).map(s=>s.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,'');
  const bundle=await transformWithEsbuild(source,'gif-chunk-test.ts',{loader:'ts',target:'es2022',minify:true});
  await page.route('**/gif-chunk-test.js',route=>route.fulfill({contentType:'text/javascript',body:bundle.code}));await page.goto('/');
  const result=await page.evaluate(async()=>{
    const worker=new Worker('/gif-chunk-test.js'),chunks:number[][]=[];let received=0;
    const send=(request:unknown)=>new Promise<{kind:string;seq:number;chunkId:number;bytes?:Uint8Array;phase:string;ok:boolean}>((resolve,reject)=>{
      const timer=setTimeout(()=>reject(new Error('chunk worker timeout')),5000);
      worker.onmessage=e=>{received++;clearTimeout(timer);resolve(e.data);};worker.postMessage(request);
    });
    try{
      const frame=new Uint8Array(60000*4).fill(255);
      await send({seq:0,kind:'init',settings:{width:60000,height:1,frameCount:1,fps:24,matte:[0,0,0],transparent:false},maxBytes:200000,maxIndexedBytes:60000});
      await send({seq:1,kind:'analyze',frame});await send({seq:2,kind:'seal'});
      for(const request of [{seq:3,kind:'index',frame},{seq:4,kind:'finish'}]){
        let response=await send(request);
        while(response.kind==='chunk'){
          chunks.push(Array.from(response.bytes!));const before=received;await new Promise(resolve=>setTimeout(resolve,25));
          if(received!==before)throw new Error('chunk sent without acknowledgment');
          response=await send({kind:'ack-chunk',seq:response.seq,chunkId:response.chunkId});
        }
        if(!response.ok||response.phase!==(request.kind==='finish'?'done':'index'))throw new Error('invalid completion');
      }
      return chunks;
    }finally{worker.terminate();}
  });
  expect(result.length).toBeGreaterThan(1);expect(result.every(c=>c.length<=65536)).toBe(true);
  const expected=encodeIndexedGif(prepareRgbaGif({width:60000,height:1,frames:[new Uint8Array(60000*4).fill(255)],fps:24,matte:[0,0,0],transparent:false}).animation);
  expect(result.flat()).toEqual(Array.from(expected));
});

