test('PCM timeline mixing matches offline Web Audio gains and sample offsets',async({page})=>{
  const sources=[{at:0,gain:0.5,samples:Array.from({length:256},(_,i)=>i%2?0.5:-0.5)},{at:128,gain:0.25,samples:new Array(256).fill(0.5)}];
  const mixed=mixTimelinePcm(sources.map(s=>({startFrame:s.at,gain:s.gain,sampleRate:8000,channels:[new Float32Array(s.samples)]})),{startFrame:0,endFrame:512,fps:8000,sampleRate:8000,channelCount:1});
  await page.goto('/');const actual=await page.evaluate(async sources=>{
    const context=new OfflineAudioContext(1,512,8000);
    for(const s of sources){const buffer=context.createBuffer(1,s.samples.length,8000);buffer.copyToChannel(new Float32Array(s.samples),0);
      const source=context.createBufferSource(),gain=context.createGain();source.buffer=buffer;gain.gain.value=s.gain;source.connect(gain);gain.connect(context.destination);source.start(s.at/8000);}
    const rendered=await context.startRendering();return Array.from(rendered.getChannelData(0));
  },sources);
  expect(actual).toEqual(Array.from(mixed.channels[0]));
});

