for(const channels of [1,2])test(`PCM16 WAV ${channels} channels agrees with browser decoding within one sample step`,async({page})=>{
  const samples=Array.from({length:channels},(_,c)=>Array.from({length:256},(_,i)=>[-32768,-16384,0,16384,32767][(i+c)%5]));
  const bytes=pcm16WavFixture(samples,8000,true),expected=decodePcm16Wav(bytes);await page.goto('/');
  const actual=await page.evaluate(async bytes=>{
    const context=new OfflineAudioContext(2,256,8000),decoded=await context.decodeAudioData(new Uint8Array(bytes).buffer);
    return {sampleRate:decoded.sampleRate,frames:decoded.length,channels:Array.from({length:decoded.numberOfChannels},(_,c)=>Array.from(decoded.getChannelData(c)))};
  },Array.from(bytes));
  expect([actual.sampleRate,actual.frames,actual.channels.length]).toEqual([expected.sampleRate,expected.frames,channels]);
  // Chromium normalizes positive values by 32767; this decoder deliberately uses 32768
  // for every signed sample. Allow only that one-step endpoint convention difference.
  for(let c=0;c<channels;c++)for(let i=0;i<expected.frames;i++){
    expect(Math.abs(actual.channels[c][i]-expected.channels[c][i])).toBeLessThanOrEqual(1/32768);
    expect(Math.round(actual.channels[c][i]*(actual.channels[c][i]<0?32768:32767))).toBe(samples[c][i]);
  }
});

