test('saved audio preparation admits real WAV workers and rejects metadata drift',async({page})=>{
  const {build}=await import('vite');
  const result=await build({configFile:false,logLevel:'silent',build:{write:false,minify:false,lib:{entry:'packages/audio/src/project-preview.ts',formats:['es'],fileName:()=> 'project-audio.js'},rollupOptions:{output:{assetFileNames:'[name][extname]'}}}});
  const outputs=(Array.isArray(result)?result:[result]).flatMap(r=>'output' in r?r.output:[]);
  for(const output of outputs)await page.route(`**/${output.fileName}`,route=>route.fulfill({contentType:'text/javascript',body:output.type==='chunk'?output.code:typeof output.source==='string'?output.source:Buffer.from(output.source)}));
  let created=0,closed=0;page.on('worker',w=>{created++;w.on('close',()=>closed++);});
  await page.goto('/');
  const p=newProject();p.fps=100;p.duration=2;p.assets=[{id:'a',path:'assets/audio/a.wav',audio:{name:'A',format:'pcm16-wav',sampleRate:8000,channels:1,frames:160}}];p.audioClips=[{id:'c',assetId:'a',startFrame:1,offsetSamples:0,gain:0.5}];
  const resultSamples=await page.evaluate(async({project,bytes})=>{
    const url='/project-audio.js';const {prepareProjectAudio}=await import(url) as typeof import('../../packages/audio/src/project-preview');
    const load=async()=>new Blob([new Uint8Array(bytes)]);
    const result=await prepareProjectAudio(project,load);
    project.assets[0].audio!.frames++;
    let failure='';try{await prepareProjectAudio(project,load);}catch(error){failure=String(error);}
    return {samples:Array.from(result.channels[0]),failure};
  },{project:p,bytes:Array.from(pcm16WavFixture([Array(160).fill(16384)]))});
  expect(resultSamples.samples).toEqual([...Array(80).fill(0),...Array(80).fill(0.25)]);expect(resultSamples.failure).toMatch(/metadata mismatch/);
  expect(created).toBe(3);await expect.poll(()=>closed).toBe(created);
});


