test('audio clip editor keeps keyboard focus during draft edits and returns it on Escape', async ({ page }) => {
  const project = newProject();
  project.assets = [{ id: 'a', path: 'assets/audio/a.wav', audio: {
    name: 'A', format: 'pcm16-wav', sampleRate: 8000, channels: 1, frames: 8000,
  } }];
  await page.addInitScript(project => localStorage.setItem('splash-recovery-v1',
    JSON.stringify({ project, folder: null, manifest: null })), project);
  await page.goto('/');
  const recover = page.getByRole('button', { name: 'Recover changes', exact: true });
  const splash = page.getByRole('button', { name: 'Open editor', exact: true });
  await expect(splash.or(recover)).toBeVisible();
  if (await splash.isVisible()) await splash.click();
  await recover.click();
  const read = () => page.evaluate(() => JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const control = page.getByRole('button', { name: 'Control', exact: true });
  await control.click();
  await page.getByRole('button', { name: 'Edit audio clips...', exact: true }).click();
  const dialog = page.getByRole('dialog', { name: 'Edit audio clips', exact: true });
  const add = dialog.getByRole('button', { name: 'Add audio clip', exact: true });
  const apply = dialog.getByRole('button', { name: 'Apply audio clips', exact: true });
  await expect(add).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(dialog.getByRole('button', { name: 'Close dialog', exact: true })).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(apply).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(add).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(dialog.getByLabel('Clip 1 asset')).toBeFocused();
  for (let i = 0; i < 6; i++) await page.keyboard.press('Tab');
  await expect(dialog.getByRole('button', { name: 'Remove clip 1', exact: true })).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(add).toBeFocused();
  expect(await read()).toEqual(project);
  await page.keyboard.press('Enter');
  await expect(dialog.getByLabel('Clip 1 asset')).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await expect(apply).toBeFocused();
  await page.keyboard.press('Enter');
  await expect(dialog.getByRole('status')).toHaveText('Audio clips applied.');
  const applied = await read();
  expect(applied.audioClips).toEqual([{ id: expect.any(String), assetId: 'a', startFrame: 0, offsetSamples: 0, gain: 1 }]);
  await page.keyboard.press('Escape');
  await expect(dialog).toHaveCount(0);
  await expect(control).toBeFocused();
  await page.getByLabel('Drawing stage').press('Control+z');
  await expect.poll(read).toEqual(project);
});

