for(const mode of ['success','timeout','cancel'] as const)test(`WAV encoder worker ${mode} preserves inputs and cleans up`,async({page})=>{
 const core=await fs.readFile('packages/audio/src/wav-encode.ts','utf8');
 const worker=await transformWithEsbuild((core+'\n'+(await fs.readFile('packages/audio/src/wav-encode-worker.ts','utf8')).replace(/^import[^\n]+\n/gm,'')).replace(/export /g,''),'encode-worker.ts',{loader:'ts',target:'es2022'});
 const source=(await fs.readFile('packages/audio/src/wav-encode-async.ts','utf8')).replace(/^import[^\n]+\n/gm,'').replace("new URL('./wav-encode-worker.ts',import.meta.url)","new URL('/encode-worker-test.js',location.href)");
 const host=await transformWithEsbuild(source.replace(/export /g,'')+'\nObject.assign(window,{encodePcm16WavAsync});','encode-host.ts',{loader:'ts',target:'es2022'});
 let fault=mode!=='success',created=0,closed=0;await page.route('**/encode-worker-test.js',route=>route.fulfill({contentType:'text/javascript',body:fault?'self.onmessage=()=>{while(true){}};':worker.code}));page.on('worker',w=>{created++;w.on('close',()=>closed++);});await page.goto('/');await page.addScriptTag({content:host.code});
 const run=(mode:string)=>page.evaluate(async mode=>{
  const api=window as unknown as {encodePcm16WavAsync:typeof import('../../packages/audio/src/wav-encode-async').encodePcm16WavAsync},source=new Float32Array([-1,0,1]),controller=new AbortController(),timer=mode==='cancel'?setTimeout(()=>controller.abort(new Error('cancel encoding')),100):undefined;
  try{const pending=api.encodePcm16WavAsync([source],8000,{signal:controller.signal,timeoutMs:mode==='timeout'?100:5000});source.fill(0);const bytes=await pending,view=new DataView(bytes.buffer);return {samples:[view.getInt16(44,true),view.getInt16(46,true),view.getInt16(48,true)],length:source.length};}catch(e){return {error:String(e)};}finally{clearTimeout(timer);}
 },mode);
 const first=await run(mode);if(mode==='success')expect(first).toEqual({samples:[-32768,0,32767],length:3});else expect(first.error).toMatch(mode==='timeout'?/timed out/:/cancel encoding/);await expect.poll(()=>closed).toBe(created);fault=false;if(mode!=='success'){expect(await run('success')).toEqual({samples:[-32768,0,32767],length:3});await expect.poll(()=>closed).toBe(created);}
});

