test('audio playback scheduler uses a real context and disposes sources without closing its owner',async({page})=>{
 const source=(await Promise.all(['pcm.ts','transport.ts','playback.ts'].map(name=>fs.readFile(`packages/audio/src/${name}`,'utf8')))).map(text=>text.replace(/^import[^\n]+\n/gm,'')).join('\n');
 const bundle=await transformWithEsbuild(source.replace(/export /g,'')+'\nObject.assign(window,{createAudioPlayback});','playback-test.ts',{loader:'ts',target:'es2022'});
 await page.goto('/');await page.addScriptTag({content:bundle.code});
 const result=await page.evaluate(async()=>{
  const api=window as unknown as {createAudioPlayback:typeof import('../../packages/audio/src/playback').createAudioPlayback};
  const context=new AudioContext({sampleRate:8000}),channels=[new Float32Array(8000)];
  const playback=api.createAudioPlayback(context,channels,{startFrame:0,endFrame:24,fps:24,sampleRate:8000});
  try{const initial=playback.position();await playback.play();for(let i=0;i<20&&playback.position().sample===0;i++)await new Promise(r=>setTimeout(r,100));const paused=playback.pause();await new Promise(r=>setTimeout(r,30));const held=playback.position();const sought=playback.seek(12);await playback.play();const resumed=playback.position();playback.dispose();return {initial,paused,held,sought,resumed,contextState:context.state};}finally{playback.dispose();await context.close();}
 });
 expect(result.initial.playing).toBe(false);expect(result.paused.sample).toBeGreaterThan(0);expect(result.paused.playing).toBe(false);expect(result.held.sample).toBe(result.paused.sample);expect(result.sought).toMatchObject({sample:4000,frame:12,playing:false});expect(result.resumed.playing).toBe(true);expect(result.contextState).toBe('running');
});

