test('detached frame replay preserves nested clocks across skips and backward seeks',async({page})=>{
 const {build}=await import('vite');const bundle=await build({configFile:false,logLevel:'silent',build:{write:false,minify:false,lib:{entry:'apps/editor/src/frame-replay.ts',formats:['es'],fileName:()=> 'frame-replay-test.js'}}});
 const outputs=(Array.isArray(bundle)?bundle:[bundle]).flatMap(r=>'output' in r?r.output:[]);for(const output of outputs)await page.route(`**/${output.fileName}`,r=>r.fulfill({contentType:'text/javascript',body:output.type==='chunk'?output.code:typeof output.source==='string'?output.source:Buffer.from(output.source)}));await page.goto('/');
 const p=newProject();p.width=p.height=40;p.duration=8;p.fps=30;
 const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
 p.symbols=[{id:'leaf',name:'Leaf',width:20,height:20,shapes:[art],timeline:{duration:3,keys:[{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]}]}}];
 p.layers[0].keys=[{frame:0,shapes:[{...art,id:'instance',kind:'symbol',symbolId:'leaf',symbolPlayback:{mode:'movie',firstFrame:0}}]}];p.frameScripts=[{frame:0,source:'throw new Error("inert");'}];
 const result=await page.evaluate(async project=>{
  const url='/frame-replay-test.js',{createFrameReplay}=await import(url) as typeof import('../../apps/editor/src/frame-replay');
  const session=createFrameReplay(project);project.symbols![0].timeline!.keys[0].shapes[0].fill='#ffffff';
  const rgb=(image:ImageData)=>Array.from(image.data.slice((5*40+5)*4,(5*40+5)*4+3));
  const first=session.seek(0);let concurrent=false;try{await session.seek(1);}catch{concurrent=true;}
  const colors=[rgb(await first),rgb(await session.seek(5)),rgb(await session.seek(5)),rgb(await session.seek(1)),rgb(await session.seek(4))];
  let invalid=false;try{await session.seek(-1);}catch{invalid=true;}colors.push(rgb(await session.seek(4)));session.dispose();session.dispose();
  let disposed=false;try{await session.seek(0);}catch{disposed=true;}
  const controller=new AbortController(),cancelled=createFrameReplay(project,{signal:controller.signal});const pending=cancelled.seek(0);controller.abort();let aborted=false;try{await pending;}catch{aborted=true;}
  const timed=createFrameReplay(project,{timeoutMs:0.001});let timeout=false;try{await timed.seek(7);}catch{timeout=true;}
  return {colors,concurrent,invalid,disposed,aborted,timeout,hosts:document.querySelectorAll('iframe[title="Detached frame replay"]').length};
 },p);
 expect(result).toEqual({colors:[[255,0,0],[0,0,255],[0,0,255],[0,255,0],[0,255,0],[0,255,0]],concurrent:true,invalid:true,disposed:true,aborted:true,timeout:true,hosts:0});
});
