for(const pattern of ['solid','alternating','ramp','noise'])test(`GIF dictionary LZW independently decodes ${pattern}`,async({page})=>{
 const size=65536,pixels=new Uint8Array(size),palette=new Uint8Array(768);let seed=12345;
 for(let i=0;i<256;i++)palette.set([i,i,i],i*3);for(let i=0;i<size;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;pixels[i]=pattern==='solid'?127:pattern==='alternating'?i%2:pattern==='ramp'?i%256:seed>>>24;}
 const settings={width:256,height:256,palette,frames:[{pixels,delayCentiseconds:7}]};const literal=encodeIndexedGif(settings),compressed=encodeIndexedGif({...settings,compression:'dictionary'});const chunks:Uint8Array[]=[];const encoder=createIndexedGifChunkEncoder({...settings,frameCount:1,compression:'dictionary'},chunk=>{chunks.push(chunk);},compressed.length,7);encoder.append(settings.frames[0]);encoder.finish();expect(new Uint8Array(chunks.flatMap(c=>Array.from(c)))).toEqual(compressed);
 if(pattern!=='noise')expect(compressed.length).toBeLessThan(literal.length/4);await page.goto('/');
 const decoded=await page.evaluate(async bytes=>{const Decoder=(globalThis as unknown as {ImageDecoder:new(options:{data:Uint8Array;type:string})=>{tracks:{ready:Promise<void>};decode:(options:{frameIndex:number})=>Promise<{image:VideoFrame}>;close:()=>void}}).ImageDecoder;const decoder=new Decoder({data:new Uint8Array(bytes),type:'image/gif'});try{await decoder.tracks.ready;const {image}=await decoder.decode({frameIndex:0});try{const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d')!;ctx.drawImage(image,0,0);const rgba=ctx.getImageData(0,0,256,256).data;return {duration:image.duration,gray:Array.from({length:65536},(_,i)=>rgba[i*4]),opaque:rgba.every((value,i)=>i%4!==3||value===255)};}finally{image.close();}}finally{decoder.close();}},Array.from(compressed));
 expect(decoded.gray).toEqual(Array.from(pixels));expect(decoded.opaque).toBe(true);expect(decoded.duration).toBe(70000);
});
for(const mode of ['complete','chunk','failure','cancel'] as const)test(`compressed GIF worker ${mode} preserves output and cleanup`,async({page})=>{
 const {build}=await import('vite');const name=mode==='complete'?'gif-stream-async':'gif-chunk-async';const bundle=await build({configFile:false,logLevel:'silent',build:{write:false,minify:false,lib:{entry:`packages/export-video/src/${name}.ts`,formats:['es'],fileName:()=> 'compressed-host.js'},rollupOptions:{output:{assetFileNames:'[name][extname]'}}}});const outputs=(Array.isArray(bundle)?bundle:[bundle]).flatMap(r=>'output' in r?r.output:[]);for(const output of outputs)await page.route(`**/${output.fileName}`,r=>r.fulfill({contentType:'text/javascript',body:output.type==='chunk'?output.code:typeof output.source==='string'?output.source:Buffer.from(output.source)}));let created=0,closed=0;page.on('worker',w=>{created++;w.on('close',()=>closed++);});await page.goto('/');
 const expected=encodeIndexedGif(prepareRgbaGif({width:4096,height:1,frames:[new Uint8Array(4096*4).fill(255)],fps:24,matte:[0,0,0],transparent:false,compression:'dictionary'}).animation);
 const result=await page.evaluate(async({mode,budget})=>{
  const url='/compressed-host.js',api=await import(url) as typeof import('../../packages/export-video/src/gif-stream-async')&typeof import('../../packages/export-video/src/gif-chunk-async');const settings={width:4096,height:1,frameCount:1,fps:24,matte:[0,0,0] as [number,number,number],transparent:false,compression:'dictionary' as const},controller=new AbortController(),chunks:Uint8Array[]=[];let aborted=0;
  const sink={write:async(c:Uint8Array)=>{chunks.push(c);await new Promise(r=>setTimeout(r,1));if(mode==='failure')throw new Error('compressed sink failure');if(mode==='cancel')controller.abort(new Error('compressed cancel'));},abort:()=>{aborted++;chunks.length=0;}};
  const opening=mode==='complete'?api.openGifStream(settings,{maxBytes:budget,signal:controller.signal}):api.openGifChunkStream(settings,sink,{maxBytes:budget,signal:controller.signal});Object.assign(settings,{compression:'literal'});const stream=await opening;
  try{await stream.analyze(new Uint8Array(4096*4).fill(255),true);await stream.seal();await stream.index(new Uint8Array(4096*4).fill(255),true);const done=await stream.finish();return {bytes:Array.from('bytes' in done?done.bytes:new Uint8Array(chunks.flatMap(c=>Array.from(c)))),aborted};}
  catch(e){await stream.dispose();return {error:String(e),aborted,remaining:chunks.length};}finally{await stream.dispose();}
 },{mode,budget:expected.length});if(mode==='complete'||mode==='chunk'){expect(result.bytes).toEqual(Array.from(expected));expect(result.aborted).toBe(0);}else{expect(result.error).toContain(mode==='failure'?'compressed sink failure':'compressed cancel');expect(result.aborted).toBe(1);expect(result.remaining).toBe(0);}await expect.poll(()=>closed).toBe(created);
});
