test('IVF frames carry real VP8 packets and rational timestamps into Chromium decoding',async({page})=>{
 await page.goto('/');const packets=await page.evaluate(async()=>{
  const chunks:number[][]=[];let failure:Error|undefined;const encoder=new VideoEncoder({output:chunk=>{const bytes=new Uint8Array(chunk.byteLength);chunk.copyTo(bytes);chunks.push(Array.from(bytes));},error:e=>{failure=e;}});
  try{encoder.configure({codec:'vp8',width:32,height:32,bitrate:1000000,framerate:30000/1001});const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const context=canvas.getContext('2d')!;
   for(let i=0;i<2;i++){context.fillStyle=i?'#0000ff':'#ff0000';context.fillRect(0,0,32,32);const frame=new VideoFrame(canvas,{timestamp:Math.round(i*1001000/30)});try{encoder.encode(frame,{keyFrame:true});}finally{frame.close();}}
   await encoder.flush();if(failure)throw failure;return chunks;
  }finally{encoder.close();}
 });expect(packets).toHaveLength(2);const chunks:Uint8Array[]=[];const writer=createIvfWriter({codec:'vp8',width:32,height:32,frameCount:2,rate:30000,scale:1001},b=>{chunks.push(b);});for(const packet of packets)writer.append(new Uint8Array(packet));const receipt=writer.finish();const bytes=new Uint8Array(chunks.flatMap(c=>Array.from(c)));expect(receipt.byteLength).toBe(bytes.length);
 const decoded=await page.evaluate(async data=>{
  const bytes=new Uint8Array(data),v=new DataView(bytes.buffer);if(String.fromCharCode(...bytes.slice(0,4))!=='DKIF'||v.getUint16(6,true)!==32||String.fromCharCode(...bytes.slice(8,12))!=='VP80')throw Error('Invalid IVF header');
  const rate=v.getUint32(16,true),scale=v.getUint32(20,true),count=v.getUint32(24,true),frames:{timestamp:number;rgb:number[]}[]=[];let failure:Error|undefined;
  const decoder=new VideoDecoder({output:frame=>{try{const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const c=canvas.getContext('2d')!;c.drawImage(frame,0,0);frames.push({timestamp:frame.timestamp,rgb:Array.from(c.getImageData(16,16,1,1).data.slice(0,3))});}finally{frame.close();}},error:e=>{failure=e;}});
  try{decoder.configure({codec:'vp8',codedWidth:v.getUint16(12,true),codedHeight:v.getUint16(14,true)});let offset=32;
   for(let i=0;i<count;i++){const length=v.getUint32(offset,true),pts=Number(v.getBigUint64(offset+4,true));offset+=12;if(offset+length>bytes.length)throw Error('Truncated IVF packet');decoder.decode(new EncodedVideoChunk({type:'key',timestamp:Math.round(pts*scale*1000000/rate),data:bytes.slice(offset,offset+length)}));offset+=length;}
   if(offset!==bytes.length)throw Error('Unexpected trailing bytes');await decoder.flush();if(failure)throw failure;return frames;
  }finally{decoder.close();}
 },Array.from(bytes));expect(decoded.map(f=>f.timestamp)).toEqual([0,33367]);expect(decoded[0].rgb[0]).toBeGreaterThan(220);expect(decoded[0].rgb[2]).toBeLessThan(30);expect(decoded[1].rgb[2]).toBeGreaterThan(220);expect(decoded[1].rgb[0]).toBeLessThan(30);
});

test('VP8 host encodes snapshots and cleans cancellation deadline and retry',async({page})=>{
 const {build}=await import('vite');const bundle=await build({configFile:false,logLevel:'silent',build:{write:false,minify:false,lib:{entry:'packages/export-video/src/vp8.ts',formats:['es'],fileName:()=> 'vp8-host.js'}}});const outputs=(Array.isArray(bundle)?bundle:[bundle]).flatMap(r=>'output' in r?r.output:[]);for(const o of outputs)if(o.type==='chunk')await page.route(`**/${o.fileName}`,r=>r.fulfill({contentType:'text/javascript',body:o.code}));await page.goto('/');
 const result=await page.evaluate(async()=>{
  const url='/vp8-host.js',{openVp8Encoder}=await import(url) as typeof import('../../packages/export-video/src/vp8');const Native=VideoEncoder;let created=0,closed=0;globalThis.VideoEncoder=class extends Native{constructor(init:VideoEncoderInit){super(init);created++;}close(){closed++;super.close();}};
  const settings={width:32,height:32,frameCount:2,rate:30000,scale:1001,bitrate:1000000};const rgba=new Uint8Array(32*32*4);for(let i=0;i<rgba.length;i+=4){rgba[i]=rgba[i+3]=255;}
  try{
   const host=openVp8Encoder(settings);const first=host.append(rgba);for(let i=0;i<rgba.length;i+=4){rgba[i]=0;rgba[i+2]=255;}await first;await host.append(rgba);const out=host.finish();const v=new DataView(out.bytes.buffer),frames:{timestamp:number;rgb:number[]}[]=[];
   let failure:Error|undefined;const decoder=new VideoDecoder({output:f=>{try{const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const c=canvas.getContext('2d')!;c.drawImage(f,0,0);frames.push({timestamp:f.timestamp,rgb:Array.from(c.getImageData(16,16,1,1).data.slice(0,3))});}finally{f.close();}},error:e=>{failure=e;}});
   try{decoder.configure({codec:'vp8',codedWidth:32,codedHeight:32});let offset=32;for(let i=0;i<2;i++){const size=v.getUint32(offset,true),pts=Number(v.getBigUint64(offset+4,true));offset+=12;decoder.decode(new EncodedVideoChunk({type:'key',timestamp:Math.round(pts*1001*1000000/30000),data:out.bytes.slice(offset,offset+size)}));offset+=size;}await decoder.flush();if(failure)throw failure;}finally{decoder.close();}
   const controller=new AbortController(),cancelled=openVp8Encoder(settings,{signal:controller.signal});const job=cancelled.append(rgba);controller.abort(Error('cancel fixture'));let cancel='';try{await job;}catch(e){cancel=String(e);}
   const timed=openVp8Encoder(settings,{timeoutMs:1});await new Promise(r=>setTimeout(r,20));let timeout='';try{timed.finish();}catch(e){timeout=String(e);}
   const retry=openVp8Encoder({...settings,frameCount:1});await retry.append(rgba);const done=retry.finish();return {frames,cancel,timeout,retry:done.frameCount,created,closed};
  }finally{globalThis.VideoEncoder=Native;}
 });expect(result.frames.map(f=>f.timestamp)).toEqual([0,33367]);expect(result.frames[0].rgb[0]).toBeGreaterThan(220);expect(result.frames[0].rgb[2]).toBeLessThan(30);expect(result.frames[1].rgb[2]).toBeGreaterThan(220);expect(result.cancel).toContain('cancel fixture');expect(result.timeout).toContain('timed out');expect(result.retry).toBe(1);expect(result.created).toBe(4);expect(result.closed).toBe(4);
});

test('detached IVF capture preserves nested selected frames and cleans cancel timeout and retry',async({page})=>{
 const {build}=await import('vite');const bundle=await build({configFile:false,logLevel:'silent',build:{write:false,minify:false,lib:{entry:'apps/editor/src/export-ivf.ts',formats:['es'],fileName:()=> 'export-ivf-test.js'}}});const outputs=(Array.isArray(bundle)?bundle:[bundle]).flatMap(r=>'output' in r?r.output:[]);for(const o of outputs)if(o.type==='chunk')await page.route(`**/${o.fileName}`,r=>r.fulfill({contentType:'text/javascript',body:o.code}));await page.goto('/');
 const p=newProject();p.width=p.height=32;p.duration=4;p.fps=29.97;const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:32,height:32,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};p.symbols=[{id:'nested',name:'Nested',width:32,height:32,shapes:[art],timeline:{duration:3,keys:[{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]}]}}];p.layers[0].keys=[{frame:0,shapes:[{...art,id:'instance',kind:'symbol',symbolId:'nested',symbolPlayback:{mode:'movie',firstFrame:0}}]}];p.frameScripts=[{frame:0,source:'throw new Error("must not execute");'}];
 const result=await page.evaluate(async original=>{
  const url='/export-ivf-test.js',{exportIVF}=await import(url) as typeof import('../../apps/editor/src/export-ivf');const work=structuredClone(original),progress:number[]=[];const settings={range:{start:1,end:2},progress:(done:number)=>{progress.push(done);work.duration=1;work.fps=1;work.symbols![0].timeline!.keys[1].shapes[0].fill='#ffffff';}};
  const out=await exportIVF(work,new AbortController().signal,settings);const v=new DataView(out.bytes.buffer),colors:number[][]=[];let failure:Error|undefined;
  const decoder=new VideoDecoder({output:frame=>{try{const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const c=canvas.getContext('2d')!;c.drawImage(frame,0,0);colors.push(Array.from(c.getImageData(16,16,1,1).data.slice(0,3)));}finally{frame.close();}},error:e=>{failure=e;}});
  try{decoder.configure({codec:'vp8',codedWidth:32,codedHeight:32});let offset=32;for(let i=0;i<out.frameCount;i++){const n=v.getUint32(offset,true),pts=Number(v.getBigUint64(offset+4,true));offset+=12;decoder.decode(new EncodedVideoChunk({type:'key',timestamp:Math.round(pts*out.scale*1000000/out.rate),data:out.bytes.slice(offset,offset+n)}));offset+=n;}await decoder.flush();if(failure)throw failure;}finally{decoder.close();}
  const controller=new AbortController();let cancel='';try{await exportIVF(original,controller.signal,{progress:()=>controller.abort(Error('capture cancel'))});}catch(e){cancel=String(e);}
  let timeout='';try{await exportIVF(original,new AbortController().signal,{timeoutMs:1});}catch(e){timeout=String(e);}
  const retry=await exportIVF(original,new AbortController().signal,{range:{start:0,end:0}});
  return {colors,progress,rate:out.rate,scale:out.scale,range:[out.start,out.end],cancel,timeout,retry:retry.frameCount,hosts:document.querySelectorAll('iframe[title="Detached frame replay"]').length};
 },p);expect(result.colors).toHaveLength(2);expect(result.colors[0][1]).toBeGreaterThan(220);expect(result.colors[0][2]).toBeLessThan(30);expect(result.colors[1][2]).toBeGreaterThan(220);expect(result.colors[1][0]).toBeLessThan(30);expect(result.progress).toEqual([1,2]);expect([result.rate,result.scale]).toEqual([2997,100]);expect(result.range).toEqual([1,2]);expect(result.cancel).toContain('capture cancel');expect(result.timeout).toContain('timed out');expect(result.retry).toBe(1);expect(result.hosts).toBe(0);
});

