 if(periodic)await page.addInitScript(()=>{const original=VideoEncoder.prototype.configure;VideoEncoder.prototype.configure=function(config){(globalThis as typeof globalThis&{ivfConfigured?:number}).ivfConfigured=config.bitrate;return original.call(this,config);};});
 await page.addInitScript(p=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project:p,folder:null,manifest:null})),p);
 if(mode==='cancel')await page.addInitScript(()=>{const root=globalThis as typeof globalThis&{ivfStall?:boolean;ivfStarted?:boolean};root.ivfStall=true;const flush=VideoEncoder.prototype.flush;VideoEncoder.prototype.flush=function(){root.ivfStarted=true;return root.ivfStall?new Promise<void>(()=>{}):flush.call(this);};});
 await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();const before=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));let downloads=0;page.on('download',()=>downloads++);
 if(selected){const box=(await page.getByLabel('Timeline frames').boundingBox())!;await page.mouse.click(box.x+33,box.y+40);await page.keyboard.down('Shift');await page.mouse.click(box.x+45,box.y+40);await page.keyboard.up('Shift');await expect(page.getByText('Frames 2–3 · 2 selected',{exact:true})).toBeVisible();}
 const command=selected?'Export selected WebM range…':'Export WebM video…';
 if(mode==='cancel'){await openExportSettings(page);await page.getByRole('button',{name:command,exact:true}).click();await expect.poll(()=>page.evaluate(()=>(globalThis as typeof globalThis&{ivfStarted?:boolean}).ivfStarted)).toBe(true);await page.getByRole('button',{name:'Cancel WebM export',exact:true}).click();await expect(page.getByText('WebM export cancelled',{exact:true})).toBeVisible();expect(downloads).toBe(0);await expect(page.locator('iframe[title="Detached frame replay"]')).toHaveCount(0);await page.evaluate(()=>{(globalThis as typeof globalThis&{ivfStall?:boolean}).ivfStall=false;});}
 await openExportSettings(page);
 if(periodic){for(const invalid of ['', '301']){await page.getByLabel('Video keyframe interval',{exact:true}).fill(invalid);await page.getByRole('button',{name:command,exact:true}).click();await expect(page.getByRole('alert')).toContainText('whole number from 1 to 300');expect(downloads).toBe(0);expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);await openExportSettings(page);}await page.getByLabel('Video keyframe interval',{exact:true}).fill('3');await page.getByLabel('Video target bitrate',{exact:true}).selectOption('1000000');}
 const pending=page.waitForEvent('download');await page.getByRole('button',{name:command,exact:true}).click();const download=await pending;expect(download.suggestedFilename()).toBe('Video fixture.webm');const bytes=Array.from(await fs.readFile((await download.path())!));
 const result=await page.evaluate(async data=>{
  const video=document.createElement('video');video.muted=true;document.body.append(video);const url=URL.createObjectURL(new Blob([new Uint8Array(data)],{type:'video/webm'}));
  const wait=(name:string)=>new Promise<void>((resolve,reject)=>{const timer=setTimeout(()=>{cleanup();reject(Error(name+' timeout'));},5000);const done=()=>{cleanup();resolve();},bad=()=>{cleanup();reject(Error('decode failure'));},cleanup=()=>{clearTimeout(timer);video.removeEventListener(name,done);video.removeEventListener('error',bad);};video.addEventListener(name,done);video.addEventListener('error',bad);});
  try{const loaded=wait('loadeddata');video.src=url;await loaded;const duration=video.duration;const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const ctx=canvas.getContext('2d')!,colors:number[][]=[];for(const time of [0.005,duration-0.005,0.005]){const seek=wait('seeked');video.currentTime=time;await seek;ctx.drawImage(video,0,0);colors.push(Array.from(ctx.getImageData(16,16,1,1).data.slice(0,3)));}return {duration,colors};}finally{video.pause();video.removeAttribute('src');video.load();video.remove();URL.revokeObjectURL(url);}
 },bytes);
 expect(result.duration).toBeCloseTo(Math.round((selected?2:periodic?8:3)*1000000/29.97)/1000000,5);for(const [i,color] of result.colors.entries()){const channel=!periodic&&i===1?2:0;expect(color[channel]).toBeGreaterThan(220);for(let j=0;j<3;j++)if(j!==channel)expect(color[j]).toBeLessThan(30);}if(periodic){expect(await page.evaluate(()=>(globalThis as typeof globalThis&{ivfConfigured?:number}).ivfConfigured)).toBe(1000000);await expect(page.getByText(/target 1 Mbps/)).toBeVisible();}expect(downloads).toBe(1);await expect(page.locator('iframe[title="Detached frame replay"]')).toHaveCount(0);expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);
