async function loadScriptSessionForTest(page:Page){
  const entry='stop-session-virtual.ts';
  const bundled=await build({configFile:false,logLevel:'silent',worker:{format:'es'},
    plugins:[{name:'stop-session-test',resolveId(id){if(id===entry||id.replaceAll('\\','/').endsWith('/'+entry))return '\0'+entry;},
      load(id){if(id==='\0'+entry)return `import { createScriptSession } from '/packages/scripting/src/session.ts';
        Object.assign(window,{createScriptSession});`;}}],
    build:{write:false,lib:{entry,name:'StopSessionTest',formats:['iife']}}});
  const [output]=Array.isArray(bundled)?bundled:[bundled];
  if(!output||!('output' in output))throw Error('Expected an in-memory script session bundle.');
  const chunk=output.output.find(item=>item.type==='chunk'&&item.isEntry);
  if(chunk?.type!=='chunk')throw Error('Missing script session bundle.');
  await page.goto('/');await page.addScriptTag({content:chunk.code});
}

test('script run-to-frame stops before the next body and preserves atomic replay',async({page})=>{
  await loadScriptSessionForTest(page);
  const result=await page.evaluate(async()=>{
    const api=window as unknown as {createScriptSession:typeof import('../../packages/scripting/src/session').createScriptSession};
    const session=api.createScriptSession({duration:4,fps:24,seed:8},[
      {frame:0,source:'state.frames.push(0);state.random=runtime.random();'},
      {frame:1,source:'state.frames.push(1);'},
      {frame:2,source:'state.frames.push(2);throw new Error("resume failure");'},
    ],{frames:[]},'entry');
    const initial=session.checkpoint();
    const options={stopAtFrames:[2],events:[{tick:0,data:{key:'consumed'}},{tick:3,data:{key:'pending'}}]};
    const first=await session.runWithPresentation(4,options);
    const held=await session.runWithPresentation(4,{stopAtFrames:[2]});
    let failure='';try{await session.run(1);}catch(error){failure=String(error);}
    const after=session.checkpoint();
    session.restore(initial);
    const replay=await session.runWithPresentation(4,options);
    return {first,held,failure,after,replay};
  });
  expect(result.first.checkpoint.state.frames).toEqual([0,1]);
  expect(result.first.presentation.map(p=>p.frame)).toEqual([0,1,2]);
  expect(result.first.stoppedAt).toBe(2);
  expect(result.first.events).toEqual([{tick:0,data:{key:'consumed'}}]);
  expect(result.held.presentation).toHaveLength(1);
  expect(result.failure).toContain('resume failure');
  expect(result.after).toEqual(result.first.checkpoint);
  expect(result.replay).toEqual(result.first);
  await expect(page.locator('iframe[title="Isolated script frame"]')).toHaveCount(0);
});

