for(const mode of ['success','write-failure','cancel','close-failure','source-change','dialog-close','commit-close','saved'] as const)test(`Prepared WAV save UI ${mode} preserves transactional files`,async({page})=>{
  const p=newProject();p.width=p.height=10;p.duration=120;
  if(mode==='saved'){p.assets=[{id:'a',path:'assets/audio/a.wav',audio:{name:'A',format:'pcm16-wav',sampleRate:8000,channels:1,frames:3}}];p.audioClips=[{id:'clip',assetId:'a',startFrame:0,offsetSamples:0,gain:1}];}
  await page.addInitScript(({p,mode})=>{
    localStorage.setItem('splash-recovery-v1',JSON.stringify({project:p,folder:null,manifest:null}));
    const state={name:'gif-save-'+crypto.randomUUID(),writing:false,closes:0,aborts:0,sizes:[] as number[],active:0,maxActive:0};
    Object.assign(window,{videoFileTest:state,showSaveFilePicker:async()=>{
      const root=await navigator.storage.getDirectory(),file=await root.getFileHandle(state.name,{create:true});
      const initial=await file.createWritable();await initial.write('original');await initial.close();
      return {createWritable:async()=>{
        const raw=await file.createWritable(),writer=raw.getWriter();let release:()=>void=()=>{};
        return {getWriter:()=>({
          write:async(chunk:Uint8Array)=>{state.writing=true;state.sizes.push(chunk.length);state.active++;state.maxActive=Math.max(state.maxActive,state.active);if(mode==='write-failure'&&state.sizes.length===3)throw new Error('injected write failure');if((mode==='cancel'||mode==='source-change'||mode==='dialog-close')&&state.sizes.length===2){await new Promise<void>(r=>{release=r;});return;}await writer.write(chunk);await new Promise(r=>setTimeout(r,2));state.active--;},
          close:async()=>{state.closes++;if(mode==='commit-close')await new Promise<void>(resolve=>{Object.assign(window,{finishWavClose:resolve});});if(mode==='close-failure')throw new Error('injected close failure');await writer.close();},
          abort:async(reason:unknown)=>{state.aborts++;release();await writer.abort(reason);},releaseLock:()=>writer.releaseLock(),
        })};
      }};
    }});
  },{p,mode});
  let streamWorkers=0,streamClosed=0;page.on('worker',w=>{if(w.url().includes('wav-chunk-worker-')){streamWorkers++;w.on('close',()=>streamClosed++);}});
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('button',{name:'Control',exact:true}).click();await page.getByRole('button',{name:mode==='saved'?'Preview saved audio...':'Preview audio...',exact:true}).click();
  await page.getByLabel(mode==='saved'?'WAV for assets/audio/a.wav':'PCM16 WAV file').setInputFiles({name:'save.wav',mimeType:'audio/wav',buffer:Buffer.from(pcm16WavFixture([[0,16384,-32768]]))});
  await page.getByRole('button',{name:'Prepare audio',exact:true}).click();await expect(page.getByText(/Audio prepared. Playback starts/)).toBeVisible();
  const before=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));let downloads=0;page.on('download',()=>downloads++);
  await page.getByRole('button',{name:'Save prepared WAV to file...',exact:true}).click();
  if(mode==='cancel'||mode==='source-change'||mode==='dialog-close'){
    await expect.poll(()=>page.evaluate(()=>(window as unknown as {videoFileTest:{sizes:number[]}}).videoFileTest.sizes.length)).toBe(2);
    if(mode==='cancel')await page.getByRole('button',{name:'Cancel WAV export',exact:true}).click();
    else if(mode==='dialog-close')await page.getByRole('button',{name:'Close dialog',exact:true}).click();
    else await page.getByLabel('Audio output sample rate').selectOption('16000');
    await expect.poll(()=>page.evaluate(()=>(window as unknown as {videoFileTest:{aborts:number}}).videoFileTest.aborts)).toBe(1);
  }else if(mode==='commit-close'){
    await expect(page.getByText('Finishing WAV file...',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Cancel WAV export',exact:true})).toHaveCount(0);await expect(page.getByRole('button',{name:'Prepare audio',exact:true})).toBeDisabled();
    await page.getByRole('button',{name:'Close dialog',exact:true}).click();await page.evaluate(()=>Reflect.get(window,'finishWavClose')());
    await expect.poll(()=>page.evaluate(async()=>{const state=Reflect.get(window,'videoFileTest');return (await (await (await navigator.storage.getDirectory()).getFileHandle(state.name)).getFile()).size;})).toBeGreaterThan(8);
  }else if(mode==='success'||mode==='saved')await expect(page.getByText('WAV file saved. PCM16 quantization; no dithering.',{exact:true})).toBeVisible();
  else await expect(page.getByRole('alert')).toContainText(mode==='write-failure'?'injected write failure':'injected close failure');
  const result=await page.evaluate(async()=>{
    const state=(window as unknown as {videoFileTest:{name:string;aborts:number;closes:number;sizes:number[];maxActive:number}}).videoFileTest,root=await navigator.storage.getDirectory();
    const file=await (await root.getFileHandle(state.name)).getFile(),bytes=Array.from(new Uint8Array(await file.arrayBuffer()));await root.removeEntry(state.name);return {...state,bytes};
  });
  if(mode==='success'||mode==='commit-close'||mode==='saved'){const decoded=decodePcm16Wav(new Uint8Array(result.bytes));expect(decoded.sampleRate).toBe(8000);expect(Array.from(decoded.channels[0].slice(0,3))).toEqual([0,0.5,-1]);expect(decoded.frames).toBe(Math.round(p.duration*8000/p.fps));expect(result.closes).toBe(1);expect(result.aborts).toBe(0);expect(result.sizes[0]).toBe(44);expect(result.sizes.length).toBeGreaterThan(3);expect(Math.max(...result.sizes)).toBeLessThanOrEqual(32768);expect(result.maxActive).toBe(1);}
  else{expect(result.bytes).toEqual(Array.from(new TextEncoder().encode('original')));expect(result.aborts).toBe(1);}
  expect(streamWorkers).toBe(1);await expect.poll(()=>streamClosed).toBe(streamWorkers);
  expect(downloads).toBe(0);expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);
});

for(const count of [1,2])test(`chunked WAV ${count} channels decodes independently in Chromium`,async({page})=>{
 const channels=Array.from({length:count},(_,c)=>Float32Array.from({length:257},(_,i)=>[-1,-0.3,0,0.3,1][(i+c)%5]));
 const chunks:Uint8Array[]=[];const receipt=writePcm16Wav(channels,8000,c=>{chunks.push(c);},{chunkFrames:31});const bytes=new Uint8Array(receipt.bytesWritten);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}await page.goto('/');
 const actual=await page.evaluate(async bytes=>{const context=new OfflineAudioContext(2,257,8000),buffer=await context.decodeAudioData(new Uint8Array(bytes).buffer);return {rate:buffer.sampleRate,length:buffer.length,channels:Array.from({length:buffer.numberOfChannels},(_,i)=>Array.from(buffer.getChannelData(i)))};},Array.from(bytes));
 expect([actual.rate,actual.length,actual.channels.length]).toEqual([8000,257,count]);
 for(let c=0;c<count;c++)for(let i=0;i<257;i++)expect(Math.abs(actual.channels[c][i]-channels[c][i])).toBeLessThanOrEqual(2/32768);
});

test('WAV pull worker waits for acknowledgements and transfers exact chunks',async({page})=>{
 const parts=await Promise.all(['wav-encode.ts','wav-chunk-processor.ts','wav-chunk-worker.ts'].map(name=>fs.readFile('packages/audio/src/'+name,'utf8')));
 const worker=await transformWithEsbuild(parts.map(s=>s.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,''),'wav-pull-test.ts',{loader:'ts',target:'es2022'});
 await page.route('**/wav-pull-test.js',route=>route.fulfill({contentType:'text/javascript',body:worker.code}));await page.goto('/');
 const result=await page.evaluate(async()=>{
  const worker=new Worker('/wav-pull-test.js',{type:'module'}),messages:{type:string;sequence:number;bytes?:Uint8Array;receipt?:{bytesWritten:number}}[]=[];
  let resolve:((value:typeof messages[number])=>void)|undefined;
  worker.onmessage=e=>{messages.push(e.data);resolve?.(e.data);resolve=undefined;};
  const next=()=>new Promise<typeof messages[number]>((r,reject)=>{const timer=setTimeout(()=>reject(Error('worker response timeout')),3000);resolve=value=>{clearTimeout(timer);r(value);};});
  try{
   const source=new Float32Array([-1,0,0.5,1,-0.25]),pending=next();worker.postMessage({type:'start',channels:[source],sampleRate:8000,options:{chunkFrames:2}},[source.buffer]);
   let reply=await pending;await new Promise(r=>setTimeout(r,50));if(messages.length!==1)throw Error('unsolicited chunks');
   const chunks:Uint8Array[]=[];
   while(reply.type==='chunk'){chunks.push(reply.bytes!);const response=next();worker.postMessage({type:'ack',sequence:reply.sequence});reply=await response;}
   if(reply.type!=='done')throw Error('missing receipt');const bytes=new Uint8Array(reply.receipt!.bytesWritten);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
   return {detached:source.byteLength,bytes:Array.from(bytes),sizes:chunks.map(c=>c.length),sequence:reply.sequence};
  }finally{worker.terminate();}
 });
 expect(result.detached).toBe(0);expect(result.sizes).toEqual([44,4,4,2]);expect(result.sequence).toBe(4);expect(Array.from(decodePcm16Wav(new Uint8Array(result.bytes)).channels[0])).toEqual([-1,0,0.5,32767/32768,-0.25]);
});

test('WAV streaming host applies backpressure and cleans failed or cancelled sinks',async({page})=>{
 const parts=await Promise.all(['wav-encode.ts','wav-chunk-processor.ts','wav-chunk-worker.ts'].map(name=>fs.readFile('packages/audio/src/'+name,'utf8')));
 const worker=await transformWithEsbuild(parts.map(s=>s.replace(/^import[^\n]+\n/gm,'')).join('\n').replace(/export /g,''),'wav-stream-worker-test.ts',{loader:'ts',target:'es2022'});
 const source=(await fs.readFile('packages/audio/src/wav-chunk-async.ts','utf8')).replace(/^import[^\n]+\n/gm,'').replace("new URL('./wav-chunk-worker.ts',import.meta.url)","new URL('/wav-stream-worker-test.js',location.href)");
 const host=await transformWithEsbuild(source.replace(/export /g,'')+'\nObject.assign(window,{streamPcm16Wav});','wav-stream-host.ts',{loader:'ts',target:'es2022'});
 let created=0,closed=0;page.on('worker',w=>{created++;w.on('close',()=>closed++);});await page.route('**/wav-stream-worker-test.js',route=>route.fulfill({contentType:'text/javascript',body:worker.code}));await page.goto('/');await page.addScriptTag({content:host.code});
 for(const mode of ['success','failure','cancel','timeout','retry']){
  const actual=await page.evaluate(async mode=>{
   const api=window as unknown as {streamPcm16Wav:typeof import('../../packages/audio/src/wav-chunk-async').streamPcm16Wav},input=Float32Array.from({length:33001},(_,i)=>(i%5-2)/2),controller=new AbortController();
   let active=0,maxActive=0,calls=0,sinkAborted=false,lateRelease:(()=>void)|undefined;
   const chunks:Uint8Array[]=[];
   try{
    const pending=api.streamPcm16Wav([input],8000,async(bytes,signal)=>{
     calls++;active++;maxActive=Math.max(maxActive,active);signal.addEventListener('abort',()=>{sinkAborted=true;},{once:true});
     if(mode==='failure')throw Error('sink rejected');
     if(mode==='cancel'){controller.abort(Error('sink cancelled'));await new Promise<void>(r=>{lateRelease=r;});}
     else if(mode==='timeout')await new Promise<void>(r=>{lateRelease=r;});
     else{chunks.push(structuredClone(bytes,{transfer:[bytes.buffer]}));await new Promise(r=>setTimeout(r,5));}
     active--;
    },{signal:controller.signal,timeoutMs:mode==='timeout'?300:5000,chunkFrames:4096});
    input.fill(0);const receipt=await pending,bytes=new Uint8Array(receipt.bytesWritten);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}
    return {receipt,bytes:Array.from(bytes),calls,maxActive,inputAttached:input.byteLength};
   }catch(error){lateRelease?.();await new Promise(r=>setTimeout(r,30));return {error:String(error),calls,maxActive,sinkAborted};}
  },mode);
  if(mode==='success'||mode==='retry'){
   expect(actual.receipt).toEqual({bytesWritten:66046,frames:33001,sampleRate:8000,channelCount:1});expect(actual.calls).toBe(10);expect(actual.maxActive).toBe(1);expect(actual.inputAttached).toBe(132004);
   const decoded=decodePcm16Wav(new Uint8Array(actual.bytes!));expect(Array.from(decoded.channels[0].slice(0,5))).toEqual([-1,-0.5,0,0.5,32767/32768]);expect(decoded.frames).toBe(33001);
  }else{expect(actual.error).toMatch(mode==='failure'?/sink rejected/:mode==='cancel'?/sink cancelled/:/timed out/);expect(actual.calls).toBe(1);expect(actual.sinkAborted).toBe(true);}
  await expect.poll(()=>closed).toBe(created);
 }
});

test('script state predicates stop at committed values and preserve atomic replay',async({page})=>{
  await loadScriptSessionForTest(page);
  const result=await page.evaluate(async()=>{
    const api=window as unknown as {createScriptSession:typeof import('../../packages/scripting/src/session').createScriptSession};
    const session=api.createScriptSession({duration:4,fps:24,seed:8},[
      {frame:0,source:'state.n++;state.frames.push(0);state.random=runtime.random();'},
      {frame:1,source:'state.n++;state.frames.push(1);'},
      {frame:2,source:'state.frames.push(2);throw new Error("resume failure");'},
    ],{frames:[],n:0},'entry');
    const initial=session.checkpoint();
    const options={stopWhenState:[{path:['n'],equals:2}],events:[{tick:0,data:{key:'consumed'}},{tick:3,data:{key:'pending'}}]};
    const first=await session.runWithPresentation(4,options);
    const held=await session.runWithPresentation(4,{stopWhenState:[{path:['n'],equals:2}]});
    let failure='';try{await session.run(1);}catch(error){failure=String(error);}
    const after=session.checkpoint();
    session.restore(initial);
    const replay=await session.runWithPresentation(4,options);
    return {first,held,failure,after,replay};
  });
  expect(result.first.checkpoint.state.frames).toEqual([0,1]);
  expect(result.first.presentation.map(p=>p.frame)).toEqual([0,1,2]);
  expect(result.first.stoppedOnState).toEqual([0]);expect(result.first.stoppedAt).toBeUndefined();expect(result.first.checkpoint.state.n).toBe(2);
  expect(result.first.events).toEqual([{tick:0,data:{key:'consumed'}}]);
  expect(result.held.presentation).toHaveLength(1);
  expect(result.failure).toContain('resume failure');
  expect(result.after).toEqual(result.first.checkpoint);
  expect(result.replay).toEqual(result.first);
  await expect(page.locator('iframe[title="Isolated script frame"]')).toHaveCount(0);
});

test('script inspector runs to state value with zero-step queues and replay',async({page})=>{
  const p=newProject();p.duration=4;p.width=120;p.height=80;
  p.frameScripts=[0,1,2].map(frame=>({frame,source:"state.visits = typeof state.visits === 'number' ? state.visits + 1 : 1;"}));
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const before=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  await d.getByLabel('Render detached artwork').check();
  await d.getByRole('button',{name:'Prepare script preview',exact:true}).click();
  await expect(d.getByRole('status')).toHaveText('Ready. No scripts have run.');
  await d.getByLabel('State condition value',{exact:true}).fill('1+1');
  await d.getByRole('button',{name:'Run to state value',exact:true}).click();
  await expect(d.getByRole('status')).toContainText('JSON primitive');
  await expect(d.getByLabel('Script preview state')).toHaveText('{}');
  await expect(d.getByLabel('State condition value')).toHaveValue('1+1');
  await d.getByLabel('State condition path').fill('["visits"]');
  await d.getByLabel('State condition value').fill('2');
  await d.getByRole('button',{name:'Run to state value',exact:true}).click();
  await expect(d.getByRole('status')).toHaveText('State condition matched at frame 3 after 2 script ticks.');
  await expect(d.getByLabel('Script preview state')).toContainText('"visits": 2');
  await d.getByLabel('Capture keys in target').check();
  await d.getByRole('button',{name:'Keyboard capture target',exact:true}).press('a');
  await expect(d.getByLabel('Queued keyboard inputs')).toContainText('2 keyboard');
  const image=await d.getByAltText('Script preview artwork').getAttribute('src');
  await d.getByRole('button',{name:'Run to state value',exact:true}).click();
  await expect(d.getByRole('status')).toHaveText('State condition matched at frame 3 after 0 script ticks.');
  expect(await d.getByAltText('Script preview artwork').getAttribute('src')).toBe(image);
  await expect(d.getByLabel('Queued keyboard inputs')).toContainText('2 keyboard');
  await d.getByRole('button',{name:'Step script tick',exact:true}).click();
  await expect(d.getByRole('status')).toHaveText('Completed 1 script tick.');
  await expect(d.getByLabel('Script preview state')).toContainText('"visits": 3');
  await d.getByLabel('Run-to-state tick budget',{exact:true}).fill('1');
  await d.getByRole('button',{name:'Run to state value',exact:true}).click();
  await expect(d.getByRole('status')).toHaveText('Completed 1 script tick. Tick budget exhausted before target.');
  await d.getByRole('button',{name:'Replay retained script history',exact:true}).click();
  await expect(d.getByRole('status')).toHaveText('Replay matched 4 ticks and 0 seek inputs.');
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);
});

for(const changed of [false,true])test(`remembered detached preview preserves recovery and rejects edited interiors ${changed}`,async({page})=>{
 const project=newProject();project.width=200;project.height=100;project.duration=10;
 const shape:Vector={id:'preview-motion',kind:'rectangle',x:0,y:20,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
 project.layers[0].keys=[{frame:0,shapes:[shape]},{frame:8,shapes:[{...shape,x:80}]}];createBasicMotionSpan(project,[project.layers[0].id],0,8,'linear');
 project.layers[0].keys[8].shapes[0].x=160;
 if(changed)project.layers[0].keys[3].shapes[0].x=999;
 await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),project);
 await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
 const box=(await page.getByLabel('Timeline frames').boundingBox())!;await page.mouse.click(box.x+9,box.y+40);await page.keyboard.down('Shift');await page.mouse.click(box.x+81,box.y+40);await page.keyboard.up('Shift');
 await page.getByRole('button',{name:'Select remembered frames 1–9',exact:true}).click();
 const before=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
 await page.getByRole('button',{name:'Preview remembered motion…',exact:true}).click();
 const dialog=page.getByRole('dialog',{name:'Preview remembered motion',exact:true});
 await dialog.getByLabel('Remembered preview frame').fill('5');await dialog.getByRole('button',{name:'Render remembered pose',exact:true}).click();
 if(changed){await expect(dialog.getByRole('status')).toContainText('Generated keys changed');await expect(dialog.getByRole('img')).toHaveCount(0);}
 else{
  await expect(dialog.getByRole('status')).toContainText('Remembered pose at frame 5');
  const pixels=await dialog.getByRole('img').evaluate(async image=>{const img=image as HTMLImageElement;await img.decode();const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;const c=canvas.getContext('2d')!;c.drawImage(img,0,0);return [Array.from(c.getImageData(85,25,1,1).data),Array.from(c.getImageData(45,25,1,1).data)]});
  expect(pixels[0]).toEqual([255,0,0,255]);expect(pixels[1]).not.toEqual([255,0,0,255]);
  await dialog.getByLabel('Remembered preview frame').fill('99');await dialog.getByRole('button',{name:'Render remembered pose',exact:true}).click();await expect(dialog.getByRole('status')).toContainText('integer inside');await expect(dialog.getByRole('img')).toHaveCount(0);
  await dialog.getByLabel('Remembered preview frame').fill('1');await dialog.getByRole('button',{name:'Render remembered pose',exact:true}).click();await expect(dialog.getByRole('status')).toContainText('Remembered pose at frame 1');
 }
 await dialog.getByRole('button',{name:'Close dialog',exact:true}).click();await expect(dialog).toHaveCount(0);
 expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);expect(await page.locator('iframe').count()).toBe(0);
});

