 const b={...a,id:'later',name:'Later',locked:false,motionSpans:[],keys:[{frame:0,shapes:[] as Vector[]},{frame:6,shapes:[{...art,id:'late',y:50,fill:'#00ff00'}]},{frame:10,shapes:[{...art,id:'late',x:80,y:50,fill:'#00ff00'}]}]};project.layers.push(b);createBasicMotionSpan(project,[b.id],6,10,'linear');b.keys.find(k=>k.frame===10)!.shapes[0].x=160;if(edited)b.keys.find(k=>k.frame===8)!.shapes[0].x=999;
