 await page.getByRole('button',{name:'Control',exact:true}).click();await page.getByRole('button',{name:'Preview remembered timeline…',exact:true}).click();
 const d=page.getByRole('dialog',{name:'Preview remembered motion',exact:true});await d.getByLabel('Remembered preview frame').fill('5');await d.getByRole('button',{name:'Render remembered pose',exact:true}).click();await d.getByLabel('Sampled root artwork').selectOption(JSON.stringify([layer.id,'pick']));
 const preview=d.getByRole('button',{name:'Preview proposed move',exact:true}),proposed=d.getByRole('img',{name:'Proposed moved pose',exact:true}),source=d.getByRole('img',{name:'Remembered motion pose',exact:true}),offset=d.getByLabel('Picked pose X offset'),apply=d.getByRole('button',{name:'Promote and move picked artwork',exact:true});
