for(const mode of ['shape','movie','graphic-route','button'])test(`detached replay samples stored root opacity without resetting exposures: ${mode}`,async({page})=>{
 const project=newProject();project.duration=10;project.width=80;project.height=40;project.background='#ffffff';
 const art:Vector={id:'ink',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],opacity:0.5};
 const definition={id:'child',name:'Child',width:20,height:20,shapes:[art],timeline:{duration:3,keys:[{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]}]}};
 const button={...structuredClone(definition),id:'button',name:'Button',buttonStates:{up:0,over:1,down:2,hit:0}};
 project.symbols=mode==='graphic-route'?[definition,button]:mode==='button'?[button]:[definition];
 const root:Vector=mode==='shape'?{...art,id:'root',opacity:0}:{...art,id:'root',kind:'symbol',symbolId:mode==='button'?'button':'child',symbolPlayback:{mode:mode==='movie'?'movie':'loop',firstFrame:0},opacity:0};
 const sibling:Vector={...art,id:'sibling',x:40,fill:'#000000',opacity:1};
 project.layers[0].keys=[{frame:0,shapes:[root,sibling]},{frame:7,shapes:[sibling]},{frame:8,shapes:[{...root,opacity:0.75},sibling]}];
 project.opacityBindings=[{layerId:project.layers[0].id,shapeId:'root',start:1,end:5,keys:[{frame:1,opacity:0,ease:{kind:'cubic',x1:1/3,x2:2/3,y1:0,y2:0}},{frame:5,opacity:1}]}];
 project.frameScripts=[{frame:0,source:'throw new Error("must remain inert")'}];
 await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),project);await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();const before=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
 await page.getByRole('button',{name:'Control',exact:true}).click();await page.getByRole('button',{name:'Preview remembered timeline…',exact:true}).click();const d=page.getByRole('dialog',{name:'Preview remembered motion',exact:true});
 for(const f of [0,3,5,6,8]){
  await d.getByLabel('Remembered preview frame').fill(String(f+1));await d.getByRole('button',{name:'Render remembered pose',exact:true}).click();await expect(d.getByRole('status')).toContainText(`Remembered pose at frame ${f+1}.`);
  const [pixel,other]=await d.getByRole('img',{name:'Remembered motion pose'}).evaluate(async(el)=>{const img=el as HTMLImageElement;await img.decode();const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const x=c.getContext('2d')!;x.drawImage(img,0,0);return [5,45].map(px=>Array.from(x.getImageData(px,5,1,1).data));});
  const alpha=(mode==='shape'?1:0.5)*(f===3?0.125:f===5?1:f===8?0.75:0),tint=f===5&&(mode==='movie'||mode==='graphic-route')?2:0;
  for(let i=0;i<3;i++)expect(Math.abs(pixel[i]-(i===tint?255:Math.round(255*(1-alpha))))).toBeLessThanOrEqual(1);expect(other).toEqual([0,0,0,255]);
 }
 await d.getByRole('button',{name:'Close dialog',exact:true}).click();expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(before);
});

