for (const routeButtons of [false, true]) test(`stage scrub and WebGL play held graphic opacity (button routing ${routeButtons})`, async ({ page }) => {
  const p = newProject();
  p.duration = 4;
  p.fps = 3;
  p.width = 120;
  p.height = 80;
  p.background = '#ffffff';
  const art: Vector = {id:'ink', kind:'rectangle', x:0, y:0, width:120, height:80, rotation:0,
    fill:'#ff0000', stroke:'#000000', strokeWidth:0, points:[]};
  p.symbols = [{id:'graphic', name:'Graphic', width:120, height:80, shapes:[art],
    timeline:{duration:2, keys:[{frame:1, shapes:[{...art, fill:'#00ff00'}]}]}}];
  if (routeButtons) p.symbols.push({...structuredClone(p.symbols[0]), id:'button',
    buttonStates:{up:0, over:1, down:1, hit:0}});
  p.layers[0].keys[0].shapes = [{...art, id:'root', kind:'symbol', symbolId:'graphic', opacity:0}];
  p.opacityBindings = [{layerId:p.layers[0].id, shapeId:'root', start:1, end:2,
    keys:[{frame:1, opacity:1},{frame:2, opacity:0.5}]}];
  await page.addInitScript(project => localStorage.setItem('splash-recovery-v1', JSON.stringify({project, folder:null, manifest:null})), p);
  await page.goto('/');
  await recoverTestMovieProject(page);
  const recovery = () => page.evaluate(() => localStorage.getItem('splash-recovery-v1'));
  const before = await recovery();
  const timeline = page.getByLabel('Timeline frames');
  const stage = page.getByLabel('Drawing stage');
  const stagePixel = () => stage.evaluate(el => {
    const c = el as HTMLCanvasElement;
    return Array.from(c.getContext('2d')!.getImageData(c.width/2+5,c.height/2+5,1,1).data);
  });
  for (const [frame, color] of [[1,[0,255,0,255]], [2,[255,127,127,255]], [3,[255,255,255,255]]] as const) {
    await timeline.click({position:{x:9+18*frame,y:40}});
    await expect.poll(stagePixel).toEqual(color);
  }
  await stage.focus();
  await page.keyboard.press('Control+Enter');
  const movie = page.getByRole('dialog', {name:'Test movie', exact:true});
  await expect(movie.getByRole('button', {name:'Close ×', exact:true})).toBeFocused();
  await expect(page.getByText('WebGL · PixiJS',{exact:true})).toBeVisible();
  const preview = page.getByLabel('Test movie interaction');
  const previewPixel = async () => {
    const png = (await preview.screenshot()).toString('base64');
    return page.evaluate(async data => {
      const image = new Image();
      image.src = 'data:image/png;base64,' + data;
      await image.decode();
      const c = document.createElement('canvas');
      const ctx = c.getContext('2d')!;
      ctx.drawImage(image,Math.floor(image.width/2),Math.floor(image.height/2),1,1,0,0,1,1);
      return Array.from(ctx.getImageData(0,0,1,1).data);
    }, png);
  };
  await expect.poll(previewPixel, {intervals:[50]}).toEqual([0,255,0,255]);
  await expect.poll(async () => {
    const [r,g,b] = await previewPixel();
    return r === 255 && Math.abs(g-128)<=2 && Math.abs(b-128)<=2;
  }, {intervals:[50]}).toBe(true);
  await page.keyboard.press('Escape');
  await expect(movie).toHaveCount(0);
  await expect(stage).toBeFocused();
  expect(await recovery()).toBe(before);
});

