  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('button',{name:'Selection',exact:true}).click();
  const box = (await page.getByLabel('Drawing stage').boundingBox())!;
  const pick = (offset: number) => page.mouse.click(box.x+box.width/2+offset,box.y+box.height/2+8);
  const add = page.getByRole('button',{name:'Add opacity channel',exact:true});
