test('revise and remove the selected opacity interval with exact custom keys and history', async ({page}) => {
  const p = newProject(), layer = p.layers[0];
  p.duration = 10;
  const art: Vector = {id:'a',kind:'rectangle',x:p.width/2,y:p.height/2,width:40,height:40,
    rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  layer.keys[0].shapes = [art];
  const later = {layerId:layer.id,shapeId:'a',start:6,end:9,keys:[{frame:8,opacity:0.3}]};
  const target = {layerId:layer.id,shapeId:'a',start:0,end:4,keys:[
    {frame:0,opacity:7/997,ease:{kind:'cubic' as const,x1:0.3,y1:0,x2:0.8,y2:1}},
    {frame:4,opacity:0.7},
  ]};
  p.opacityBindings = [later,target];
  await page.addInitScript(project => localStorage.setItem('splash-recovery-v1', JSON.stringify({
    project, folder:null, manifest:null,
  })),p);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('button',{name:'Selection',exact:true}).click();
  const stage = page.getByLabel('Drawing stage');
  const box = (await stage.boundingBox())!;
  const pick = () => page.mouse.click(box.x+box.width/2+8,box.y+box.height/2+8);
  const read = () => page.evaluate(() => JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const edit = page.getByRole('button',{name:'Edit opacity channel',exact:true});
  const draft = page.getByRole('region',{name:'Edit opacity channel'});
  const apply = draft.getByRole('button',{name:'Apply opacity channel'});
  await pick();
  await edit.click();
  await expect(draft.getByRole('group',{name:'Opacity key 1'}).getByLabel('Outgoing easing')).toHaveValue('custom');
  await draft.getByLabel('Last frame').fill('7');
  await apply.click();
  await expect(draft.getByRole('alert')).toContainText('overlap');
  expect(await read()).toEqual(p);
  await draft.getByLabel('Last frame').fill('6');
  await draft.getByRole('group',{name:'Opacity key 2'}).getByLabel('Opacity (%)',{exact:true}).fill('60');
  await apply.click();
  const revised = structuredClone(p);
  revised.opacityBindings![1].end = 5;
  revised.opacityBindings![1].keys = [target.keys[0],{frame:4,opacity:0.6}];
  expect(await read()).toEqual(revised);
  await edit.click();
  await draft.getByRole('button',{name:'Remove opacity channel'}).click();
  const removed = {...p,opacityBindings:[later]};
  expect(await read()).toEqual(removed);
  await stage.focus();
  for (const [shortcut,expected] of [['Control+z',revised],['Control+z',p],
    ['Control+Shift+z',revised],['Control+Shift+z',removed]] as const) {
    await page.keyboard.press(shortcut);
    expect(await read()).toEqual(expected);
  }
  await page.getByLabel('Timeline frames').click({position:{x:135,y:40}});
  await pick();
  await edit.click();
  await expect(draft.getByLabel('First frame')).toHaveValue('7');
  await page.getByLabel('Timeline frames').click({position:{x:9,y:40}});
  await expect(draft).toHaveCount(0);
  expect(await read()).toEqual(removed);
  await page.getByLabel('Timeline frames').click({position:{x:135,y:40}});
  await pick();
  await edit.click();
  await draft.getByRole('button',{name:'Remove opacity channel'}).click();
  const unbound = structuredClone(p);
  delete unbound.opacityBindings;
  expect(await read()).toEqual(unbound);
  await stage.focus();
  await page.keyboard.press('Control+z');
  expect(await read()).toEqual(removed);
});

for (const cut of [false,true]) test(`stage removal respects opacity later in the hold and preserves clipboard (cut ${cut})`, async ({page}) => {
  const p = newProject(), layer = p.layers[0];
  p.duration = 9;
  const art: Vector = {id:'target',kind:'rectangle',x:p.width/2,y:p.height/2,width:30,height:30,
    rotation:0,fill:'#aa0000',stroke:'#000000',strokeWidth:0,points:[],groups:['pair']};
  const peer = {...art,id:'peer',x:art.x+40,fill:'#00bb00'};
  const seed = {...art,id:'seed',x:art.x+90,fill:'#0000cc',groups:[]};
  layer.keys = [0,6].map(frame => ({frame,shapes:structuredClone([art,peer,seed])}));
  p.opacityBindings = [{layerId:layer.id,shapeId:art.id,start:3,end:4,keys:[{frame:3,opacity:0.5}]}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({
    project,folder:null,manifest:null,
  })),p);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('button',{name:'Selection',exact:true}).click();
  const stage = page.getByLabel('Drawing stage'), timeline = page.getByLabel('Timeline frames');
  const read = () => page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const pick = async (dx:number) => {
    const box = (await stage.boundingBox())!;
    const zoom = Number(await page.getByRole('combobox',{name:'Zoom',exact:true}).inputValue());
    await page.mouse.click(box.x+box.width/2+dx*zoom,box.y+box.height/2+12*zoom);
  };
  const press = async (shortcut:string) => {
    await stage.focus();
    await page.keyboard.press(shortcut);
  };
  const remove = cut ? 'Control+x' : 'Delete';
  await pick(102);
  await press('Control+c');
  await timeline.click({position:{x:27,y:40}});
  await pick(12);
  await press(remove);
  await expect(page.getByRole('alert')).toContainText('uniquely');
  await expect(page.getByText('2 vectors selected.',{exact:false})).toBeVisible();
  expect(await read()).toEqual(p);
  await page.getByRole('alert').getByRole('button',{name:'Dismiss'}).click();
  await press('Control+v');
  const pasted = await read();
  expect(pasted.layers[0].keys[0].shapes.map(s=>s.fill)).toEqual([art.fill,peer.fill,seed.fill,seed.fill]);
  await press('Control+z');
  expect(await read()).toEqual(p);
  await timeline.click({position:{x:135,y:40}});
  await pick(12);
  await press(remove);
  const removed = structuredClone(p);
  removed.layers[0].keys[1].shapes = [seed];
  expect(await read()).toEqual(removed);
  await press('Control+z');
  expect(await read()).toEqual(p);
  await press('Control+Shift+z');
  expect(await read()).toEqual(removed);
  await press('Control+v');
  const after = await read();
  expect(after.layers[0].keys[1].shapes.map(s=>s.fill)).toEqual(cut?[seed.fill,art.fill,peer.fill]:[seed.fill,seed.fill]);
  expect(after.opacityBindings).toEqual(p.opacityBindings);
});

for (const stale of [false, true]) test(`distribute remembered motion into independently editable tracks (stale ${stale})`, async ({page}) => {
  const p = newProject(), source = p.layers[0];
  p.duration = 10;
  const art: Vector = {id:'single',kind:'rectangle',x:20,y:40,width:30,height:30,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  source.keys = [0,4,8].map(frame=>({frame,shapes:[{...art,x:20+frame*5},
    {...art,id:'b',groups:['outer'],y:40+frame*10},{...art,id:'c',groups:['outer','inner'],x:80+frame*10}]}));
  createBasicMotionSpan(p,[source.id],0,4,'linear');
  createBasicMotionSpan(p,[source.id],4,8,'out');
  p.opacityBindings = [{layerId:source.id,shapeId:'b',start:0,end:8,keys:[{frame:1,opacity:0.5}]}];
  if (stale) source.keys[6].shapes[1].x++;
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const timeline = page.getByLabel('Timeline frames');
  const cell = (frame:number) => timeline.click({position:{x:9+18*frame,y:40}});
  const read = () => page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  await cell(0);
  await page.getByText('Layer organization',{exact:true}).click();
  await page.getByRole('button',{name:'Distribute artwork to layers',exact:true}).click();
  if (stale) {
    await expect(page.getByRole('alert')).toContainText('Generated keys changed');
    expect(await read()).toEqual(p);
    await page.getByLabel('Drawing stage').focus();
    await page.keyboard.press('Control+z');
    expect(await read()).toEqual(p);
    return;
  }
  const split = await read(), [single,group] = split.layers;
  expect(split.layers).toHaveLength(2);
  expect(split.opacityBindings).toEqual([{...p.opacityBindings[0],layerId:group.id}]);
  for (const [i,key] of source.keys.entries())
    expect([...single.keys[i].shapes,...group.keys[i].shapes]).toEqual(key.shapes);
  for (const layer of split.layers) for (const span of layer.motionSpans!)
    expect(JSON.parse(span.baseline)).toEqual(layer.keys.filter(k=>k.frame>span.start&&k.frame<span.end));
  await cell(0);
  await page.keyboard.down('Shift');
  await cell(4);
  await page.keyboard.up('Shift');
  await page.getByLabel('Remembered motion easing',{exact:true}).selectOption('in');
  await page.getByRole('button',{name:'Apply easing to remembered motion',exact:true}).click();
  const revised = await read();
  expect(revised.layers[0]).toEqual(single);
  expect(revised.layers[1].motionSpans![0].ease).toBe('in');
  expect(revised.layers[1].keys[2].shapes[0].y).toBeLessThan(group.keys[2].shapes[0].y);
  await page.getByLabel('Drawing stage').focus();
  for (const [key, expected] of [['Control+z',split],['Control+z',p],
    ['Control+Shift+z',split],['Control+Shift+z',revised]] as const) {
    await page.keyboard.press(key);
    expect(await read()).toEqual(expected);
  }
});

for(const editor of ['main','symbol'] as const)for(const distance of [false,true])for(const cut of distance?[2,4,6]:[3,4,6])test(`curved waypoint nonzero tangent preserved split in ${editor} at ${cut} (distance ${distance})`,async({page})=>{
  const p=newProject(),layer=p.layers[0],end=distance?8:12;p.duration=end+2;p.width=200;p.height=100;
  const art:Vector={id:'curve',kind:'rectangle',x:0,y:0,width:10,height:10,rotation:90,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  layer.keys=[{frame:0,shapes:[art]},{frame:end,shapes:[{...art,x:distance?96:90,y:distance?96:40,rotation:150}]},{frame:end+1,shapes:[]}];
  createBasicMotionSpan(p,[layer.id],0,end,'linear',undefined,{startX:0,startY:0,endX:0,endY:0,distance,
    curvedWaypoints:true,waypoints:distance?[{x:48,y:48}]:[{x:30,y:30},{x:60,y:10}],
    ...(distance?{waypointTangents:[{x:16-1/4096,y:16+1/4096},{x:16-1/4096,y:16+1/4096},{x:16-1/4096,y:16+1/4096}]}:{}),
    tangent:true,headingOffset:10,headingOffsetEnd:30});
  let original=structuredClone(layer.keys);
  if(editor==='symbol'){
    p.symbols=[{id:'curve-symbol',name:'Curve',width:200,height:100,shapes:original[0].shapes,
      timeline:{duration:end+2,keys:original.slice(1),motionSpans:layer.motionSpans,layers:[]}}];
    layer.keys=[{frame:0,shapes:[]}];delete layer.motionSpans;
  }
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),suffix=editor==='symbol'?' symbol':'';
  const open=async()=>{
    if(editor==='symbol')await page.getByRole('group',{name:'Symbol Curve',exact:true}).getByRole('button',{name:'Edit symbol timeline',exact:true}).click();
  };
  await open();
  if(editor==='main'){
    const box=(await page.getByLabel('Timeline frames').boundingBox())!;
    await page.mouse.click(box.x+9,box.y+40);await page.keyboard.down('Shift');
    await page.mouse.click(box.x+9+18*end,box.y+40);await page.keyboard.up('Shift');
  }
  await page.getByRole('button',{name:`Select remembered${suffix} frames 1–${end+1}`,exact:true}).click();
  // Establish Chromium's own exact generated baseline before preserved reconstruction.
  await page.getByRole('button',{name:`Refresh remembered${suffix} motion`,exact:true}).click();
  if(editor==='symbol')await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  Object.assign(p,await read());
  original=editor==='main'?structuredClone(p.layers[0].keys):
    [{frame:0,shapes:structuredClone(p.symbols![0].shapes)},...structuredClone(p.symbols![0].timeline!.keys)];
  if(editor==='symbol'){
    await open();await page.getByRole('button',{name:`Select remembered symbol frames 1–${end+1}`,exact:true}).click();
  }
  const split=page.getByRole('button',{name:`Split and regenerate remembered${suffix} motion`,exact:true}),
    input=page.getByLabel(`Remembered${suffix} motion split frame`,{exact:true});
  await page.getByLabel(`Preserve simple${suffix} motion when splitting`,{exact:true}).check();
  await input.fill('2');await split.click();
  await expect(page.getByRole('alert')).toContainText(/three frames/i);expect(await read()).toEqual(p);
  await input.fill(String(cut+1));await split.click();
  await expect(page.getByRole('button',{name:`Select remembered${suffix} frames 1–${cut+1}`,exact:true})).toBeVisible();
  await expect(page.getByRole('button',{name:`Select remembered${suffix} frames ${cut+1}–${end+1}`,exact:true})).toBeVisible();
  if(editor==='symbol'){
    await page.getByRole('button',{name:'Undo symbol timeline change',exact:true}).click();
    await page.getByRole('button',{name:'Redo symbol timeline change',exact:true}).click();expect(await read()).toEqual(p);
    await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  }
  const saved=await read(),track=editor==='main'?saved.layers[0]:saved.symbols![0].timeline!;
  expect(saved.schemaVersion).toBe(59);expect(track.motionSpans!.map(s=>[s.start,s.end])).toEqual([[0,cut],[cut,end]]);
  const result=editor==='main'?track.keys:[{frame:0,shapes:saved.symbols![0].shapes},...track.keys];
  expect(result).toEqual(original);
  if(!distance)expect(track.motionSpans![1].path!.curvedWaypoints).toBe(true);
  else expect(track.motionSpans!.every(s=>s.path!.distance && s.path!.tangent)).toBe(true);
  expect(track.motionSpans![1].path!.headingOffsetEnd).toBe(30);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(saved);
  await open();
  for(const interval of [`1–${cut+1}`,`${cut+1}–${end+1}`]){
    await page.getByRole('button',{name:`Select remembered${suffix} frames ${interval}`,exact:true}).click();
    await page.getByRole('button',{name:`Refresh remembered${suffix} motion`,exact:true}).click();
  }
  if(editor==='symbol')await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  const refreshed=await read(),keys=editor==='main'?refreshed.layers[0].keys:
    [{frame:0,shapes:refreshed.symbols![0].shapes},...refreshed.symbols![0].timeline!.keys];
  for(let i=0;i<=end;i++)for(const field of ['x','y','rotation'] as const)
    expect(keys[i].shapes[0][field]).toBeCloseTo(original[i].shapes[0][field],10);
  expect(keys[end+1]).toEqual(original[end+1]);
});

for(const editor of ['main','symbol'] as const)for(const conflict of [false,true])for(const distance of [false,true])
test(`curved tangent reversal in ${editor} (conflict ${conflict}, distance ${distance})`,async({page})=>{
  const p=newProject(),layer=p.layers[0],end=distance?8:12;p.duration=end+2;p.width=200;p.height=100;
  const art:Vector={id:'reversed',kind:'rectangle',x:0,y:0,width:10,height:10,rotation:90,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  layer.keys=[{frame:0,shapes:[art]},{frame:end,shapes:[{...art,x:distance?96:90,y:distance?0:40,rotation:150}]},{frame:end+1,shapes:[]}];
  if(conflict){
    layer.keys[0].shapes.push({...art,id:'other',x:10});
    layer.keys[1].shapes.push({...art,id:'other',x:110,y:distance?0:40,rotation:150});
  }
  createBasicMotionSpan(p,[layer.id],0,end,'in',undefined,{startX:0,startY:0,endX:0,endY:0,distance,
    curvedWaypoints:true,waypoints:distance?[{x:48,y:32}]:[{x:30,y:30},{x:60,y:10}],
    ...(distance?{waypointTangents:[{x:16,y:32},{x:16,y:0},{x:16,y:-32}]}:{}),
    tangent:true,headingOffset:10,headingOffsetEnd:30});
  if(editor==='symbol'){
    p.symbols=[{id:'reverse-curves',name:'Reverse curves',width:200,height:100,shapes:layer.keys[0].shapes,
      timeline:{duration:end+2,keys:layer.keys.slice(1),motionSpans:layer.motionSpans,layers:[]}}];
    layer.keys=[{frame:0,shapes:[]}];delete layer.motionSpans;
  }
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),
    suffix=editor==='symbol'?' symbol':'',open=async()=>{
      if(editor==='symbol')await page.getByRole('group',{name:'Symbol Reverse curves',exact:true}).getByRole('button',{name:'Edit symbol timeline',exact:true}).click();
    };
  await open();
  if(editor==='main'){
    const box=(await page.getByLabel('Timeline frames').boundingBox())!;
    await page.mouse.click(box.x+9,box.y+40);await page.keyboard.down('Shift');
    await page.mouse.click(box.x+9+18*end,box.y+40);await page.keyboard.up('Shift');
  }
  const select=()=>page.getByRole('button',{name:`Select remembered${suffix} frames 1–${end+1}`,exact:true}).click();
  await select();await page.getByRole('button',{name:`Refresh remembered${suffix} motion`,exact:true}).click();
  if(editor==='symbol')await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  const before=await read(),original=editor==='main'?before.layers[0].keys:
    [{frame:0,shapes:before.symbols![0].shapes},...before.symbols![0].timeline!.keys];
  if(editor==='symbol'){await open();await select();}
  await page.getByRole('button',{name:`Reverse remembered${suffix} motion`,exact:true}).click();
  if(conflict){
    await expect(page.getByRole('alert')).toContainText(/shared route/i);expect(await read()).toEqual(before);
    if(editor==='symbol'){
      await expect(page.getByRole('button',{name:'Undo symbol timeline change',exact:true})).toBeDisabled();
      await page.getByRole('button',{name:'Cancel symbol timeline',exact:true}).click();
    }
    return;
  }
  if(editor==='symbol'){
    await page.getByRole('button',{name:'Undo symbol timeline change',exact:true}).click();
    await page.getByRole('button',{name:'Redo symbol timeline change',exact:true}).click();expect(await read()).toEqual(before);
    await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  }
  const saved=await read(),track=editor==='main'?saved.layers[0]:saved.symbols![0].timeline!,
    result=editor==='main'?track.keys:[{frame:0,shapes:saved.symbols![0].shapes},...track.keys],
    prior=editor==='main'?before.layers[0]:before.symbols![0].timeline!;
  expect(track.motionSpans![0].id).toBe(prior.motionSpans![0].id);
  expect(track.motionSpans![0].ease).toBe('out');
  expect(track.motionSpans![0].path!.curvedWaypoints).toBe(true);
  expect(track.motionSpans![0].path!.distance??false).toBe(distance);
  expect(track.motionSpans![0].path!.headingOffsetEnd!-track.motionSpans![0].path!.headingOffset!).toBe(-20);
  for(let i=0;i<=end;i++)expect(result[end-i].shapes).toEqual(original[i].shapes);
  expect(result[end+1]).toEqual(original[end+1]);expect(saved.duration).toBe(before.duration);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(before);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(saved);
  await open();await select();
  await page.getByRole('button',{name:`Refresh remembered${suffix} motion`,exact:true}).click();
  if(editor==='symbol')await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  const refreshed=await read(),keys=editor==='main'?refreshed.layers[0].keys:
    [{frame:0,shapes:refreshed.symbols![0].shapes},...refreshed.symbols![0].timeline!.keys];
  for(let i=0;i<=end;i++)for(const field of ['x','y','rotation'] as const)
    expect(keys[end-i].shapes[0][field]).toBeCloseTo(original[i].shapes[0][field],10);
});

for(const scenario of ['native','cancel','stale','reject'] as const)
test(`main object hierarchy placement owns drag context (${scenario})`,async({page})=>{
  const p=newProject(),layer=p.layers[0];layer.drawingMode='object';
  const a:Vector={id:'moving',kind:'rectangle',x:p.width/2,y:p.height/2,width:30,height:30,
    rotation:27,transform:[1.2,.2,-.1,.8],pivot:{x:4,y:6},
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['moving-group']};
  const member:Vector={...a,id:'member',x:a.x+40,y:a.y+20,groups:['moving-group','child']},
    b:Vector={...a,id:'anchor-first',x:a.x+100,groups:['target','unit']},
    c:Vector={...b,id:'anchor-nested',x:a.x+140,groups:['target','unit','nested']},
    d:Vector={...b,id:'other',x:a.x+180,groups:['target']};
  layer.keys=[{frame:0,shapes:[a,member,b,c,d]}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('button',{name:'Selection',exact:true}).click();
  const stage=page.getByLabel('Drawing stage'),box=(await stage.boundingBox())!;
  await stage.click({position:{x:box.width/2+8,y:box.height/2+8}});
  await page.getByText('Drag or place selected units',{exact:true}).click();
  const source=page.getByRole('button',{name:'Drag selected hierarchy units',exact:true}),
    below=page.getByRole('button',{name:'Place selection below anchor-first in target',exact:true}),
    above=page.getByRole('button',{name:'Place selection above anchor-first in target',exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),
    moving=page.getByText('Moving selected hierarchy units. Escape cancels.',{exact:true});
  await expect(page.getByRole('button',{name:'Place selection below anchor-nested in target',exact:true})).toHaveCount(0);
  const start=async()=>{
    const data=await page.evaluateHandle(()=>new DataTransfer());
    await source.dispatchEvent('dragstart',{dataTransfer:data});await expect(moving).toBeVisible();
    expect(await read()).toEqual(p);return data;
  };
  const drag=async(target:ReturnType<typeof page.getByRole>)=>{
    await source.scrollIntoViewIfNeeded();
    const from=(await source.boundingBox())!;
    await page.mouse.move(from.x+from.width/2,from.y+from.height/2);await page.mouse.down();
    await page.mouse.move(from.x+from.width/2+10,from.y+from.height/2+2,{steps:3});
    await expect(moving).toBeVisible();
    await target.scrollIntoViewIfNeeded();
    const to=(await target.boundingBox())!;
    await page.mouse.move(to.x+to.width/2,to.y+to.height/2,{steps:10});
    await page.mouse.move(to.x+to.width/2+1,to.y+to.height/2);
    await page.mouse.up();
  };
  if(scenario==='native'){
    await drag(below);
    const moved=structuredClone(p),aa={...a,groups:['target','moving-group']},mm={...member,groups:['target','moving-group','child']};
    moved.layers[0].keys[0].shapes=[aa,mm,b,c,d];await expect.poll(read).toEqual(moved);
    await drag(above);
    const reordered=structuredClone(moved);reordered.layers[0].keys[0].shapes=[b,c,aa,mm,d];
    await expect.poll(read).toEqual(reordered);
    await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(moved);
    await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
    await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(moved);
    return;
  }
  if(scenario==='cancel'){
    for(const action of ['escape','end','blur']){
      const data=await start();
      if(action==='escape')await page.keyboard.press('Escape');
      else if(action==='end')await source.dispatchEvent('dragend',{dataTransfer:data});
      else await page.evaluate(()=>window.dispatchEvent(new Event('blur')));
      await expect(moving).toHaveCount(0);
      await below.dispatchEvent('drop',{dataTransfer:data});expect(await read()).toEqual(p);
      await data.dispose();
    }
    const external=await page.evaluateHandle(()=>{const data=new DataTransfer();data.setData('application/x-splash-hierarchy','forged');return data;});
    await below.dispatchEvent('drop',{dataTransfer:external});expect(await read()).toEqual(p);await external.dispose();
  }else if(scenario==='stale'){
    let data=await start();
    await page.getByLabel('Timeline frames').click({position:{x:9+18,y:40}});
    await expect(moving).toHaveCount(0);await expect(source).toHaveCount(0);expect(await read()).toEqual(p);
    await page.getByLabel('Timeline frames').click({position:{x:9,y:40}});
    const current=(await stage.boundingBox())!;
    await stage.click({position:{x:current.width/2+8,y:current.height/2+8}});
    await page.getByText('Drag or place selected units',{exact:true}).click();
    await below.dispatchEvent('drop',{dataTransfer:data});expect(await read()).toEqual(p);await data.dispose();
    data=await start();
    await page.getByRole('button',{name:'Toggle lock '+layer.name,exact:true}).click();
    const locked=await read();expect(locked.layers[0].locked).toBe(true);
    await expect(moving).toHaveCount(0);await expect(source).toHaveCount(0);
    expect(await read()).toEqual(locked);await data.dispose();
    await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
    return;
  }else{
    await drag(page.getByRole('button',{name:'Place selection into moving-group / child',exact:true}));
    await expect(page.getByRole('alert')).toContainText('itself');expect(await read()).toEqual(p);
    const data=await start();await data.evaluate(value=>value.setData('application/x-splash-hierarchy','forged'));
    await below.dispatchEvent('drop',{dataTransfer:data});expect(await read()).toEqual(p);await data.dispose();
    // The same target remains available as an explicit keyboard-accessible action.
    await below.click();
    const moved=await read();expect(moved.layers[0].keys[0].shapes[0].groups).toEqual(['target','moving-group']);
    await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  }
  await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
});

for(const nested of [false,true])test(`isolated hierarchy drag retains draft and enclosing history (nested ${nested})`,async({page})=>{
  const p=newProject(),a:Vector={id:'moving',kind:'rectangle',x:10,y:10,width:20,height:20,
    rotation:27,transform:[1.2,.2,-.1,.8],pivot:{x:4,y:6},fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['moving-unit']},
    member:Vector={...a,id:'member',x:35,groups:['moving-unit','child']},
    b:Vector={...a,id:'anchor-first',x:70,groups:['target','unit']},
    c:Vector={...b,id:'anchor-child',x:100,groups:['target','unit','nested']};
  const source=[b,c,a,member];
  if(nested)for(const item of source)item.groups=['enclosing',...item.groups!];
  p.symbols=[{id:'hierarchy-symbol',name:'Hierarchy',width:200,height:100,shapes:source}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),
    parent=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    editor=page.getByRole('dialog',{name:nested?'Edit isolated symbol group':'Edit symbol artwork',exact:true});
  const open=async()=>{
    await page.getByRole('group',{name:'Symbol Hierarchy',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
    await parent.getByLabel('Symbol artwork item',{exact:true}).selectOption('moving');
    if(nested)await parent.getByRole('button',{name:'Edit symbol group in isolation',exact:true}).click();
    await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('moving');
    await editor.getByText('Drag or place selected units',{exact:true}).click();
  };
  const drag=async()=>{
    const handle=editor.getByRole('button',{name:'Drag selected hierarchy units',exact:true}),
      target=editor.getByRole('button',{name:'Place selection below anchor-first in target',exact:true});
    await handle.scrollIntoViewIfNeeded();const from=(await handle.boundingBox())!;
    await page.mouse.move(from.x+from.width/2,from.y+from.height/2);await page.mouse.down();
    await page.mouse.move(from.x+from.width/2+10,from.y+from.height/2+2,{steps:3});
    await expect(editor.getByText('Moving selected hierarchy units. Escape cancels.',{exact:true})).toBeVisible();
    await target.scrollIntoViewIfNeeded();const to=(await target.boundingBox())!;
    await page.mouse.move(to.x+to.width/2,to.y+to.height/2,{steps:10});await page.mouse.move(to.x+to.width/2+1,to.y+to.height/2);await page.mouse.up();
  };
  await open();await drag();expect(await read()).toEqual(p);
  await editor.getByRole('button',{name:'Undo artwork change',exact:true}).click();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  await editor.getByRole('button',{name:'Redo artwork change',exact:true}).click();
  await editor.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  if(nested)await parent.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  expect(await read()).toEqual(p);
  await open();await drag();await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  if(nested){
    expect(await read()).toEqual(p);
    await parent.getByRole('button',{name:'Undo artwork change',exact:true}).click();
    await parent.getByRole('button',{name:'Redo artwork change',exact:true}).click();
    await parent.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  }
  const expected=structuredClone(p),prefix=nested?['enclosing']:[];
  expected.symbols![0].shapes=[{...a,groups:[...prefix,'target','moving-unit']},
    {...member,groups:[...prefix,'target','moving-unit','child']},b,c];
  await expect.poll(read).toEqual(expected);
  await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(expected);
});

for(const mode of ['cancel','capacity','boundary','source'] as const)test(`isolated hierarchy drag rejects stale and invalid context (${mode})`,async({page})=>{
  const p=newProject(),a:Vector={id:'moving',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['moving-unit']},
    b:Vector={...a,id:'target-art',x:70,groups:['target']};
  p.symbols=[{id:'hierarchy-owner',name:'Owner',width:200,height:100,shapes:[a,b]}];
  if(mode==='capacity'){
    p.symbols.push({id:'deep-leaf',name:'Leaf',width:20,height:20,shapes:[{...a,id:'deep-art',groups:Array.from({length:32},(_,i)=>'deep'+i)}]});
    a.kind='symbol';a.symbolId='deep-leaf';delete a.groups;
  }
  if(mode==='boundary'){a.groups=['enclosing','moving-unit'];b.groups=['enclosing','target'];}
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('group',{name:'Symbol Owner',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
  const editor=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),
    handle=editor.getByRole('button',{name:'Drag selected hierarchy units',exact:true}),
    moving=editor.getByText('Moving selected hierarchy units. Escape cancels.',{exact:true});
  await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('moving');
  await editor.getByText('Drag or place selected units',{exact:true}).click();
  const start=async()=>{
    const data=await page.evaluateHandle(()=>new DataTransfer());
    await handle.dispatchEvent('dragstart',{dataTransfer:data});await expect(moving).toBeVisible();return data;
  };
  if(mode==='source'){
    const data=await start();
    await page.getByRole('button',{name:'Add layer',exact:true}).evaluate(el=>(el as HTMLButtonElement).click());
    await expect(moving).toHaveCount(0);
    const changed=await read();expect(changed.layers).toHaveLength(2);expect(changed.symbols).toEqual(p.symbols);
    await editor.getByRole('button',{name:'Place selection into target',exact:true}).dispatchEvent('drop',{dataTransfer:data});
    await data.dispose();await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
    expect(await read()).toEqual(changed);
    await editor.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
    await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
    return;
  }
  if(mode==='capacity'){
    const data=await start();
    await editor.getByRole('button',{name:'Place selection into target',exact:true}).dispatchEvent('drop',{dataTransfer:data});
    await expect(editor.getByRole('alert')).toContainText('nested symbol expansion budget');
    await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
    expect(await read()).toEqual(p);await data.dispose();
  }else if(mode==='boundary'){
    const data=await start();
    await editor.getByRole('button',{name:'Edit symbol group in isolation',exact:true}).click();
    const child=page.getByRole('dialog',{name:'Edit isolated symbol group',exact:true});
    await expect(moving).toHaveCount(0);
    await child.getByText('Drag or place selected units',{exact:true}).click();
    await child.getByRole('button',{name:'Place selection into target',exact:true}).dispatchEvent('drop',{dataTransfer:data});
    await expect(child.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
    await child.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
    await editor.getByRole('button',{name:'Place selection into enclosing / target',exact:true}).dispatchEvent('drop',{dataTransfer:data});
    await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();await data.dispose();
  }else{
    const target=editor.getByRole('button',{name:'Place selection into target',exact:true});
    for(const action of ['escape','end','blur','selection']){
      const data=await start();
      if(action==='escape')await page.keyboard.press('Escape');
      else if(action==='end')await handle.dispatchEvent('dragend',{dataTransfer:data});
      else if(action==='blur')await page.evaluate(()=>window.dispatchEvent(new Event('blur')));
      else{
        await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('target-art');
        await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('moving');
      }
      await expect(moving).toHaveCount(0);await expect(editor).toBeVisible();
      await target.dispatchEvent('drop',{dataTransfer:data});await data.dispose();
      await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
      expect(await read()).toEqual(p);
    }
    const data=await start();await data.evaluate(value=>value.setData('application/x-splash-hierarchy','forged'));
    await target.dispatchEvent('drop',{dataTransfer:data});await data.dispose();
    await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  }
  await editor.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();expect(await read()).toEqual(p);
});

test('symbol hierarchy drag binds additional-track held frame ownership',async({page})=>{
  const p=newProject(),a:Vector={id:'moving',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:27,
    pivot:{x:4,y:6},transform:[1.2,.2,-.1,.8],fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['moving-unit']},
    b:Vector={...a,id:'target-art',x:70,groups:['target']};
  p.symbols=[{id:'tracked',name:'Tracked',width:200,height:100,shapes:[{...a,id:'base',groups:undefined}],
    timeline:{duration:4,keys:[],layers:[{...structuredClone(p.layers[0]),id:'overlay',name:'Overlay',keys:[{frame:0,shapes:[a,b]},{frame:2,shapes:[]}]}]}}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),
    timeline=page.getByRole('dialog',{name:'Symbol timeline',exact:true}),editor=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true});
  await page.getByRole('group',{name:'Symbol Tracked',exact:true}).getByRole('button',{name:'Edit symbol timeline',exact:true}).click();
  await timeline.getByLabel('Symbol layer',{exact:true}).selectOption('overlay');
  await timeline.getByRole('button',{name:'Edit symbol frame artwork',exact:true}).click();
  await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('moving');
  await editor.getByText('Drag or place selected units',{exact:true}).click();
  const source=editor.getByRole('button',{name:'Drag selected hierarchy units',exact:true}),
    target=editor.getByRole('button',{name:'Place selection into target',exact:true}),
    moving=editor.getByText('Moving selected hierarchy units. Escape cancels.',{exact:true}),
    data=await page.evaluateHandle(()=>new DataTransfer());
  await source.dispatchEvent('dragstart',{dataTransfer:data});await expect(moving).toBeVisible();
  const setFrame=async(value:string)=>timeline.getByLabel('Symbol frame',{exact:true}).evaluate((el,value)=>{
    const input=el as HTMLInputElement;input.value=value;input.dispatchEvent(new Event('change',{bubbles:true}));
  },value);
  // Same held artwork, different editor frame: returning must not revive the token.
  await setFrame('2');await expect(moving).toHaveCount(0);await setFrame('1');
  await target.dispatchEvent('drop',{dataTransfer:data});await data.dispose();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();expect(await read()).toEqual(p);
  await target.click();
  await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();expect(await read()).toEqual(p);
  await timeline.getByRole('button',{name:'Undo symbol timeline change',exact:true}).click();
  await timeline.getByRole('button',{name:'Redo symbol timeline change',exact:true}).click();
  await timeline.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
  const expected=structuredClone(p);
  expected.symbols![0].timeline!.layers![0].keys[0].shapes=[b,{...a,groups:['target','moving-unit']}];
  await expect.poll(read).toEqual(expected);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(expected);
});

for(const nested of [false,true])test(`isolated multi-unit hierarchy placement preserves complete order (nested ${nested})`,async({page})=>{
  const p=newProject(),a:Vector={id:'moving',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:27,
    pivot:{x:4,y:6},transform:[1.2,.2,-.1,.8],fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['moving-unit']},
    member:Vector={...a,id:'member',x:35,groups:['moving-unit','child']},
    gap:Vector={...a,id:'gap',x:50,groups:undefined},solo:Vector={...a,id:'solo',x:70,groups:undefined},
    b:Vector={...a,id:'anchor-first',x:100,groups:['target','unit']},
    c:Vector={...b,id:'anchor-child',x:130,groups:['target','unit','nested']};
  const source=[a,member,gap,solo,b,c];
  if(nested)for(const item of source)item.groups=['enclosing',...(item.groups??[])];
  p.symbols=[{id:'multi-hierarchy',name:'Multi hierarchy',width:200,height:100,shapes:source}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const parent=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    editor=page.getByRole('dialog',{name:nested?'Edit isolated symbol group':'Edit symbol artwork',exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const open=async()=>{
    await page.getByRole('group',{name:'Symbol Multi hierarchy',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
    await parent.getByLabel('Symbol artwork item',{exact:true}).selectOption('solo');
    if(nested)await parent.getByRole('button',{name:'Edit symbol group in isolation',exact:true}).click();
    await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('solo');
    await editor.getByText('Drag or place selected units',{exact:true}).click();
    await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit member',exact:true})).toHaveCount(0);
    await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit anchor-child',exact:true})).toHaveCount(0);
    await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit solo',exact:true})).toBeChecked();
    // Pick order is solo then moving; authored paint order must remain moving then solo.
    await editor.getByRole('checkbox',{name:'Move hierarchy unit moving',exact:true}).check();
  };
  const drag=async()=>{
    const handle=editor.getByRole('button',{name:'Drag selected hierarchy units',exact:true}),
      target=editor.getByRole('button',{name:'Place selection below anchor-first in target',exact:true});
    await handle.scrollIntoViewIfNeeded();const from=(await handle.boundingBox())!;
    await page.mouse.move(from.x+from.width/2,from.y+from.height/2);await page.mouse.down();
    await page.mouse.move(from.x+from.width/2+10,from.y+from.height/2+2,{steps:3});
    await expect(editor.getByText('Moving selected hierarchy units. Escape cancels.',{exact:true})).toBeVisible();
    await target.scrollIntoViewIfNeeded();const to=(await target.boundingBox())!;
    await page.mouse.move(to.x+to.width/2,to.y+to.height/2,{steps:10});
    await page.mouse.move(to.x+to.width/2+1,to.y+to.height/2);await page.mouse.up();
  };
  await open();await drag();expect(await read()).toEqual(p);
  await editor.getByRole('button',{name:'Undo artwork change',exact:true}).click();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit solo',exact:true})).toBeChecked();
  await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit moving',exact:true})).not.toBeChecked();
  await editor.getByRole('button',{name:'Redo artwork change',exact:true}).click();
  await editor.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  if(nested)await parent.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  expect(await read()).toEqual(p);
  await open();await drag();await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  if(nested){
    expect(await read()).toEqual(p);await parent.getByRole('button',{name:'Undo artwork change',exact:true}).click();
    await parent.getByRole('button',{name:'Redo artwork change',exact:true}).click();
    await parent.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  }
  const expected=structuredClone(p),prefix=nested?['enclosing']:[];
  expected.symbols![0].shapes=[gap,{...a,groups:[...prefix,'target','moving-unit']},
    {...member,groups:[...prefix,'target','moving-unit','child']},{...solo,groups:[...prefix,'target']},b,c];
  await expect.poll(read).toEqual(expected);
  await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(expected);
});

for(const mode of ['selection','capacity'] as const)test(`isolated multi-unit placement rejects atomically (${mode})`,async({page})=>{
  const p=newProject(),a:Vector={id:'first',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]},
    second:Vector={...a,id:'second',x:40},target:Vector={...a,id:'target-art',x:80,groups:['target']};
  p.symbols=[{id:'multi-reject',name:'Multi reject',width:200,height:100,shapes:[a,second,target]}];
  if(mode==='capacity'){
    p.symbols.push({id:'deep-multi',name:'Deep',width:20,height:20,
      shapes:[{...a,id:'deep-art',groups:Array.from({length:32},(_,i)=>'depth'+i)}]});
    second.kind='symbol';second.symbolId='deep-multi';
  }
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('group',{name:'Symbol Multi reject',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
  const editor=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('first');
  await editor.getByText('Drag or place selected units',{exact:true}).click();
  const firstBox=editor.getByRole('checkbox',{name:'Move hierarchy unit first',exact:true}),
    secondBox=editor.getByRole('checkbox',{name:'Move hierarchy unit second',exact:true}),
    handle=editor.getByRole('button',{name:'Drag selected hierarchy units',exact:true}),
    into=editor.getByRole('button',{name:'Place selection into target',exact:true});
  await secondBox.check();
  const data=await page.evaluateHandle(()=>new DataTransfer());
  await handle.dispatchEvent('dragstart',{dataTransfer:data});
  await expect(editor.getByText('Moving selected hierarchy units. Escape cancels.',{exact:true})).toBeVisible();
  if(mode==='selection'){
    await secondBox.uncheck();await secondBox.check();
    await into.dispatchEvent('drop',{dataTransfer:data});
    await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
    await firstBox.uncheck();await secondBox.uncheck();await expect(handle).toBeDisabled();
    await expect(firstBox).toBeEnabled();await firstBox.check();await secondBox.check();
    // A moved unit cannot also act as an anchor.
    await editor.getByRole('button',{name:'Place selection below second in Current editing root',exact:true}).click();
    await expect(editor.getByRole('alert')).toContainText('unmoved');
  }else{
    await into.dispatchEvent('drop',{dataTransfer:data});
    await expect(editor.getByRole('alert')).toContainText('nested symbol expansion budget');
    await expect(firstBox).toBeChecked();await expect(secondBox).toBeChecked();
  }
  await data.dispose();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();expect(await read()).toEqual(p);
  // Removing the stale/conflicting second unit permits exactly one valid local edit.
  await secondBox.uncheck();await into.click();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeEnabled();
  await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  const expected=structuredClone(p);expected.symbols![0].shapes=[second,target,{...a,groups:['target']}];
  await expect.poll(read).toEqual(expected);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
});


for(const nested of [false,true])for(const custom of [false,true])test(`isolated multi-unit shared transform is atomic (nested ${nested}, custom ${custom})`,async({page})=>{
  const p=newProject(),a:Vector={id:'a',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    pivot:{x:4,y:6},fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['moving']},
    b:Vector={...a,id:'b',x:30,groups:['moving','child']},
    solo:Vector={...a,id:'solo',x:70,groups:undefined},outside:Vector={...a,id:'outside',x:110,groups:undefined};
  const source=[a,b,solo,outside];
  if(nested)for(const item of source)item.groups=['enclosing',...(item.groups??[])];
  p.symbols=[{id:'multi-transform',name:'Multi transform',width:200,height:100,shapes:source}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const parent=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    editor=page.getByRole('dialog',{name:nested?'Edit isolated symbol group':'Edit symbol artwork',exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const open=async()=>{
    await page.getByRole('group',{name:'Symbol Multi transform',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
    await parent.getByLabel('Symbol artwork item',{exact:true}).selectOption('solo');
    if(nested)await parent.getByRole('button',{name:'Edit symbol group in isolation',exact:true}).click();
    await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('solo');
    await editor.getByText('Drag or place selected units',{exact:true}).click();
    await editor.getByRole('checkbox',{name:'Move hierarchy unit a',exact:true}).check();
    if(custom){
      await editor.getByRole('checkbox',{name:'Use custom hierarchy transform pivot',exact:true}).check();
      await editor.getByLabel('Hierarchy transform pivot X',{exact:true}).fill('-10');
      await editor.getByLabel('Hierarchy transform pivot Y',{exact:true}).fill('5');
    }
  };
  const transform=editor.getByRole('button',{name:'Transform selected hierarchy units',exact:true});
  const fill=async(field:string,value:string)=>editor.getByLabel('Symbol group transform '+field,{exact:true}).fill(value);
  await open();
  for(const value of ['0','0.000000000001']){
    await fill('scaleX',value);await transform.click();
    await expect(editor.getByRole('alert')).toContainText(value==='0'?'nonzero':'geometry limits');
    await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
    await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit a',exact:true})).toBeChecked();
    await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit solo',exact:true})).toBeChecked();
    expect(await read()).toEqual(p);
  }
  if(custom){
    await fill('scaleX','100');
    for(const value of ['', '1e308']){
      await editor.getByLabel('Hierarchy transform pivot X',{exact:true}).fill(value);
      await fill('rotation','90');await transform.click();
      await expect(editor.getByRole('alert')).toContainText(value===''?'finite transform pivot':'geometry limits');
      await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
      await expect(editor.getByRole('checkbox',{name:'Move hierarchy unit a',exact:true})).toBeChecked();
      expect(await read()).toEqual(p);
    }
    await editor.getByRole('button',{name:'Reset symbol transform values',exact:true}).click();
    await expect(editor.getByRole('checkbox',{name:'Use custom hierarchy transform pivot',exact:true})).not.toBeChecked();
    await editor.getByRole('checkbox',{name:'Use custom hierarchy transform pivot',exact:true}).check();
    await expect(editor.getByLabel('Hierarchy transform pivot X',{exact:true})).toHaveValue('0');
    await editor.getByLabel('Hierarchy transform pivot X',{exact:true}).fill('-10');
    await editor.getByLabel('Hierarchy transform pivot Y',{exact:true}).fill('5');
  }
  const apply=async()=>{
    await fill('dx','7');await fill('dy','-3');await fill('scaleX','-200');await fill('scaleY','50');await transform.click();
  };
  await apply();expect(await read()).toEqual(p);
  await editor.getByRole('button',{name:'Undo artwork change',exact:true}).click();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  await editor.getByRole('button',{name:'Redo artwork change',exact:true}).click();
  await editor.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  if(nested)await parent.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  expect(await read()).toEqual(p);
  await open();await apply();await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  if(nested)await parent.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  const expected=structuredClone(p);
  expected.symbols![0].shapes=source.map((item,i)=>i===3?item:
    {...item,x:(custom?-23:157)-2*item.x,y:.5*item.y+(custom?-.5:7),rotation:0,transform:[-2,0,0,.5]});
  await expect.poll(read).toEqual(expected);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(expected);
});


for(const nested of [false,true])test(`isolated canvas hierarchy picks complete units without authoring (nested ${nested})`,async({page})=>{
  const p=newProject(),a:Vector={id:'pick-a',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    pivot:{x:4,y:6},fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['unit']},
    b:Vector={...a,id:'pick-b',x:40,groups:['unit','child']},
    solo:Vector={...a,id:'pick-solo',x:80,groups:undefined},outside:Vector={...a,id:'pick-outside',x:130,groups:undefined};
  const source=[a,b,solo,outside];if(nested)for(const item of source)item.groups=['enclosing',...(item.groups??[])];
  p.symbols=[{id:'canvas-pick',name:'Canvas pick',width:200,height:100,shapes:source}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('group',{name:'Symbol Canvas pick',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
  const parent=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    editor=page.getByRole('dialog',{name:nested?'Edit isolated symbol group':'Edit symbol artwork',exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  await parent.getByLabel('Symbol artwork item',{exact:true}).selectOption('pick-solo');
  if(nested)await parent.getByRole('button',{name:'Edit symbol group in isolation',exact:true}).click();
  await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('pick-solo');
  await editor.getByLabel('Symbol canvas tool',{exact:true}).selectOption('hierarchy');
  await editor.getByText('Drag or place selected units',{exact:true}).click();
  const canvas=editor.getByLabel('Symbol artwork preview',{exact:true}),
    box=(id:string)=>editor.getByRole('checkbox',{name:'Move hierarchy unit '+id,exact:true});
  const click=async(x:number,y:number,shift=false)=>{
    await canvas.scrollIntoViewIfNeeded();const r=(await canvas.boundingBox())!;
    if(shift)await page.keyboard.down('Shift');
    await page.mouse.click(r.x+(20+2.5*x)*r.width/540,r.y+(20+2.5*y)*r.height/330);
    if(shift)await page.keyboard.up('Shift');
  };
  await click(45,15);await expect(box('pick-a')).toBeChecked();await expect(box('pick-solo')).not.toBeChecked();
  await expect(box('pick-b')).toHaveCount(0);
  await expect(editor.getByLabel('Symbol artwork item',{exact:true})).toHaveValue('pick-solo');
  // Both members have cyan bounds, including the member that was not directly clicked.
  const outline=async(x:number)=>canvas.evaluate((node,x)=>{
    const ctx=(node as HTMLCanvasElement).getContext('2d')!;
    const pixels=ctx.getImageData(20+2.5*x-2,55,5,10).data;
    for(let i=0;i<pixels.length;i+=4)if(pixels[i]<210 && pixels[i+1]>pixels[i]+20 && pixels[i+2]>pixels[i]+30)return true;
    return false;
  },x);
  await expect.poll(()=>outline(10)).toBe(true);await expect.poll(()=>outline(40)).toBe(true);
  await page.keyboard.press('Delete');await page.keyboard.press('ArrowRight');
  await click(15,15,true);await expect(box('pick-a')).not.toBeChecked();
  await expect.poll(()=>outline(10)).toBe(false);
  await click(45,15);await click(85,15,true);
  await expect(box('pick-a')).toBeChecked();await expect(box('pick-solo')).toBeChecked();
  await page.keyboard.press('Control+a');await expect(box('pick-outside')).toBeChecked();
  await click(185,80);await expect(box('pick-a')).not.toBeChecked();await expect(box('pick-solo')).not.toBeChecked();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();expect(await read()).toEqual(p);
  // A blank ordinary pick can clear the active item; hierarchy mode must still recover a unit.
  await editor.getByLabel('Symbol canvas tool',{exact:true}).selectOption('select');
  await click(185,80);await expect(editor.getByLabel('Symbol artwork item',{exact:true})).toHaveValue('');
  await editor.getByLabel('Symbol canvas tool',{exact:true}).selectOption('hierarchy');
  await click(45,15);await expect(box('pick-a')).toBeChecked();
  await expect(editor.getByLabel('Symbol artwork item',{exact:true})).toHaveValue('pick-a');
  await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('pick-solo');
  await click(45,15);await click(85,15,true);
  await editor.getByLabel('Symbol group transform dx',{exact:true}).fill('5');
  await editor.getByRole('button',{name:'Transform selected hierarchy units',exact:true}).click();
  expect(await read()).toEqual(p);
  await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  if(nested)await parent.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  const expected=structuredClone(p);expected.symbols![0].shapes=source.map((item,i)=>i===3?item:{...item,x:item.x+5,transform:[1,0,0,1]});
  await expect.poll(read).toEqual(expected);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
});

test('isolated canvas hierarchy pending picks cancel without selection or history edits',async({page})=>{
  const p=newProject(),a:Vector={id:'pending-a',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]},solo={...a,id:'pending-solo',x:80};
  p.symbols=[{id:'pending-pick',name:'Pending pick',width:200,height:100,shapes:[a,solo]}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('group',{name:'Symbol Pending pick',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
  const editor=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),canvas=editor.getByLabel('Symbol artwork preview',{exact:true}),
    box=(id:string)=>editor.getByRole('checkbox',{name:'Move hierarchy unit '+id,exact:true});
  await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('pending-solo');
  await editor.getByLabel('Symbol canvas tool',{exact:true}).selectOption('hierarchy');
  await editor.getByText('Drag or place selected units',{exact:true}).click();
  for(const mode of ['cancel','lost','escape','blur','resize','selection','motion']){
    await canvas.scrollIntoViewIfNeeded();const r=(await canvas.boundingBox())!;
    const x=r.x+57.5*r.width/540,y=r.y+57.5*r.height/330;
    await page.mouse.move(x,y);await page.mouse.down();
    if(mode==='cancel')await canvas.dispatchEvent('pointercancel',{pointerId:1});
    if(mode==='lost')await canvas.evaluate(node=>(node as HTMLCanvasElement).releasePointerCapture(1));
    if(mode==='escape')await page.keyboard.press('Escape');
    if(mode==='blur')await page.evaluate(()=>window.dispatchEvent(new Event('blur')));
    if(mode==='resize')await canvas.evaluate(node=>node.style.width='500px');
    if(mode==='selection'){await box('pending-solo').uncheck();await box('pending-solo').check();}
    if(mode==='motion'){await page.mouse.move(x+10,y);await page.mouse.move(x,y);}
    await page.mouse.up();
    await expect(box('pending-solo'),mode).toBeChecked();await expect(box('pending-a'),mode).not.toBeChecked();
    await canvas.evaluate(node=>node.style.removeProperty('width'));
  }
  // Unrelated pointers cannot complete or cancel the primary pick.
  await canvas.scrollIntoViewIfNeeded();const r=(await canvas.boundingBox())!;
  await page.mouse.move(r.x+57.5*r.width/540,r.y+57.5*r.height/330);await page.mouse.down();
  await canvas.dispatchEvent('pointerup',{pointerId:99,clientX:r.x+57.5,clientY:r.y+57.5});
  await canvas.dispatchEvent('pointercancel',{pointerId:99});
  await expect(box('pending-solo')).toBeChecked();await page.mouse.up();await expect(box('pending-a')).toBeChecked();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project)).toEqual(p);
  await canvas.focus();await page.keyboard.press('Escape');
  await expect(editor.getByLabel('Symbol canvas tool',{exact:true})).toHaveValue('select');await expect(editor).toBeVisible();
});


