for(const spec of [
  {edge:'n',nested:false,custom:false,shift:false,start:{x:55,y:10},end:{x:45,y:80},c:.5,anchor:30,probe:{x:5,y:15}},
  {edge:'s',nested:true,custom:true,shift:true,start:{x:55,y:30},end:{x:63,y:90},c:Math.tan(Math.PI/4),anchor:20,probe:{x:32,y:25}},
  {edge:'e',nested:false,custom:true,shift:false,start:{x:100,y:20},end:{x:200,y:42.5},c:.5,anchor:55,probe:{x:85,y:40}},
  {edge:'w',nested:true,custom:false,shift:false,start:{x:10,y:20},end:{x:200,y:65},c:-.5,anchor:100,probe:{x:15,y:60}}
])test(`isolated hierarchy skew ${spec.edge} preserves complete units and history`,async({page})=>{
  const p=newProject(),a:Vector={id:'skew-a',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    pivot:{x:4,y:6},fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['unit']},
    b={...a,id:'skew-b',x:40,groups:['unit','child']},solo={...a,id:'skew-solo',x:80,groups:undefined},
    outside={...a,id:'skew-outside',x:140,groups:undefined};
  const source=[a,b,solo,outside];if(spec.nested)for(const item of source)item.groups=['enclosing',...(item.groups??[])];
  p.symbols=[{id:'shared-skew',name:'Shared skew',width:200,height:100,shapes:source}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const parent=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),
    editor=page.getByRole('dialog',{name:spec.nested?'Edit isolated symbol group':'Edit symbol artwork',exact:true}),
    canvas=editor.getByLabel('Symbol artwork preview',{exact:true}),
    read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
  const open=async()=>{
    await page.getByRole('group',{name:'Symbol Shared skew',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
    await parent.getByLabel('Symbol artwork item',{exact:true}).selectOption('skew-solo');
    if(spec.nested)await parent.getByRole('button',{name:'Edit symbol group in isolation',exact:true}).click();
    await editor.getByLabel('Symbol artwork item',{exact:true}).selectOption('skew-solo');
    await editor.getByText('Drag or place selected units',{exact:true}).click();
    await editor.getByRole('checkbox',{name:'Move hierarchy unit skew-a',exact:true}).check();
    if(spec.custom){
      await editor.getByRole('checkbox',{name:'Use custom hierarchy transform pivot',exact:true}).check();
      await editor.getByLabel('Hierarchy transform pivot X',{exact:true}).fill('55');
      await editor.getByLabel('Hierarchy transform pivot Y',{exact:true}).fill('20');
    }
    await editor.getByLabel('Symbol canvas tool',{exact:true}).selectOption('hierarchy-skew');
  };
  const begin=async()=>{
    await canvas.scrollIntoViewIfNeeded();const r=(await canvas.boundingBox())!;
    await page.mouse.move(r.x+(20+2.5*spec.start.x)*r.width/540,r.y+(20+2.5*spec.start.y)*r.height/330);await page.mouse.down();return r;
  };
  const drag=async()=>{
    const r=await begin();if(spec.shift)await page.keyboard.down('Shift');if(spec.custom)await page.keyboard.down('Alt');
    await page.mouse.move(r.x+(20+2.5*spec.end.x)*r.width/540,r.y+(20+2.5*spec.end.y)*r.height/330,{steps:5});
  };
  const release=async()=>{await page.mouse.up();if(spec.shift)await page.keyboard.up('Shift');if(spec.custom)await page.keyboard.up('Alt');};
  const pixel=()=>canvas.evaluate((node,p)=>Array.from((node as HTMLCanvasElement).getContext('2d')!.getImageData(20+p.x*2.5,20+p.y*2.5,1,1).data),spec.probe);
  await open();await begin();await page.mouse.up();await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  await drag();await expect.poll(pixel).toEqual([255,0,0,255]);
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();expect(await read()).toEqual(p);
  await page.keyboard.press('Escape');await release();await expect.poll(pixel).toEqual([255,255,255,255]);
  await drag();await release();await editor.getByRole('button',{name:'Undo artwork change',exact:true}).click();
  await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true})).toBeDisabled();
  await editor.getByRole('button',{name:'Redo artwork change',exact:true}).click();
  await editor.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();
  if(spec.nested)await parent.getByRole('button',{name:'Cancel symbol editing',exact:true}).click();expect(await read()).toEqual(p);
  await open();await drag();await release();await editor.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  if(spec.nested)await parent.getByRole('button',{name:'Apply symbol changes',exact:true}).click();
  const horizontal=spec.edge==='n'||spec.edge==='s',expected=structuredClone(p);
  expected.symbols![0].shapes=source.map((item,i)=>i===3?item:horizontal?
    {...item,x:item.x+spec.c*item.y-spec.c*spec.anchor,transform:[1,0,spec.c,1]}:
    {...item,y:spec.c*item.x+item.y-spec.c*spec.anchor,transform:[1,spec.c,0,1]});
  await expect.poll(read).toEqual(expected);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(expected);
});

test('isolated hierarchy skew rejects singular snapped stale and overflowing proposals',async({page})=>{
  const p=newProject(),a:Vector={id:'skew-guard-a',kind:'rectangle',x:10,y:10,width:20,height:20,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],groups:['unit']},
    b={...a,id:'skew-guard-b',x:40,groups:['unit','child']},solo={...a,id:'skew-guard-solo',x:80,groups:undefined};
  p.symbols=[{id:'skew-guards',name:'Skew guards',width:200,height:100,shapes:[a,b,solo]}];
  await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
  await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('group',{name:'Symbol Skew guards',exact:true}).getByRole('button',{name:'Edit symbol artwork',exact:true}).click();
  const editor=page.getByRole('dialog',{name:'Edit symbol artwork',exact:true}),canvas=editor.getByLabel('Symbol artwork preview',{exact:true});
  await editor.getByText('Drag or place selected units',{exact:true}).click();
  await editor.getByRole('checkbox',{name:'Move hierarchy unit skew-guard-solo',exact:true}).check();
  await editor.getByRole('checkbox',{name:'Use custom hierarchy transform pivot',exact:true}).check();
  await editor.getByLabel('Hierarchy transform pivot X',{exact:true}).fill('55');
  await editor.getByLabel('Hierarchy transform pivot Y',{exact:true}).fill('30');
  await editor.getByLabel('Symbol canvas tool',{exact:true}).selectOption('hierarchy-skew');
  for(const mode of ['singular','capture','cancel','blur','resize','pivot','overflow','snap90']){
    await canvas.scrollIntoViewIfNeeded();const r=(await canvas.boundingBox())!;
    await page.mouse.move(r.x+157.5*r.width/540,r.y+95*r.height/330);await page.mouse.down();
    if(mode==='singular')await page.keyboard.down('Alt');
    if(mode==='capture')await canvas.evaluate(node=>(node as HTMLCanvasElement).releasePointerCapture(1));
    if(mode==='cancel')await canvas.dispatchEvent('pointercancel',{pointerId:1});
    if(mode==='blur')await page.evaluate(()=>window.dispatchEvent(new Event('blur')));
    if(mode==='resize')await canvas.evaluate(node=>node.style.width='500px');
    if(mode==='pivot')for(const value of ['56','55'])await editor.getByLabel('Hierarchy transform pivot X',{exact:true}).evaluate((node,value)=>{
      (node as HTMLInputElement).value=value;node.dispatchEvent(new Event('input',{bubbles:true}));
    },value);
    if(mode==='overflow'||mode==='snap90')await canvas.dispatchEvent('pointermove',{pointerId:1,clientX:1e9,clientY:r.y+95,shiftKey:mode==='snap90'});
    else await page.mouse.move(r.x+182.5*r.width/540,r.y+95*r.height/330);
    await page.mouse.up();if(mode==='singular')await page.keyboard.up('Alt');
    await canvas.evaluate(node=>node.style.removeProperty('width'));
    await expect(editor.getByRole('button',{name:'Undo artwork change',exact:true}),mode).toBeDisabled();
    if(mode==='singular')await expect(editor.getByRole('alert')).toContainText('pivot');
    if(mode==='snap90')await expect(editor.getByRole('alert')).toContainText('90 degrees');
    if(mode==='overflow')await expect(editor.getByRole('alert')).toContainText('geometry limits');
    expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project)).toEqual(p);
  }
});


