for(const mode of ['default','saved','stale'] as const)test('rotate shared remembered endpoint preserves two-sided ownership and history '+mode,async({page})=>{
 const project=newProject(),layer=project.layers[0];project.duration=12;
 const art:Vector={id:'a',kind:'rectangle',x:project.width/2,y:project.height/2,width:32,height:32,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],...(mode==='saved'?{pivot:{x:0,y:0}}:{})};
 layer.keys=[0,4,8].map(frame=>({frame,shapes:[{...art,x:art.x+(frame-4)*10}]}));layer.keys.push({frame:10,shapes:[]});
 createBasicMotionSpan(project,[layer.id],0,4,'in');createBasicMotionSpan(project,[layer.id],4,8,'linear');
 if(mode==='stale')layer.keys[6].shapes[0].x++;
 await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),project);
 await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
 const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),before=await read();
 const timeline=(await page.getByLabel('Timeline frames').boundingBox())!;await page.mouse.click(timeline.x+81,timeline.y+40);
 await page.getByRole('button',{name:'Selection',exact:true}).click();
 const box=(await page.getByLabel('Drawing stage').boundingBox())!;await page.mouse.click(box.x+box.width/2+8,box.y+box.height/2+8);
 await page.getByLabel('Shared endpoint rotation',{exact:true}).fill('90');await page.getByRole('button',{name:'Rotate endpoint and refresh both spans',exact:true}).click();
 if(mode==='stale'){
  await expect(page.getByRole('alert')).toContainText('Generated keys changed');expect(await read()).toEqual(before);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(before);
 }else{
  const saved=await read(),keys=saved.layers[0].keys,joint=keys[4].shapes[0];
  expect(joint.rotation).toBe(90);expect(joint.x).toBeCloseTo(art.x+(mode==='saved'?0:32));expect(joint.y).toBeCloseTo(art.y);
  expect(joint.pivot).toEqual(art.pivot);expect(joint.transform).toBeUndefined();
  expect(keys[2].shapes[0].rotation).toBeCloseTo(22.5);expect(keys[6].shapes[0].rotation).toBeCloseTo(45);
  expect([keys[0],keys[8],keys[9]]).toEqual([before.layers[0].keys[0],before.layers[0].keys[8],before.layers[0].keys[9]]);
  expect(saved.layers[0].motionSpans!.map(({baseline:_baseline,...settings})=>settings)).toEqual(before.layers[0].motionSpans!.map(({baseline:_baseline,...settings})=>settings));
  expect(saved.duration).toBe(before.duration);
  await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(before);
  await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(saved);
 }
});


for(const mode of ['default','saved','group','stale','optin','reflection'] as const)test('scale shared remembered endpoint admits both recipes atomically '+mode,async({page})=>{
 const p=newProject(),layer=p.layers[0];p.width=200;p.height=100;p.duration=12;
 const art:Vector={id:'scale-a',kind:'rectangle',x:0,y:20,width:40,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],...(mode==='saved'?{pivot:{x:0,y:0}}:{})};
 layer.keys=[0,4,8].map(frame=>({frame,shapes:[{...art,x:40+frame*10},...(mode==='group'?[{...art,id:'scale-b',x:60+frame*10,y:60,fill:'#0000ff'}]:[])]}));
 layer.keys.push({frame:10,shapes:[]});
 if(mode==='group')for(const k of layer.keys)for(const shape of k.shapes)shape.groups=['outer','inner'];
 const spin=mode==='group'?{direction:'shortest' as const,turns:0,rigidGroups:true,axisGroupScale:true}:undefined;
 createBasicMotionSpan(p,[layer.id],0,4,'in',{affine:true},undefined,spin);createBasicMotionSpan(p,[layer.id],4,8,'linear',mode==='optin'?undefined:{affine:true},undefined,spin);
 if(mode==='stale')layer.keys[6].shapes[0].x++;
 await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
 await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
 const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
 await page.getByLabel('Timeline frames').click({position:{x:81,y:40}});await page.getByRole('combobox',{name:'Zoom',exact:true}).selectOption('0.5');
 await page.getByRole('button',{name:'Selection',exact:true}).click();
 const stage=page.getByLabel('Drawing stage'),b=(await stage.boundingBox())!;await stage.click({position:{x:b.width/2-7.5,y:b.height/2-12.5}});
 await page.getByLabel('Shared endpoint X scale',{exact:true}).fill(mode==='reflection'?'-100':'200');
 await page.getByLabel('Shared endpoint Y scale',{exact:true}).fill('50');await page.getByRole('button',{name:'Scale endpoint and refresh both spans',exact:true}).click();
 if(mode==='stale'||mode==='optin'||mode==='reflection'){
  await expect(page.getByRole('alert')).toContainText(mode==='stale'?/Generated keys changed/:mode==='optin'?/enabled motion properties/:/orientation|reflection|sign/i);
  expect(await read()).toEqual(p);await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);return;
 }
 const saved=await read(),track=saved.layers[0],joint=track.keys[4].shapes[0];
 expect(joint.x).toBe(mode==='saved'?80:mode==='group'?50:60);expect(joint.y).toBe(mode==='saved'?20:mode==='group'?35:25);
 expect(joint.transform).toEqual([2,0,0,.5]);expect(joint.pivot).toEqual(art.pivot);
 expect(track.keys[2].shapes[0].transform).toEqual([1.25,0,0,.875]);expect(track.keys[6].shapes[0].transform).toEqual([1.5,0,0,.75]);
 if(mode==='group')expect(track.keys[4].shapes[1]).toMatchObject({x:90,y:55,transform:[2,0,0,.5],groups:['outer','inner']});
 expect([track.keys[0],track.keys[8],track.keys[9]]).toEqual([layer.keys[0],layer.keys[8],layer.keys[9]]);
 expect(track.motionSpans!.map(({baseline:_baseline,...settings})=>settings)).toEqual(layer.motionSpans!.map(({baseline:_baseline,...settings})=>settings));
 expect(saved.duration).toBe(p.duration);
 const pixel=(x:number,y:number)=>stage.evaluate((el,p)=>{
  const c=el as HTMLCanvasElement,dpr=devicePixelRatio||1;
  return Array.from(c.getContext('2d')!.getImageData((c.width/dpr/2+(p.x-100)*.5)*dpr,(c.height/dpr/2+(p.y-50)*.5)*dpr,1,1).data);
 },{x,y});
 await expect.poll(()=>pixel(joint.x+(mode==='saved'?30:10),joint.y+5)).toEqual([255,0,0,255]);
 await expect.poll(()=>pixel(joint.x+(mode==='saved'?30:10),joint.y+16)).toEqual([255,255,255,255]);
 await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(saved);
});


for(const mode of ['x','y','saved-x','saved-y','group-x','group-y','stale','optin','right-angle'] as const)test('skew shared remembered endpoint preserves guarded two-sided admission '+mode,async({page})=>{
 const p=newProject(),layer=p.layers[0];p.width=200;p.height=100;p.duration=12;
 const group=mode.startsWith('group'),saved=mode.startsWith('saved')||group,axis=mode.endsWith('y')?'y':'x',h=Math.tan(Math.PI/6);
 const art:Vector={id:'skew-a',kind:'rectangle',x:0,y:20,width:40,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],...(saved?{pivot:{x:0,y:0}}:{})};
 layer.keys=[0,4,8].map(frame=>({frame,shapes:[{...art,x:40+frame*10},...(group?[{...art,id:'skew-b',x:60+frame*10,y:60,pivot:{x:-20,y:-40},fill:'#0000ff'}]:[])]}));layer.keys.push({frame:10,shapes:[]});
 if(group)for(const k of layer.keys)for(const shape of k.shapes)shape.groups=['outer','inner'];
 const spin=group?{direction:'shortest' as const,turns:0,rigidGroups:true,axisGroupScale:true,axisGroupShear:true,savedGroupPivots:true}:undefined;
 createBasicMotionSpan(p,[layer.id],0,4,'in',{affine:true},undefined,spin);createBasicMotionSpan(p,[layer.id],4,8,'linear',mode==='optin'?undefined:{affine:true},undefined,spin);
 if(mode==='stale')layer.keys[6].shapes[0].x++;
 await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
 await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
 const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project);
 await page.getByLabel('Timeline frames').click({position:{x:81,y:40}});await page.getByRole('combobox',{name:'Zoom',exact:true}).selectOption('0.5');await page.getByRole('button',{name:'Selection',exact:true}).click();
 const stage=page.getByLabel('Drawing stage'),b=(await stage.boundingBox())!;await stage.click({position:{x:b.width/2-7.5,y:b.height/2-12.5}});
 await page.getByLabel('Shared endpoint skew axis',{exact:true}).selectOption(axis);await page.getByLabel('Shared endpoint skew angle',{exact:true}).fill(mode==='right-angle'?'90':'30');
 await page.getByRole('button',{name:'Skew endpoint and refresh both spans',exact:true}).click();
 if(mode==='stale'||mode==='optin'||mode==='right-angle'){
  await expect(page.getByRole('alert')).toContainText(mode==='stale'?/Generated keys changed/:mode==='optin'?/enabled motion properties/:/90 degrees/);
  expect(await read()).toEqual(p);await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);return;
 }
 const result=await read(),track=result.layers[0],joint=track.keys[4].shapes[0];
 expect(joint.x).toBeCloseTo(80+(!saved&&axis==='x'?-10*h:0),9);expect(joint.y).toBeCloseTo(20+(!saved&&axis==='y'?-20*h:0),9);
 expect(joint.transform).toEqual([1,axis==='y'?h:0,axis==='x'?h:0,1]);expect(joint.pivot).toEqual(art.pivot);
 if(group){expect(track.keys[4].shapes[1].x).toBeCloseTo(100+(axis==='x'?40*h:0),9);expect(track.keys[4].shapes[1].y).toBeCloseTo(60+(axis==='y'?20*h:0),9);}
 if(axis==='x'){expect(track.keys[2].shapes[0].transform![2]).toBeCloseTo(h*.25,9);expect(track.keys[6].shapes[0].transform![2]).toBeCloseTo(h*.5,9);}
 expect([track.keys[0],track.keys[8],track.keys[9]]).toEqual([layer.keys[0],layer.keys[8],layer.keys[9]]);
 expect(track.motionSpans!.map(({baseline:_baseline,...settings})=>settings)).toEqual(layer.motionSpans!.map(({baseline:_baseline,...settings})=>settings));expect(result.duration).toBe(p.duration);
 const clear=(await stage.boundingBox())!;await stage.click({position:{x:clear.width/2+45,y:clear.height/2+20}});expect(await read()).toEqual(result);
 const pixel=(x:number,y:number)=>stage.evaluate((el,p)=>{
  const c=el as HTMLCanvasElement,d=devicePixelRatio||1;
  return Array.from(c.getContext('2d')!.getImageData((c.width/d/2+(p.x-100)*.5)*d,(c.height/d/2+(p.y-50)*.5)*d,1,1).data);
 },{x,y});
 await expect.poll(()=>pixel(axis==='y'?115:saved?125:80,axis==='y'?45:saved?36:24)).toEqual([255,0,0,255]);
 await expect.poll(()=>pixel(150,15)).toEqual([255,255,255,255]);
 await stage.focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(p);await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(result);
});


for(const mode of ['base','saved','overlay','nested','stale','source'] as const)test('isolated symbol shared-key rotation preserves draft and document history '+mode,async({page})=>{
 const p=newProject(),track=p.layers[0];p.duration=12;
 const ink:Vector={id:'moving',kind:'rectangle',x:0,y:10,width:24,height:12,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[],...(mode==='saved'?{pivot:{x:0,y:0}}:{})};
 const graphic={id:'graphic',name:'Graphic',width:24,height:12,shapes:[{...ink,id:'ink',y:0}],timeline:{duration:3,keys:[{frame:1,shapes:[{...ink,id:'ink',y:0,fill:'#00ff00'}]},{frame:2,shapes:[{...ink,id:'ink',y:0,fill:'#0000ff'}]}]}};
 if(mode==='nested')p.symbols=[graphic];
 track.keys=[0,4,8].map(frame=>({frame,shapes:[{...ink,x:frame*10,...(mode==='nested'?{kind:'symbol' as const,symbolId:graphic.id,symbolPlayback:{mode:'loop' as const,firstFrame:frame%3}}:{})},{...ink,id:'stationary',x:0,y:60}]}));track.keys.push({frame:10,shapes:[]});
 createBasicMotionSpan(p,[track.id],0,4,'in');createBasicMotionSpan(p,[track.id],4,8,'linear');
 const overlay=structuredClone(track);overlay.id='overlay';overlay.name='Overlay';
 if(mode==='stale')track.keys[6].shapes[0].x++;
 const def={id:'child',name:'Child',width:100,height:100,shapes:track.keys[0].shapes,buttonStates:{up:0,over:4,down:8,hit:10},
 timeline:{duration:12,keys:track.keys.slice(1),motionSpans:track.motionSpans,layers:[overlay]}};
 p.symbols=[...(p.symbols??[]),def];track.keys=[{frame:0,shapes:[]}];delete track.motionSpans;
 await page.addInitScript(project=>localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null})),p);
 await page.goto('/');await page.getByRole('button',{name:'Recover changes',exact:true}).click();
 const read=()=>page.evaluate(()=>JSON.parse(localStorage.getItem('splash-recovery-v1')!).project as Project),before=await read();
 const open=async()=>{
  await page.getByRole('group',{name:'Symbol Child',exact:true}).getByRole('button',{name:'Edit symbol timeline',exact:true}).click();
  if(mode==='overlay')await page.getByLabel('Symbol layer',{exact:true}).selectOption('overlay');
  const frame=page.getByLabel('Symbol frame',{exact:true});await frame.fill('5');await frame.press('Tab');
 };
 const rotate=async()=>{
  await page.getByLabel('Symbol shared endpoint artwork',{exact:true}).selectOption('moving');
  await page.getByLabel('Symbol shared endpoint rotation',{exact:true}).fill('90');
  await page.getByRole('button',{name:'Rotate symbol endpoint and refresh both spans',exact:true}).click();
 };
 await open();await rotate();expect(await read()).toEqual(before);
 const undo=page.getByRole('button',{name:'Undo symbol timeline change',exact:true}),redo=page.getByRole('button',{name:'Redo symbol timeline change',exact:true});
 if(mode==='stale'){
  await expect(page.getByText(/Generated keys changed/).first()).toBeVisible();await expect(undo).toBeDisabled();await page.getByRole('button',{name:'Cancel symbol timeline',exact:true}).click();expect(await read()).toEqual(before);return;
 }
 const canvas=page.getByLabel('Symbol timeline preview',{exact:true});
 const pixel=(x:number,y:number)=>canvas.evaluate((el,p)=>Array.from((el as HTMLCanvasElement).getContext('2d')!.getImageData(20+p.x*2.9,20+p.y*2.9,1,1).data),{x,y});
 if(mode!=='overlay'){
  await expect.poll(()=>pixel(mode==='saved'?34:52,mode==='saved'?22:25)).toEqual(mode==='nested'?[0,255,0,255]:[255,0,0,255]);
 }
 await undo.click();await expect(undo).toBeDisabled();expect(await read()).toEqual(before);await redo.click();await expect(undo).toBeEnabled();
 await page.getByRole('button',{name:'Cancel symbol timeline',exact:true}).click();expect(await read()).toEqual(before);
 await open();await rotate();expect(await read()).toEqual(before);
 if(mode==='source'){
  await page.getByRole('button',{name:'Add layer',exact:true}).evaluate(el=>(el as HTMLButtonElement).click());
  await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();await expect(page.getByText(/Project changed\. Cancel and reopen/).first()).toBeVisible();
  const changed=await read();expect(changed.symbols).toEqual(before.symbols);expect(changed.layers).toHaveLength(2);
  await page.getByRole('button',{name:'Cancel symbol timeline',exact:true}).click();await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(before);return;
 }
 await page.getByRole('button',{name:'Apply symbol timeline',exact:true}).click();
 const result=await read(),actual=result.symbols!.find(s=>s.id==='child')!,original=before.symbols!.find(s=>s.id==='child')!;
 const keys=mode==='overlay'?actual.timeline!.layers![0].keys:[{frame:0,shapes:actual.shapes},...actual.timeline!.keys],oldKeys=mode==='overlay'?original.timeline!.layers![0].keys:[{frame:0,shapes:original.shapes},...original.timeline!.keys];
 const joint=keys.find(k=>k.frame===4)!.shapes[0];expect(joint.rotation).toBe(90);expect(joint.x).toBeCloseTo(mode==='saved'?40:58);expect(joint.y).toBeCloseTo(mode==='saved'?10:4);
 expect(keys.find(k=>k.frame===2)!.shapes[0].rotation).toBeCloseTo(22.5);expect(keys.find(k=>k.frame===6)!.shapes[0].rotation).toBeCloseTo(45);
 expect(keys.map(k=>k.shapes[1])).toEqual(oldKeys.map(k=>k.shapes[1]));expect(keys.filter(k=>[0,8,10].includes(k.frame))).toEqual(oldKeys.filter(k=>[0,8,10].includes(k.frame)));
 expect(actual.buttonStates).toEqual(original.buttonStates);expect(actual.timeline!.duration).toBe(12);
 const spans=mode==='overlay'?actual.timeline!.layers![0].motionSpans:actual.timeline!.motionSpans,oldSpans=mode==='overlay'?original.timeline!.layers![0].motionSpans:original.timeline!.motionSpans;
 expect(spans!.map(({baseline:_baseline,...settings})=>settings)).toEqual(oldSpans!.map(({baseline:_baseline,...settings})=>settings));
 if(mode==='overlay'){expect(actual.shapes).toEqual(original.shapes);expect(actual.timeline!.keys).toEqual(original.timeline!.keys);}else expect(actual.timeline!.layers).toEqual(original.timeline!.layers);
 if(mode==='nested'){
  expect(result.symbols!.find(s=>s.id==='graphic')).toEqual(graphic);
  expect(keys.map(k=>k.shapes[0]?.symbolPlayback)).toEqual(oldKeys.map(k=>k.shapes[0]?.symbolPlayback));
 }
 await page.getByLabel('Drawing stage').focus();await page.keyboard.press('Control+z');expect(await read()).toEqual(before);await page.keyboard.press('Control+Shift+z');expect(await read()).toEqual(result);
});


