 const child={id:'group-graphic',name:'Group graphic',width:12,height:12,shapes:[ink('child-ink',0,0,'#ff0000')],
 timeline:{duration:3,keys:[{frame:1,shapes:[ink('child-ink',0,0,'#00ff00')]},{frame:2,shapes:[ink('child-ink',0,0,'#0000ff')]}]}};
 if(mode==='nested'){p.symbols=[child];shapes=shapes.map(s=>s.id==='c'?{...s,kind:'symbol',symbolId:child.id,symbolPlayback:{mode:'loop',firstFrame:0}}:s);}
