 const testDialog=page.getByRole('dialog',{name:'Button state test',exact:true}),canvas=testDialog.getByLabel('Test symbol button',{exact:true}),toggle=testDialog.getByLabel('Use remembered button states',{exact:true});
 const pixel=(x:number,y:number)=>canvas.evaluate((el,p)=>Array.from((el as HTMLCanvasElement).getContext('2d')!.getImageData(20+p.x*2.5,20+p.y*2.5,1,1).data),{x,y});
