  const button={id:'button',name:'Remembered button',width:200,height:100,shapes:root.keys[0].shapes,buttonStates:{up:2,over:2,down:6,hit:4},timeline:{duration:12,keys:root.keys.slice(1),motionSpans:root.motionSpans,layers:[{...p.layers[1],keys:[{frame:0,shapes:[movie]}]}]}};
