 const pending=!stream&&!failure?page.waitForEvent('download'):undefined;
 const command=stream?(sheet?'Save PNG sprite sheet ZIP to file…':selected?'Save selected PNG range ZIP to file…':'Save PNG sequence ZIP to file…'):(single?'Export current frame PNG…':sheet?'Export PNG sprite sheet ZIP…':selected?'Export selected PNG range ZIP…':'Export PNG sequence ZIP…');
