   expect(result.blue).toEqual(f<10?[0,0,255,255]:[255,255,255,255]);expect(result.reentry).toEqual(f===2||f===3?[255,255,255,255]:[255,0,0,255]);expect(result.continuous).toEqual(f<10?[255,0,0,255]:[255,255,255,255]);expect(result.button).toEqual([0,0,255,255]);
