for(const kind of ['direct','static nested','animated nested','multilayer nested','fixed-frame nested','scripted animated nested'] as const)test(`scene ${kind} button visibility survives replay and requires a fresh press after reveal`,async({page})=>{
  const nested=kind!=='direct', fixed=kind==='fixed-frame nested';
  const scripted=kind==='scripted animated nested';
  const multilayer=fixed||kind==='multilayer nested'||scripted, animated=kind==='animated nested'||kind==='multilayer nested'||scripted;
  const project=newProject();
  project.width=80;project.height=40;project.duration=animated?4:2;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  project.symbols=[{id:'button',name:'Button',width:20,height:20,shapes:[art],
    timeline:{duration:2,keys:[{frame:1,shapes:[{...art,fill:'#0000ff'}]}],
      ...(scripted?{frameScripts:[0,1].map(frame=>({frame,
        source:'state.visits=(typeof state.visits==="string"?state.visits:"")+timeline.currentFrame; if(input.buttonActivation)state.activated=true;',
      }))}:{})},buttonStates:{up:0,over:0,down:1,hit:0}}];
  const root:Vector={...art,id:'action</script>',kind:'symbol',symbolId:'button',instanceName:'Action'};
  project.layers[0].keys=[{frame:0,shapes:[root,{...root,id:'other',x:30,instanceName:'Companion'}]}];
  if(nested){
    const child={...root,id:'child'};
    const childKeys=[{frame:0,shapes:fixed?[]:[child]},{frame:1,shapes:fixed?[child]:[]},{frame:2,shapes:[child]}];
    project.symbols.push({id:'panel',name:'Panel',width:20,height:20,shapes:multilayer?[]:[child],
      ...(multilayer?{timeline:{duration:3,keys:[],layers:[{
        id:'controls',name:'Controls',visible:true,locked:false,keys:childKeys,
      }]}}:animated?{timeline:{duration:3,keys:childKeys.slice(1)}}:{})});
    project.layers[0].keys[0].shapes=[
      {...root,id:'first',symbolId:'panel',instanceName:'First'},
      {...root,id:'second',symbolId:'panel',instanceName:'Second',x:30},
    ];
    if(fixed) for(const shape of project.layers[0].keys[0].shapes) shape.symbolPlayback={mode:'single',firstFrame:1};
    if(scripted)project.layers[0].keys[0].shapes[1].symbolPlayback={mode:'loop',firstFrame:2};
  }
  const setter=nested?'setChildVisible("First","Action",':'setVisible("Action",';
  project.frameScripts=[{frame:0,source:`
    ${nested?'state.owned=stage!.getChildInstance("First","Action")?.id??null; state.root=!!stage!.getInstance("Action");':''}
    if(input.hide===true)stage!.${setter}false);
    if(input.reveal===true)stage!.${setter}true);
    if(input.type==="pointerup"){state.hit=!!input.buttonTarget;state.activated=!!input.buttonActivation;}
    timeline.stop();
  `}];
  if(animated){const source=project.frameScripts[0].source;project.frameScripts=[0,1,2,3].map(frame=>({frame,source}));}
  await page.addInitScript(project=>{if(window===parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const recovery=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const dialog=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const button=(name:string)=>dialog.getByRole('button',{name,exact:true});
  const status=dialog.getByRole('status');
  const state=dialog.getByLabel('Script preview state');
  const placedState=async()=>JSON.parse((await dialog.getByLabel('Placed symbol script states').textContent())!);
  const press=dialog.getByLabel('Script button press');
  const enable=async()=>{
    await dialog.getByLabel('Capture pointers on artwork').check();
    await dialog.getByLabel('Include button target for new pointers').check();
  };
  const pointer=async(type:string)=>{
    await dialog.getByRole('application',{name:'Script pointer target'}).evaluate((host,type)=>{
      const img=host.querySelector('img')!,rect=img.getBoundingClientRect();
      host.dispatchEvent(new PointerEvent(type,{pointerId:19,button:0,bubbles:true,
        clientX:rect.left+rect.width*10/img.naturalWidth,clientY:rect.top+rect.height*10/img.naturalHeight}));
    },type);
    await button('Deliver next pointer and step').click();
    await expect(status).toHaveText('Completed 1 script tick.');
  };
  const send=async(data:object)=>{
    await dialog.getByLabel('Script input JSON').fill(JSON.stringify(data));
    await button('Send input and step').click();
    await expect(status).toHaveText('Completed 1 script tick.');
  };
  const pixels=()=>dialog.getByAltText('Script preview artwork').evaluate(async node=>{
    const img=node as HTMLImageElement;await img.decode();const canvas=document.createElement('canvas');
    canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
    const ctx=canvas.getContext('2d')!;ctx.drawImage(img,0,0);
    return [10,40].map(x=>Array.from(ctx.getImageData(x,10,1,1).data));
  });
  await dialog.getByLabel('Render detached artwork').check();
  if(scripted)await dialog.getByLabel('Run placed symbol frame scripts').check();
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  const red=[255,0,0,255],white=[255,255,255,255];
  await expect.poll(pixels).toEqual([red,red]);
  await enable();
  await pointer('pointerdown');
  await expect(press).toContainText('Pressed: Button');
  const authoredButton=(side:string,mode:string,visits:string,activated=false)=>({
    layerId:project.layers[0].id,shapeId:side+'/controls/child',symbolId:'button',frame:mode==='down'?1:0,
    state:{visits,...(activated?{activated}: {})},mode:'button',buttonVisual:mode,
  });
  if(scripted)expect(await placedState()).toEqual([
    authoredButton('first','down','1'),authoredButton('second','up','0'),
  ]);
  await send({hide:true});
  await expect(press).toHaveText('No button press active.');
  if(nested){await expect(state).toContainText(`"owned": "${multilayer?"first/controls/child":"first/child"}"`);await expect(state).toContainText('"root": false');}
  await expect.poll(pixels).toEqual([white,red]);
  await button('Capture script checkpoint').click();
  if(animated){
    const seek=async(frame:number)=>{
      await dialog.getByLabel('Seek target frame').fill(String(frame));
      await button('Seek stopped and step').click();
      await expect(status).toHaveText('Completed 1 script tick.');
    };
    await seek(2);
    await expect(state).toContainText('"owned": null');
    await expect.poll(pixels).toEqual([white,scripted?red:white]);
    if(scripted)expect(await placedState()).toEqual([authoredButton('second','up','0')]);
    await seek(3);
    await expect(state).toContainText(`"owned": "${multilayer?"first/controls/child":"first/child"}"`);
    if(scripted)expect(await placedState()).toEqual([authoredButton('first','up','0')]);
  }else await send({reveal:true});
  await expect.poll(pixels).toEqual([red,scripted?white:red]);
  await pointer('pointerup');
  await expect(state).toContainText('"hit": true');
  await expect(state).toContainText('"activated": false');
  if(scripted)expect(await placedState()).toEqual([authoredButton('first','over','00')]);
  await pointer('pointerdown');
  await pointer('pointerup');
  await expect(state).toContainText('"activated": true');
  if(scripted)expect(await placedState()).toEqual([authoredButton('first','over','0010',true)]);
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  await expect.poll(pixels).toEqual([red,scripted?white:red]);
  if(scripted)expect(await placedState()).toEqual([authoredButton('first','over','0010',true)]);
  await button('Restore script checkpoint').click();
  await expect(status).toContainText('Checkpoint restored');
  await expect.poll(pixels).toEqual([white,red]);
  if(scripted)expect(await placedState()).toEqual([authoredButton('second','up','0')]);
  await enable();
  await pointer('pointerup');
  await expect(state).toContainText('"hit": false');
  await expect(state).toContainText('"activated": false');
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(recovery);
});

test('scene scripted placement transforms update detached pixels and replay', async ({page}) => {
  const project=newProject();
  project.width=80;project.height=40;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const actor:Vector={...art,id:'actor',kind:'symbol',symbolId:'graphic',instanceName:'Actor'};
  project.symbols=[{id:'graphic',name:'Graphic',width:20,height:20,shapes:[art]}];
  project.layers[0].keys[0].shapes=[actor,{...actor,id:'peer',instanceName:'Peer',x:50}];
  project.frameScripts=[{frame:0,source:`
    if (input.forge) state.$splashPlacementTransforms=[["forged",40,0,90,[-1.5,0,0.5,0.5]]];
    else if (input.affine) {
      state.basisBefore=[...stage!.getBasis("Actor")!];
      stage!.setBasis("Actor",[-1.5,0,0.5,0.5]);
      stage!.setTransform("Actor",{x:40,y:0,rotation:0});
      state.basisAfter=[...stage!.getBasis("Actor")!];
    }
    else {
      state.before={...stage!.getTransform("Actor")!};
      stage!.setTransform("Actor",{x:40,y:0,rotation:90});
      state.after={...stage!.getTransform("Actor")!};
    }
    timeline.stop();
  `}];
  await page.addInitScript(project=>{if(window===parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const recovery=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const dialog=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const button=(name:string)=>dialog.getByRole('button',{name,exact:true});
  const status=dialog.getByRole('status');
  const pixels=()=>dialog.getByAltText('Script preview artwork').evaluate(async node=>{
    const img=node as HTMLImageElement;await img.decode();const canvas=document.createElement('canvas');
    canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
    const ctx=canvas.getContext('2d')!;ctx.drawImage(img,0,0);
    return [[5,5],[25,5],[55,5],[42,5],[25,14]].map(([x,y])=>Array.from(ctx.getImageData(x,y,1,1).data));
  });
  const red=[255,0,0,255],white=[255,255,255,255];
  await dialog.getByLabel('Render detached artwork').check();
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  await expect.poll(pixels).toEqual([red,white,red,white,white]);
  await button('Capture script checkpoint').click();
  await button('Step script tick').click();
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual([white,red,red,white,red]);
  await expect(dialog.getByLabel('Script preview state')).toContainText('"rotation": 90');
  await dialog.getByLabel('Script input JSON').fill('{"affine":true}');
  await button('Send input and step').click();
  await expect(status).toHaveText('Completed 1 script tick.');
  const affinePixels=[white,red,red,red,white];
  await expect.poll(pixels).toEqual(affinePixels);
  await expect(dialog.getByLabel('Script preview state')).toContainText('"basisAfter"');
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  await expect.poll(pixels).toEqual(affinePixels);
  await dialog.getByLabel('Script input JSON').fill('{"forge":true}');
  await button('Send input and step').click();
  await expect(status).toContainText('Unknown script placement transform target');
  await expect.poll(pixels).toEqual(affinePixels);
  await button('Restore script checkpoint').click();
  await expect(status).toContainText('Checkpoint restored');
  await expect.poll(pixels).toEqual([red,white,red,white,white]);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(recovery);
});

test('scene scripts create and remove preview-owned graphics through library links', async ({page})=>{
  const project=newProject();
  project.width=80;project.height=40;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  project.symbols=[
    {id:'asset',name:'Asset',width:20,height:20,shapes:[art]},
    {id:'button',name:'Button',width:20,height:20,shapes:[art],buttonStates:{up:0,over:0,down:0,hit:0}},
  ];
  project.libraryLinks=[
    {kind:'symbol',id:'asset',name:'graphics.Badge'},
    {kind:'symbol',id:'button',name:'graphics.Button'},
    {kind:'audio',id:'sound',name:'effects.Chime'},
  ];
  project.assets=[{id:'sound',path:'assets/audio/sound.wav',
    audio:{name:'Chime',format:'pcm16-wav',sampleRate:48000,channels:1,frames:48}}];
  project.layers[0].keys[0].shapes=[{...art,id:'authored',kind:'symbol',symbolId:'asset',instanceName:'Original'}];
  project.frameScripts=[{frame:0,source:`
    if (input.remove) stage!.removeSpawned("Preview");
    else if (input.authored) stage!.removeSpawned("Original");
    else if (input.invalid) state.$splashSpawnedGraphics=[["Other","button",25,0,0]];
    else if (input.nonGraphic) stage!.library.spawnGraphic("graphics.Button","Preview",{x:25,y:0,rotation:0});
    else stage!.library.spawnGraphic("graphics.Badge","Preview",{x:25,y:0,rotation:0});
    const linked=stage!.library.get("graphics.Badge");
    if (linked?.kind==="symbol") state.linked={id:linked.id,settings:linked.defaultPlayback,width:linked.width};
    const sound=stage!.library.get("effects.Chime");
    if (sound?.kind==="audio") state.audioFormat=sound.format;
    state.spawned=stage!.getSpawned("Preview")?.symbolId ?? null;
    timeline.stop();
  `}];
  await page.addInitScript(project=>{if(window===parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const recovery=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const dialog=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const button=(name:string)=>dialog.getByRole('button',{name,exact:true});
  const status=dialog.getByRole('status');
  const send=async (input:object)=>{
    await dialog.getByLabel('Script input JSON').fill(JSON.stringify(input));
    await button('Send input and step').click();
  };
  const pixels=()=>dialog.getByAltText('Script preview artwork').evaluate(async node=>{
    const img=node as HTMLImageElement;await img.decode();
    const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
    const ctx=canvas.getContext('2d')!;ctx.drawImage(img,0,0);
    return [5,30].map(x=>Array.from(ctx.getImageData(x,5,1,1).data));
  });
  const red=[255,0,0,255],white=[255,255,255,255];
  await dialog.getByLabel('Render detached artwork').check();
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  await expect.poll(pixels).toEqual([red,white]);
  await button('Step script tick').click();
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual([red,red]);
  await expect(dialog.getByLabel('Script preview state')).toContainText('"settings": "loop"');
  await expect(dialog.getByLabel('Script preview state')).toContainText('"audioFormat": "pcm16-wav"');
  await button('Capture script checkpoint').click();
  await send({remove:true});
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual([red,white]);
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  await expect.poll(pixels).toEqual([red,white]);
  await send({authored:true});
  await expect(status).toContainText('Removal requires a script-owned graphic');
  await send({invalid:true});
  await expect(status).toContainText('unavailable for scripted creation');
  await send({nonGraphic:true});
  await expect(status).toContainText('This library link cannot create a preview graphic');
  await expect.poll(pixels).toEqual([red,white]);
  await button('Restore script checkpoint').click();
  await expect(status).toContainText('Checkpoint restored');
  await expect.poll(pixels).toEqual([red,red]);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(recovery);
});

test('scene scripts resolve named graphic children at each parent clock',async({page})=>{
  const project=newProject();
  project.duration=3;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:10,height:10,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const child:Vector={...art,id:'child',kind:'symbol',symbolId:'asset',instanceName:'Leaf'};
  const parent:Vector={...child,id:'first',symbolId:'panel',instanceName:'First'};
  project.symbols=[
    {id:'asset',name:'Asset',width:10,height:10,shapes:[art]},
    {id:'panel',name:'Panel',width:10,height:10,shapes:[],timeline:{duration:3,keys:[],layers:[
      {id:'details',name:'Details',visible:true,locked:false,keys:[
        {frame:0,shapes:[]},{frame:1,shapes:[child]},{frame:2,shapes:[]},
      ]},
    ]}},
  ];
  project.layers[0].keys[0].shapes=[parent,{...parent,id:'second',instanceName:'Second',x:15,
    symbolPlayback:{mode:'single',firstFrame:1}}];
  const source=`
    if (input.tryWrite) stage!.setChildVisible("Second","Leaf",false);
    state.first=stage!.getChildInstance("First","Leaf")?.id??null;
    state.second=stage!.getChildInstance("Second","Leaf")?.id??null;
    state.root=!!stage!.getInstance("Leaf");
    timeline.play();
  `;
  project.frameScripts=[0,1,2].map(frame=>({frame,source}));
  await page.addInitScript(project=>{if(window===window.parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const recovery=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const dialog=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const button=(name:string)=>dialog.getByRole('button',{name,exact:true});
  const status=dialog.getByRole('status'),state=dialog.getByLabel('Script preview state');
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  const step=async()=>{
    await button('Step script tick').click();
    await expect(status).toHaveText('Completed 1 script tick.');
  };
  await step();
  await expect(state).toContainText('"first": null');
  await expect(state).toContainText('"second": "second/details/child"');
  await step();
  await expect(state).toContainText('"first": "first/details/child"');
  await expect(state).toContainText('"root": false');
  await button('Capture script checkpoint').click();
  await step();
  await expect(state).toContainText('"first": null');
  await dialog.getByLabel('Script input JSON').fill('{"tryWrite":true}');
  await button('Send input and step').click();
  await expect(status).toContainText('Visibility requires a named noninteractive graphic');
  await expect(state).toContainText('"second": "second/details/child"');
  await button('Restore script checkpoint').click();
  await expect(state).toContainText('"first": "first/details/child"');
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(recovery);
});

test('scene linked bitmap preview waits for decode and rolls back a damaged image',async({page})=>{
  const image=await page.evaluate(()=>{
    const canvas=document.createElement('canvas');canvas.width=12;canvas.height=8;
    const ctx=canvas.getContext('2d')!;ctx.fillStyle='#00ff00';ctx.fillRect(0,0,12,8);
    return canvas.toDataURL('image/png');
  });
  const project=newProject();
  project.width=60;project.height=24;
  project.assets=[
    {id:'picture',path:'assets/bitmaps/picture.json',bitmap:{name:'Picture',width:12,height:8,dataUrl:image}},
    {id:'damaged',path:'assets/bitmaps/damaged.json',bitmap:{name:'Damaged',width:12,height:8,dataUrl:image.slice(0,66)}},
    {id:'missing',path:'assets/bitmaps/missing.json',bitmap:{name:'Missing',width:12,height:8}},
  ];
  project.libraryLinks=[
    {kind:'bitmap',id:'picture',name:'art.Picture'},
    {kind:'bitmap',id:'damaged',name:'art.Damaged'},
    {kind:'bitmap',id:'missing',name:'art.Missing'},
  ];
  project.frameScripts=[{frame:0,source:`
    if (!stage) throw Error("Stage is unavailable.");
    if (input.remove) stage.removeSpawned("Print");
    else if (input.damage) {
      stage.removeSpawned("Print");
      stage.library.spawnBitmap("art.Damaged","Broken",{x:25,y:0,rotation:0});
    } else if (input.missing) stage.library.spawnBitmap("art.Missing","Missing",{x:25,y:0,rotation:0});
    else stage.library.spawnBitmap("art.Picture","Print",{x:20,y:0,rotation:0});
    state.art=stage.getSpawned("Print")?.assetId??null;
    const entry=stage.library.get("art.Picture");
    if (entry?.kind==="bitmap") state.size=[entry.width,entry.height];
    timeline.stop();
  `}];
  await page.addInitScript(project=>{if(window===window.parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const original=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const dialog=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const button=(name:string)=>dialog.getByRole('button',{name,exact:true});
  const status=dialog.getByRole('status'),state=dialog.getByLabel('Script preview state');
  const send=async (input:object)=>{
    await dialog.getByLabel('Script input JSON').fill(JSON.stringify(input));
    await button('Send input and step').click();
  };
  const pixels=()=>dialog.getByAltText('Script preview artwork').evaluate(async node=>{
    const img=node as HTMLImageElement;await img.decode();
    const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
    const ctx=canvas.getContext('2d')!;ctx.drawImage(img,0,0);
    return [[19,4],[20,4],[31,7],[32,4],[21,8]].map(([x,y])=>Array.from(ctx.getImageData(x,y,1,1).data));
  });
  const white=[255,255,255,255],green=[0,255,0,255];
  const blank=[white,white,white,white,white],placed=[white,green,green,white,white];
  await dialog.getByLabel('Render detached artwork').check();
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  await expect.poll(pixels).toEqual(blank);
  await button('Step script tick').click();
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual(placed);
  await expect(state).toContainText('"art": "picture"');
  await button('Capture script checkpoint').click();
  await send({damage:true});
  await expect(status).toContainText('Script artwork rendering failed');
  await expect.poll(pixels).toEqual(placed);
  await expect(state).toContainText('"art": "picture"');
  await send({missing:true});
  await expect(status).toContainText('cannot create a preview bitmap');
  await send({remove:true});
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual(blank);
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  await expect.poll(pixels).toEqual(blank);
  await button('Restore script checkpoint').click();
  await expect(status).toContainText('Checkpoint restored');
  await expect.poll(pixels).toEqual(placed);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
});

test('linked timeline symbols retain independent creation clocks in scene script previews',async({page})=>{
  const project=newProject();
  project.width=60;project.height=24;project.duration=4;
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:12,height:12,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  project.symbols=[{id:'graphic',name:'Graphic',width:12,height:12,shapes:[art],timeline:{duration:3,keys:[
    {frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]},
  ]}}];
  project.symbols.push({...structuredClone(project.symbols[0]),id:'movie',name:'Movie',defaultPlayback:'movie'});
  project.symbols[1].timeline!.frameScripts=[{frame:0,source:'throw new Error("Linked descendant scripts must stay idle.");'}];
  project.libraryLinks=[{id:'graphic',kind:'symbol',name:'art.Graphic'},{id:'movie',kind:'symbol',name:'art.Movie'}];
  project.frameScripts=[{frame:0,source:`
    if (!stage) throw Error("Stage is unavailable.");
    if (input.forge) state.$splashSpawnedGraphics=[["Wrong","movie",0,0,0,"timeline",0,0]];
    if (input.create) {
      stage.library.spawnGraphic("art.Graphic","Graphic",{x:0,y:0,rotation:0});
      stage.library.spawnGraphic("art.Movie","Movie",{x:25,y:0,rotation:0});
    }
    if (input.advance) timeline.play(); else timeline.stop();
  `}];
  await page.addInitScript(project=>{if(window===window.parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const original=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const dialog=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const button=(name:string)=>dialog.getByRole('button',{name,exact:true}),status=dialog.getByRole('status');
  const send=async(data:object)=>{
    await dialog.getByLabel('Script input JSON').fill(JSON.stringify(data));
    await button('Send input and step').click();
  };
  const step=async()=>{await button('Step script tick').click();await expect(status).toHaveText('Completed 1 script tick.');};
  const pixels=()=>dialog.getByAltText('Script preview artwork').evaluate(async node=>{
    const img=node as HTMLImageElement;await img.decode();const canvas=document.createElement('canvas');
    canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
    const ctx=canvas.getContext('2d')!;ctx.drawImage(img,0,0);
    return [5,30].map(x=>Array.from(ctx.getImageData(x,5,1,1).data));
  });
  const red=[255,0,0,255],green=[0,255,0,255],blue=[0,0,255,255];
  await dialog.getByLabel('Render detached artwork').check();
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  await step();await step();
  await send({create:true});
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual([red,red]);
  await step();
  await expect.poll(pixels).toEqual([red,green]);
  await button('Capture script checkpoint').click();
  await send({forge:true});
  await expect(status).toContainText('Invalid spawned symbol origin');
  await expect.poll(pixels).toEqual([red,green]);
  await send({advance:true});
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect.poll(pixels).toEqual([green,blue]);
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  await expect.poll(pixels).toEqual([green,blue]);
  await button('Restore script checkpoint').click();
  await expect(status).toContainText('Checkpoint restored');
  await expect.poll(pixels).toEqual([red,green]);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
});

test('scene script sound is opt-in and pauses, resumes and seeks decoded audio',async({page})=>{
  const project=newProject();
  project.fps=20;
  project.assets=['tone','wrong'].map(id=>({id,path:'assets/audio/'+id+'.wav',
    audio:{name:id,format:'pcm16-wav' as const,sampleRate:8000,channels:1 as const,frames:16000}}));
  project.libraryLinks=['tone','wrong'].map(id=>({id,kind:'audio' as const,name:'fx.'+id}));
  project.frameScripts=[{frame:0,source:`
    const sound=stage?.sound;
    state.permission=!!sound;
    if (input.play) sound?.play("fx.tone",200,0.5);
    if (input.fail) sound?.play("fx.wrong");
    if (input.pause) sound?.pause();
    if (input.resume) sound?.resume();
    if (typeof input.seek==="number") sound?.seekSamples(input.seek);
    if (input.stop) sound?.stop();
    state.sample=sound?.positionSamples()??null;
    timeline.stop();
  `}];
  await page.addInitScript(project=>{
    if(window!==window.parent)return;
    localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));
    const Native=window.AudioContext,contexts:AudioContext[]=[],starts:number[]=[],stops:number[]=[];
    const probes:AnalyserNode[]=[];
    Object.assign(window,{soundTest:{contexts,starts,stops,probes},AudioContext:class extends Native{
      constructor(){super();contexts.push(this);}
      createBufferSource(){
        const node=super.createBufferSource(),start=node.start.bind(node),stop=node.stop.bind(node),probe=this.createAnalyser();
        probes.push(probe);node.connect(probe);
        node.start=(when=0,offset=0,duration?:number)=>{starts.push(offset);start(when,offset,duration);};
        node.stop=(when=0)=>{stops.push(when);stop(when);};
        return node;
      }
    }});
  },project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const original=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  const open=async()=>{
    await page.getByRole('button',{name:'Control',exact:true}).click();
    await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  };
  await open();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true});
  const status=d.getByRole('status'),state=d.getByLabel('Script preview state');
  const button=(name:string)=>d.getByRole('button',{name,exact:true});
  const prep=async()=>{await button('Prepare script preview').click();await expect(status).toHaveText('Ready. No scripts have run.');};
  const send=async(data:object)=>{
    await d.getByLabel('Script input JSON').fill(JSON.stringify(data));
    await button('Send input and step').click();
  };
  const diagnostics=()=>page.evaluate(()=>{
    const t=Reflect.get(window,'soundTest') as {contexts:AudioContext[];starts:number[];stops:number[]};
    return {states:t.contexts.map(ctx=>ctx.state),starts:t.starts,stops:t.stops.length};
  });
  await prep();
  await send({play:true});
  await expect(state).toContainText('"permission": false');
  expect(await diagnostics()).toEqual({states:[],starts:[],stops:0});
  await button('Close dialog').click();
  await open();
  await d.getByLabel('Enable scripted sound').check();
  const samples=Float32Array.from({length:16000},(_,i)=>0.4*Math.sin(i*2*Math.PI*440/8000));
  await d.getByLabel('WAV for fx.tone').setInputFiles({name:'tone.wav',mimeType:'audio/wav',buffer:Buffer.from(encodePcm16Wav([samples],8000))});
  await d.getByLabel('WAV for fx.wrong').setInputFiles({name:'wrong.wav',mimeType:'audio/wav',buffer:Buffer.from(encodePcm16Wav([samples.slice(0,100)],8000))});
  await prep();
  expect(await diagnostics()).toEqual({states:['running'],starts:[],stops:0});
  await send({play:true});
  await expect(status).toHaveText('Completed 1 script tick.');
  await expect(state).toContainText('"sample": 200');
  await expect.poll(async()=>page.evaluate(()=>{
    const {probes}=Reflect.get(window,'soundTest') as {probes:AnalyserNode[]};
    const samples=new Float32Array(probes[0].fftSize);
    probes[0].getFloatTimeDomainData(samples);
    return Math.max(...samples);
  })).toBeGreaterThan(0.2);
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025],stops:0});
  await send({});
  await expect(state).toContainText('"sample": 200');
  await send({});
  await expect(state).toContainText('"sample": 600');
  await send({fail:true});
  await expect(status).toContainText('Script WAV does not match its captured metadata');
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025],stops:0});
  await send({pause:true});
  await expect(state).toContainText('"sample": 1000');
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025],stops:1});
  await send({});
  await expect(state).toContainText('"sample": 1000');
  await send({seek:16001});
  await expect(status).toContainText('valid sample offset');
  await expect(state).toContainText('"sample": 1000');
  await send({seek:4000});
  await expect(state).toContainText('"sample": 4000');
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025],stops:1});
  await send({resume:true});
  await expect(status).toHaveText('Completed 1 script tick.');
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025,0.5],stops:1});
  await send({seek:6000});
  await expect(state).toContainText('"sample": 6000');
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025,0.5,0.75],stops:2});
  await send({stop:true});
  await expect(state).toContainText('"sample": null');
  expect(await diagnostics()).toEqual({states:['running'],starts:[0.025,0.5,0.75],stops:3});
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  expect((await diagnostics()).starts).toEqual([0.025,0.5,0.75]);
  await button('Close dialog').click();
  await expect.poll(async()=>(await diagnostics()).states).toEqual(['closed']);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
});

for(const damage of [false,true])test(`multi-tick script sound ${damage?'rejects a later invalid cue atomically':'plays intermediate cues in order'}`,async({page})=>{
  const project=newProject();
  project.fps=10;project.duration=10;
  project.assets=['first','second'].map(id=>({id,path:'assets/audio/'+id+'.wav',
    audio:{name:id,format:'pcm16-wav' as const,sampleRate:8000,channels:1 as const,frames:8000}}));
  project.libraryLinks=['first','second'].map(id=>({id,kind:'audio' as const,name:'fx.'+id}));
  project.frameScripts=[
    {frame:0,source:'stage!.sound!.play("fx.first",800); timeline.play();'},
    {frame:2,source:'stage!.sound!.stop();'},
    {frame:4,source:'stage!.sound!.play("fx.second",1600);'},
    {frame:6,source:'stage!.sound!.stop(); state.completed=true;'},
  ];
  await page.addInitScript(project=>{
    if(window!==window.top)return;
    localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));
    const Native=window.AudioContext,starts:number[][]=[],stops:number[]=[];
    Reflect.set(window,'soundBatch',{starts,stops});
    Object.assign(window,{AudioContext:class extends Native{
      createBufferSource(){
        const node=super.createBufferSource(),start=node.start.bind(node),stop=node.stop.bind(node);
        node.start=(when=0,offset=0,duration?:number)=>{starts.push([when,offset]);start(when,offset,duration);};
        node.stop=(when=0)=>{stops.push(when);stop(when);};
        return node;
      }
    }});
  },project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true}),status=d.getByRole('status');
  const button=(name:string)=>d.getByRole('button',{name,exact:true});
  const calls=()=>page.evaluate(()=>Reflect.get(window,'soundBatch') as {starts:number[][];stops:number[]});
  await d.getByLabel('Enable scripted sound').check();
  const pcm=Float32Array.from({length:8000},(_,i)=>0.4*Math.sin(i*2*Math.PI*440/8000));
  for(const [name,frames] of [['first',8000],['second',damage?800:8000]] as const)
    await d.getByLabel('WAV for fx.'+name).setInputFiles({name:name+'.wav',mimeType:'audio/wav',
      buffer:Buffer.from(encodePcm16Wav([pcm.slice(0,frames)],8000))});
  await button('Prepare script preview').click();
  await expect(status).toHaveText('Ready. No scripts have run.');
  await button('Run 10 script ticks').click();
  if(damage){
    await expect(status).toContainText('Script WAV does not match its captured metadata');
    expect(await calls()).toEqual({starts:[],stops:[]});
    await expect(d.getByLabel('Script preview state')).toHaveText('{}');
    return;
  }
  await expect(status).toHaveText('Completed 10 script ticks.');
  await expect(d.getByLabel('Script preview state')).toContainText('"completed": true');
  const {starts,stops}=await calls();
  expect(starts.map(([,offset])=>offset)).toEqual([0.1,0.2]);
  expect(starts[1][0]-starts[0][0]).toBeCloseTo(0.4,6);
  expect(stops[0]-starts[0][0]).toBeCloseTo(0.2,6);
  expect(stops[1]-starts[1][0]).toBeCloseTo(0.2,6);
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  expect((await calls()).starts).toHaveLength(2);
});

test('explicit scene preview dispatches saved graphic bodies per authored exposure',async({page})=>{
  const project=newProject();
  project.duration=5;
  const layer=project.layers[0];
  const leaf:Vector={kind:'rectangle',id:'leaf',x:0,y:0,width:12,height:12,rotation:0,
    fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const first:Vector={...leaf,kind:'symbol',id:'first',symbolId:'graphic'};
  const source='state.count=(typeof state.count==="number"?state.count:0)+1; state.frame=timeline.currentFrame; timeline.stop();';
  project.symbols=[{id:'graphic',name:'Graphic',width:12,height:12,shapes:[leaf],
    timeline:{duration:3,keys:[],frameScripts:[
      {frame:0,source},{frame:1,source},{frame:2,source:'throw new Error("child rejected");'},
    ]}}];
  layer.keys=[
    {frame:0,shapes:[first,{...first,id:'fixed',x:20,symbolPlayback:{mode:'single',firstFrame:1}}]},
    {frame:2,shapes:[{...first}]},
    {frame:3,shapes:[]},
    {frame:4,shapes:[{...first,symbolPlayback:{mode:'single',firstFrame:2}}]},
  ];
  project.frameScripts=[{frame:0,source:'state.scene=1; timeline.play();'}];
  await page.addInitScript(project=>{if(window===window.top)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const original=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  const open=async()=>{
    await page.getByRole('button',{name:'Control',exact:true}).click();
    await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  };
  await open();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true}),status=d.getByRole('status');
  const button=(name:string)=>d.getByRole('button',{name,exact:true});
  const nested=d.getByLabel('Placed symbol script states',{exact:true});
  const states=async()=>JSON.parse((await nested.textContent())!);
  const prepare=async()=>{await button('Prepare script preview').click();await expect(status).toHaveText('Ready. No scripts have run.');};
  const step=async()=>{await button('Step script tick').click();await expect(status).toHaveText('Completed 1 script tick.');};
  await prepare();await step();
  await expect(nested).toHaveCount(0);
  await button('Close dialog').click();await open();
  await d.getByLabel('Run placed symbol frame scripts').check();
  await prepare();
  expect(await states()).toEqual([]);
  const expected=(shapeId:string,frame:number,count:number)=>({layerId:layer.id,shapeId,symbolId:'graphic',frame,state:{count,frame}});
  await step();
  expect(await states()).toEqual([expected('first',0,1),expected('fixed',1,1)]);
  await step();
  expect(await states()).toEqual([expected('first',1,2),expected('fixed',1,1)]);
  await button('Capture script checkpoint').click();
  await step();
  expect(await states()).toEqual([expected('first',0,1)]);
  await step();
  expect(await states()).toEqual([]);
  await button('Step script tick').click();
  await expect(status).toContainText('Graphic first, local frame 3: Error: child rejected');
  expect(await states()).toEqual([]);
  await expect(d.getByLabel('Script preview state')).toContainText('"scene": 1');
  await button('Replay retained script history').click();
  await expect(status).toContainText('Replay matched');
  await button('Restore script checkpoint').click();
  await expect(status).toContainText('Checkpoint restored');
  expect(await states()).toEqual([expected('first',1,2),expected('fixed',1,1)]);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
});

for(const mode of ['graphic','movie','nested movie'] as const)test(`Graphic child scripts follow sampled parent frames and authored child keys (${mode} parent)`,async({page})=>{
  const project=newProject();
  const movieParent=mode!=='graphic',nestedParent=mode==='nested movie';
  project.width=80;project.height=movieParent?50:40;project.duration=5;
  const layer=project.layers[0];
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const child:Vector={...art,kind:'symbol',id:'child',symbolId:'child-definition',instanceName:'Child'};
  const source='state.count=(typeof state.count==="number"?state.count:0)+1; state.frame=timeline.currentFrame;';
  project.symbols=[
    {id:'child-definition',name:'Child',width:20,height:20,shapes:[art],timeline:{duration:3,keys:[
      {frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]},
    ],frameScripts:[0,1,2].map(frame=>({frame,source}))}},
    {id:'parent',name:'Parent',width:20,height:20,shapes:[],timeline:{duration:4,keys:[],layers:[{
      id:'children',name:'Children',visible:true,locked:false,keys:[
        {frame:0,shapes:[child]},{frame:2,shapes:[]},{frame:3,shapes:[{...child,symbolPlayback:{mode:'single',firstFrame:2}}]},
      ],
    }]}},
  ];
  if(movieParent)project.symbols[1].timeline!.layers!.push({
    id:'movies',name:'Movies',visible:true,locked:false,
    keys:[{frame:0,shapes:[{...child,id:'independent',y:23,symbolPlayback:{mode:'movie',firstFrame:1}}]}],
  });
  const parentShape:Vector={...art,kind:'symbol',id:'first',symbolId:'parent',instanceName:'First'};
  if(movieParent)parentShape.symbolPlayback={mode:'movie',firstFrame:0};
  layer.keys=[{frame:0,shapes:[parentShape,{...parentShape,id:'second',instanceName:'Second',x:30,symbolPlayback:{mode:movieParent?'movie':'loop',firstFrame:1}}]}];
  if(nestedParent)layer.keys[0].shapes=layer.keys[0].shapes.map(placement=>{
    const id='outer-'+placement.id;
    project.symbols!.push({id,name:'Outer '+placement.id,width:20,height:20,
      shapes:[{...placement,id:'middle',instanceName:'Middle',x:0}]});
    return {...placement,symbolId:id,symbolPlayback:undefined};
  });
  if(movieParent)layer.keys.push({frame:1,shapes:[]},{frame:2,shapes:structuredClone(layer.keys[0].shapes)});
  project.frameScripts=[0,1,2,3,4].map(frame=>({frame,source:'if(input.fail)throw new Error("root rejected"); if(typeof input.jump==="number")timeline.gotoAndStop(input.jump);else timeline.stop();'}));
  await page.addInitScript(project=>{if(window===parent)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const original=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true}),status=d.getByRole('status');
  const button=(name:string)=>d.getByRole('button',{name,exact:true});
  const nested=async()=>JSON.parse((await d.getByLabel('Placed symbol script states').textContent())!);
  const complete=async()=>expect(status).toHaveText('Completed 1 script tick.');
  const seek=async(frame:number)=>{
    await d.getByLabel('Seek target frame').fill(String(frame));
    await button('Seek stopped and step').click();await complete();
  };
  const send=async(data:object)=>{
    await d.getByLabel('Script input JSON').fill(JSON.stringify(data));
    await button('Send input and step').click();
  };
  const pixels=(y=10)=>d.getByAltText('Script preview artwork').evaluate(async (node,y)=>{
    const img=node as HTMLImageElement;await img.decode();
    const context=document.createElement('canvas').getContext('2d')!;
    context.drawImage(img,0,0);
    return [10,40].map(x=>Array.from(context.getImageData(x,y,1,1).data));
  },y);
  await d.getByLabel('Run placed symbol frame scripts').check();
  await d.getByLabel('Render detached artwork').check();
  await button('Prepare script preview').click();await expect(status).toHaveText('Ready. No scripts have run.');
  const path=(id:string)=>id+(nestedParent?'/middle':'');
  const expected=(id:string,frame:number,count:number)=>({layerId:layer.id,shapeId:path(id)+'/children/child',symbolId:'child-definition',frame,state:{count,frame}});
  const red=[255,0,0,255],green=[0,255,0,255],blue=[0,0,255,255],white=[255,255,255,255];
  if(movieParent){
    const group=async()=> (await nested() as {shapeId:string;mode?:string}[]);
    const graphic=async()=> (await group()).filter(item=>item.mode!=='movie');
    const movies=async()=> (await group()).filter(item=>item.mode==='movie');
    const expectedMovies=(frame:number,count:number)=>['first','second'].map(id=>({
      ...expected(id,frame,count),shapeId:path(id)+'/movies/independent',mode:'movie',
    }));
    await button('Step script tick').click();await complete();
    expect(await graphic()).toEqual([expected('first',0,1)]);
    expect(await movies()).toEqual(expectedMovies(1,1));
    await expect.poll(pixels).toEqual([green,white]);
    await expect.poll(()=>pixels(33)).toEqual([blue,blue]);
    await button('Capture script checkpoint').click();
    await send({fail:true});await expect(status).toContainText('root rejected');
    expect(await movies()).toEqual(expectedMovies(1,1));
    await button('Step script tick').click();await complete();
    expect(await graphic()).toEqual([]);
    expect(await movies()).toEqual(expectedMovies(2,2));
    await expect.poll(pixels).toEqual([white,blue]);
    await expect.poll(()=>pixels(33)).toEqual([red,red]);
    await button('Step script tick').click();await complete();
    await button('Step script tick').click();await complete();
    expect(await graphic()).toEqual([expected('second',0,1)]);
    expect(await movies()).toEqual(expectedMovies(1,4));
    await expect.poll(pixels).toEqual([red,green]);
    await button('Replay retained script history').click();await expect(status).toContainText('Replay matched');
    expect(await movies()).toEqual(expectedMovies(1,4));
    await button('Restore script checkpoint').click();await expect(status).toContainText('Checkpoint restored');
    expect(await movies()).toEqual(expectedMovies(1,1));
    await seek(2);
    expect(await group()).toEqual([]);
    await expect.poll(pixels).toEqual([white,white]);
    await seek(3);
    expect(await graphic()).toEqual([expected('first',0,1),expected('second',1,1)]);
    expect(await movies()).toEqual(expectedMovies(1,1));
    await expect.poll(pixels).toEqual([red,green]);
    await expect.poll(()=>pixels(33)).toEqual([green,green]);
    expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
    return;
  }
  await button('Step script tick').click();await complete();
  expect(await nested()).toEqual([expected('first',0,1),expected('second',1,1)]);
  await expect.poll(pixels).toEqual([red,green]);
  await seek(2);
  expect(await nested()).toEqual([expected('first',1,2)]);
  await expect.poll(pixels).toEqual([green,white]);
  await button('Capture script checkpoint').click();
  await send({fail:true});await expect(status).toContainText('root rejected');
  expect(await nested()).toEqual([expected('first',1,2)]);
  await send({jump:2});await complete();
  expect(await nested()).toEqual([]);
  await expect.poll(pixels).toEqual([white,blue]);
  await button('Step script tick').click();await complete();
  expect(await nested()).toEqual([expected('second',2,1)]);
  await seek(4);
  expect(await nested()).toEqual([expected('first',2,1),expected('second',0,1)]);
  await expect.poll(pixels).toEqual([blue,red]);
  await button('Replay retained script history').click();await expect(status).toContainText('Replay matched');
  expect(await nested()).toEqual([expected('first',2,1),expected('second',0,1)]);
  await button('Restore script checkpoint').click();await expect(status).toContainText('Checkpoint restored');
  expect(await nested()).toEqual([expected('first',1,2)]);
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
});

for(const route of ['Movie','deep Movie','deep Graphic','mixed Graphic and Movie','nested scene Movie','fixed Graphic and nested Movie'] as const)test(`Button scripts under ${route} parents follow resolved frame poses and release lifetimes`,async({page})=>{
  const project=newProject();
  const fixed=route==='fixed Graphic and nested Movie';
  const deep=route!=='Movie',graphic=route==='deep Graphic',mixed=route==='mixed Graphic and Movie'||fixed;
  const twoMovies=route==='nested scene Movie'||fixed;
  project.width=80;project.height=40;
  if(graphic)project.duration=10;
  if(twoMovies)project.duration=2;
  const layer=project.layers[0];
  const art:Vector={id:'art',kind:'rectangle',x:0,y:0,width:20,height:20,rotation:0,fill:'#ff0000',stroke:'#000000',strokeWidth:0,points:[]};
  const child:Vector={...art,kind:'symbol',id:'child',instanceName:'Child',symbolId:'button'};
  const stateSource='state.seen=timeline.currentFrame; if(input.buttonActivation)state.activated=true;';
  project.symbols=[
    {id:'button',name:'Button',width:20,height:20,shapes:[art],buttonStates:{up:0,over:1,down:2,hit:3},timeline:{duration:4,
      keys:[{frame:1,shapes:[{...art,fill:'#00ff00'}]},{frame:2,shapes:[{...art,fill:'#0000ff'}]},{frame:3,shapes:[art]}],
      frameScripts:[0,1,2].map(frame=>({frame,source:stateSource})).concat({frame:3,source:'throw new Error("Hit must stay idle");'}),
    }},
    {id:'movie-wrapper',name:'Movie wrapper',width:20,height:20,shapes:[],timeline:{duration:5,keys:[],layers:[{
      id:'controls',name:'Controls',visible:true,locked:false,
      keys:[{frame:0,shapes:[child]},{frame:3,shapes:[]},{frame:4,shapes:[child]}],
    }]}},
  ];
  if(deep){
    project.symbols.push({id:'button-bridge',name:'Button bridge',width:20,height:20,shapes:[child]});
    for(const key of project.symbols[1].timeline!.layers![0].keys)
      if(key.shapes.length)key.shapes=[{...child,id:'bridge',instanceName:'Bridge',symbolId:'button-bridge'}];
  }
  if(twoMovies){
    const control=project.symbols[1].timeline!.layers![0];
    for(const key of control.keys)for(const shape of key.shapes)shape.symbolPlayback={mode:'movie',firstFrame:1};
    control.keys.splice(1,0,{frame:1,shapes:[{...control.keys[0].shapes[0],x:3}]});
    const marker={...art,id:'phase',width:5,height:5,y:25};
    project.symbols.at(-1)!.timeline={duration:2,keys:[],layers:[{id:'phase',name:'Phase',visible:true,locked:false,
      keys:[{frame:0,shapes:[marker]},{frame:1,shapes:[{...marker,fill:'#0000ff'}]}]}]};
  }
  const mode=graphic?'loop':'movie';
  const wrapper:Vector={...art,kind:'symbol',id:'first',instanceName:'First',symbolId:'movie-wrapper',symbolPlayback:{mode,firstFrame:0}};
  layer.keys=[{frame:0,shapes:[wrapper,{...wrapper,id:'second',instanceName:'Second',x:30,symbolPlayback:{mode,firstFrame:1}}]}];
  if(mixed)layer.keys[0].shapes=layer.keys[0].shapes.map(movie=>{
    const id='graphic-'+movie.id;
    const placement={...movie,id:'movie',instanceName:'Movie',x:0};
    project.symbols!.push({id,name:'Graphic '+movie.id,width:20,height:20,
      shapes:fixed?[]:[placement],timeline:{duration:2,keys:fixed?[{frame:1,shapes:[placement]}]:[]}});
    return {...movie,symbolId:id,symbolPlayback:fixed?{mode:'single',firstFrame:1}:{mode:'loop',firstFrame:0}};
  });
  if(twoMovies)layer.keys.push({frame:1,shapes:structuredClone(layer.keys[0].shapes)});
  project.frameScripts=twoMovies?[0,1].map(frame=>({frame,source:'timeline.stop();'})):
    [{frame:0,source:graphic?'timeline.play();':'timeline.stop();'}];
  await page.addInitScript(project=>{if(window===window.top)localStorage.setItem('splash-recovery-v1',JSON.stringify({project,folder:null,manifest:null}));},project);
  await page.goto('/');
  await page.getByRole('button',{name:'Recover changes',exact:true}).click();
  const original=await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'));
  await page.getByRole('button',{name:'Control',exact:true}).click();
  await page.getByRole('button',{name:'Preview saved scripts…',exact:true}).click();
  const d=page.getByRole('dialog',{name:'Preview saved scripts',exact:true}),status=d.getByRole('status');
  const button=(name:string)=>d.getByRole('button',{name,exact:true});
  const press=d.getByLabel('Script button press');
  const nested=async()=>JSON.parse((await d.getByLabel('Placed symbol script states').textContent())!);
  const done=async()=>expect(status).toHaveText('Completed 1 script tick.');
  const step=async()=>{await button('Step script tick').click();await done();};
  const capture=async(type:string)=>{
    await d.getByRole('application',{name:'Script pointer target'}).evaluate((host,type)=>{
      const img=host.querySelector('img')!,rect=img.getBoundingClientRect();
      host.dispatchEvent(new PointerEvent(type,{pointerId:19,button:0,bubbles:true,
        clientX:rect.left+rect.width*10/img.naturalWidth,clientY:rect.top+rect.height*10/img.naturalHeight}));
    },type);
  };
  const pointer=async(type:string)=>{
    await capture(type);
    await button('Deliver next pointer and step').click();await done();
  };
  const pixels=()=>d.getByAltText('Script preview artwork').evaluate(async node=>{
    const img=node as HTMLImageElement;await img.decode();const ctx=document.createElement('canvas').getContext('2d')!;
    ctx.drawImage(img,0,0);return [10,40].map(x=>Array.from(ctx.getImageData(x,10,1,1).data));
  });
  const expected=(id:string,buttonVisual:string,frame:number,activated=false)=>({
    layerId:layer.id,shapeId:id+(mixed?'/movie':'')+'/controls/'+(deep?'bridge/':'')+'child',symbolId:'button',frame,mode:'button',buttonVisual,
    state:{seen:frame,...(activated?{activated:true}:{})},
  });
  const red=[255,0,0,255],green=[0,255,0,255],blue=[0,0,255,255],white=[255,255,255,255];
  await d.getByLabel('Run placed symbol frame scripts').check();
  await d.getByLabel('Render detached artwork').check();
  await button('Prepare script preview').click();await expect(status).toHaveText('Ready. No scripts have run.');
  await d.getByLabel('Capture pointers on artwork').check();
  await d.getByLabel('Include button target for new pointers').check();
  await pointer('pointerdown');
  expect(await nested()).toEqual([expected('first','down',2),expected('second','up',0)]);
  await expect.poll(pixels).toEqual([blue,red]);
  if(twoMovies)await expect.poll(()=>d.getByAltText('Script preview artwork').evaluate(async node=>{
    const image=node as HTMLImageElement;await image.decode();
    const ctx=document.createElement('canvas').getContext('2d')!;ctx.drawImage(image,0,0);
    return [[1,10],[4,27]].map(([x,y])=>Array.from(ctx.getImageData(x,y,1,1).data));
  })).toEqual([white,red]);
  await pointer('pointerup');
  expect(await nested()).toEqual([expected('first','over',1,true)]);
  await expect.poll(pixels).toEqual([green,white]);
  await button('Capture script checkpoint').click();
  if(twoMovies&&!fixed){
    // Keep the next nested frame pending until the user cancels the host step.
    await capture('pointerdown');
    await withPendingScriptEngine(page,()=>button('Deliver next pointer and step').click(),()=>button('Cancel script preview').click());
    await expect(status).toContainText(/cancel|abort/i);
    expect(await nested()).toEqual([expected('first','over',1,true)]);
    await expect.poll(pixels).toEqual([green,white]);
    await expect(d.getByLabel('Captured input order')).toContainText('1 captured');
    await button('Deliver next pointer and step').click();await done();
  }else await pointer('pointerdown');
  expect(await nested()).toEqual([]);
  await expect(press).toHaveText('No button press active.');
  await expect.poll(pixels).toEqual([white,red]);
  await step();await step();
  await expect.poll(pixels).toEqual([red,red]);
  await pointer('pointerup');
  expect(await nested()).toEqual([expected('first','over',1),expected('second','up',0)]);
  await expect.poll(pixels).toEqual([green,red]);
  await button('Replay retained script history').click();await expect(status).toContainText('Replay matched');
  await button('Restore script checkpoint').click();await expect(status).toContainText('Checkpoint restored');
  expect(await nested()).toEqual([expected('first','over',1,true)]);
  if(twoMovies){
    await d.getByLabel('Seek target frame').fill('2');
    await button('Seek stopped and step').click();await done();
    await expect.poll(pixels).toEqual([white,red]);
  }
  expect(await page.evaluate(()=>localStorage.getItem('splash-recovery-v1'))).toBe(original);
});

